/* ============ player-sound.js ============ */

(function () {
    'use strict';

    var MUTE_KEY = 'quizify_sound_muted';

    var ctx = null;
    var muted = false;
    var _lastTickSecond = null;

    try {
        muted = window.localStorage.getItem(MUTE_KEY) === '1';
    } catch (e) {
        muted = false;
    }

    function supported() {
        return typeof (window.AudioContext || window.webkitAudioContext) === 'function';
    }

    function ensureCtx() {
        if (muted || !supported()) return null;
        if (!ctx) {
            var Ctor = window.AudioContext || window.webkitAudioContext;
            try {
                ctx = new Ctor();
            } catch (e) {
                ctx = null;
                return null;
            }
        }
        if (ctx.state === 'suspended' && typeof ctx.resume === 'function') {
            ctx.resume().catch(function () { });
        }
        return ctx;
    }

    function unlock() {
        ensureCtx();
    }
    document.addEventListener('pointerdown', unlock, { once: false, passive: true });
    document.addEventListener('keydown', unlock, { once: false, passive: true });

    function tone(freq, start, dur, type, peak) {
        var ac = ensureCtx();
        if (!ac) return;
        var t0 = ac.currentTime + start;
        var osc = ac.createOscillator();
        var gain = ac.createGain();
        osc.type = type || 'sine';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.0001, t0);
        gain.gain.exponentialRampToValueAtTime(peak || 0.18, t0 + 0.012);
        gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
        osc.connect(gain);
        gain.connect(ac.destination);
        osc.start(t0);
        osc.stop(t0 + dur + 0.02);
    }

    function playCorrect() {
        if (muted) return;
        tone(660, 0, 0.14, 'sine', 0.18);
        tone(990, 0.11, 0.20, 'sine', 0.18);
    }

    function playWrong() {
        if (muted) return;
        tone(196, 0, 0.26, 'sawtooth', 0.12);
        tone(146, 0.05, 0.26, 'sawtooth', 0.10);
    }

    function playTick() {
        if (muted) return;
        tone(880, 0, 0.05, 'square', 0.06);
    }

    function tickFromRemaining(remaining) {
        if (muted) return;
        var sec = Math.ceil(remaining);
        if (sec <= 0 || sec > 5) return;
        if (sec === _lastTickSecond) return;
        _lastTickSecond = sec;
        playTick();
    }

    function resetTick() {
        _lastTickSecond = null;
    }

    function isMuted() {
        return muted;
    }

    function setMuted(value) {
        muted = !!value;
        try {
            window.localStorage.setItem(MUTE_KEY, muted ? '1' : '0');
        } catch (e) { }
        if (!muted) ensureCtx();
        return muted;
    }

    function toggleMute() {
        return setMuted(!muted);
    }

    window.QuizifyPlayerSound = {
        playCorrect: playCorrect,
        playWrong: playWrong,
        playTick: playTick,
        tickFromRemaining: tickFromRemaining,
        resetTick: resetTick,
        isMuted: isMuted,
        setMuted: setMuted,
        toggleMute: toggleMute
    };
})();


/* ============ player-a11y.js ============ */

(function () {
    'use strict';

    var A11Y_KEY = 'quizify_a11y';

    var enabled = false;
    try {
        enabled = window.localStorage.getItem(A11Y_KEY) === '1';
    } catch (e) {
        enabled = false;
    }

    function apply() {
        var root = document.documentElement;
        if (!root) return;
        if (enabled) root.classList.add('a11y');
        else root.classList.remove('a11y');
    }

    function isEnabled() {
        return enabled;
    }

    function toggle() {
        enabled = !enabled;
        try {
            window.localStorage.setItem(A11Y_KEY, enabled ? '1' : '0');
        } catch (e) { }
        apply();
        return enabled;
    }

    apply();

    window.QuizifyA11y = {
        isEnabled: isEnabled,
        toggle: toggle,
        STORAGE_KEY: A11Y_KEY
    };
})();


