(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var state = pu.state;

    function _renderHeroAndOrbits(players, data) {
        var hero = document.getElementById('pl-mega-avatar');
        var nameEl = document.getElementById('pl-mega-name');
        var alsoEl = document.getElementById('pl-also');
        var orbits = document.getElementById('player-list');
        var metaEl = document.getElementById('pl-meta');
        if (!orbits) return;

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var myName = state.playerName || '';
        var me = null;
        var others = [];
        for (var i = 0; i < players.length; i++) {
            var p = players[i];
            if (p && p.name === myName) me = p;
            else others.push(p);
        }

        if (hero && nameEl) {
            var initial = (myName || '?').charAt(0).toUpperCase();
            var color = (me && me.color) || state.playerColor || 'var(--color-accent-primary)';
            hero.textContent = initial;
            hero.style.background = color;
            hero.style.boxShadow = '0 0 0 6px ' + _hexWithAlpha(color, 0.22);
            nameEl.textContent = myName || '…';
        }

        if (metaEl) {
            var bits = [];
            var diffIcons = { 'easy': '🌱', 'medium': '🎯', 'hard': '🔥' };
            var diff = data && (data.difficulty || data.game_difficulty);
            if (diff && diffIcons[diff]) {
                bits.push(diffIcons[diff] + ' ' + _i18nSpan('difficulties.' + diff, t));
            }
            var total = data && (data.total_rounds || data.num_rounds);
            if (total) {
                bits.push(_i18nSpan('game.questionsCount', t, { count: Number(total) }));
            }
            metaEl.innerHTML = bits.length
                ? bits.join(' · ')
                : _i18nSpan('lobby.gameLobby', t);
        }

        if (alsoEl) {
            var alsoKey = 'lobby.aloneWaiting';
            var alsoParams = null;
            if (others.length > 0) {
                alsoKey = 'lobby.also';
                alsoParams = { count: others.length };
            }
            alsoEl.setAttribute('data-i18n', alsoKey);
            if (alsoParams) {
                alsoEl.setAttribute('data-i18n-params', JSON.stringify(alsoParams));
            } else {
                alsoEl.removeAttribute('data-i18n-params');
            }
            alsoEl.textContent = t(alsoKey, alsoParams);
        }

        orbits.innerHTML = others.map(function (p) {
            var initial = (p.name || '?').charAt(0).toUpperCase();
            var bg = p.color || '#A89E89';
            var awayClass = p.connected === false ? ' is-away' : '';
            var hostClass = p.is_admin ? ' is-host' : '';
            var hostMark = p.is_admin ? '<span class="pl-orbit-host" aria-hidden="true">👑</span>' : '';
            return '<div class="pl-orbit' + awayClass + hostClass + '" data-player="' + _escape(p.name) + '">' +
                '<span class="pl-orbit-av" style="background:' + bg + '">' + _escape(initial) + '</span>' +
                '<span class="pl-orbit-nm">' + _escape(p.name || '') + '</span>' +
                hostMark +
            '</div>';
        }).join('');
    }

    function renderAllTime(standing, elementId) {
        var el = document.getElementById(elementId || 'pl-alltime');
        if (!el) return;
        if (!standing || !standing.total_players) {
            el.textContent = '';
            el.removeAttribute('data-i18n');
            el.removeAttribute('data-i18n-params');
            el.classList.add('hidden');
            return;
        }
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var key = _allTimeKey();
        var params = {
            rank: standing.rank,
            total: standing.total_players,
            wins: standing.wins || 0,
            games: standing.games_played || 0
        };
        el.setAttribute('data-i18n', key);
        el.setAttribute('data-i18n-params', JSON.stringify(params));
        el.textContent = t(key, params);
        el.classList.remove('hidden');
    }

    function _allTimeKey() {
        return 'lobby.allTime';
    }

    function _i18nSpan(key, t, params) {
        var attr = params
            ? ' data-i18n-params="' + _escape(JSON.stringify(params)) + '"'
            : '';
        return '<span data-i18n="' + _escape(key) + '"' + attr + '>'
            + _escape(t(key, params)) + '</span>';
    }

    function _escape(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }
    function _hexWithAlpha(hex, alpha) {
        if (typeof hex !== 'string' || !hex.startsWith('#') || hex.length !== 7) return hex;
        var r = parseInt(hex.slice(1, 3), 16);
        var g = parseInt(hex.slice(3, 5), 16);
        var b = parseInt(hex.slice(5, 7), 16);
        return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
    }

    function renderLobby(data) {
        var players = data.players || [];
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        var countBadgeEl = document.getElementById('player-count-badge');
        if (countBadgeEl) countBadgeEl.textContent = players.length;

        var diffBadgeEl = document.getElementById('lobby-difficulty-badge');
        if (diffBadgeEl) {
            var diffIcons = { 'easy': '🌱', 'medium': '🎯', 'hard': '🔥' };
            var diff = data.difficulty || data.game_difficulty || '';
            if (diff && diffIcons[diff]) {
                diffBadgeEl.innerHTML = diffIcons[diff] + ' '
                    + _i18nSpan('difficulties.' + diff, t);
                diffBadgeEl.classList.remove('hidden');
            } else {
                diffBadgeEl.classList.add('hidden');
                diffBadgeEl.textContent = '';
            }
        }

        var playersSummaryEl = document.getElementById('players-summary');
        if (playersSummaryEl) playersSummaryEl.textContent = players.length;

        var playersEmptyEl = document.getElementById('players-empty');
        if (playersEmptyEl) playersEmptyEl.classList.toggle('hidden', players.length > 0);

        _renderHeroAndOrbits(players, data);

        updateAdminControls(players);

        if (data.join_url) {
            setupInviteSection(data.join_url);
        }
    }

    function handlePlayerJoined(data) {
        var players = data.players || [];

        var countBadgeEl = document.getElementById('player-count-badge');
        if (countBadgeEl) countBadgeEl.textContent = players.length;

        var playersSummaryEl = document.getElementById('players-summary');
        if (playersSummaryEl) playersSummaryEl.textContent = players.length;

        var playersEmptyEl = document.getElementById('players-empty');
        if (playersEmptyEl) playersEmptyEl.classList.toggle('hidden', players.length > 0);

        _renderHeroAndOrbits(players, data);
        updateAdminControls(players);
    }

    function handlePlayerLeft(data) {
        var players = data.players || [];

        var countBadgeEl = document.getElementById('player-count-badge');
        if (countBadgeEl) countBadgeEl.textContent = players.length;

        var playersSummaryEl = document.getElementById('players-summary');
        if (playersSummaryEl) playersSummaryEl.textContent = players.length;

        var playersEmptyEl = document.getElementById('players-empty');
        if (playersEmptyEl) playersEmptyEl.classList.toggle('hidden', players.length > 0);

        _renderHeroAndOrbits(players, data);
        updateAdminControls(players);
    }

    var currentJoinUrl = null;

    function setupInviteSection(joinUrl) {
        if (!joinUrl) return;
        currentJoinUrl = joinUrl;

        pu.generateQR('player-qr-code', joinUrl);

        var dashLink = document.getElementById('player-dashboard-url');
        if (dashLink) {
            dashLink.href = window.location.origin + '/quizify/dashboard';
        }

        var qrContainer = document.getElementById('player-qr-code');
        if (qrContainer) {
            qrContainer.onclick = openQRModal;
            qrContainer.onkeydown = function (e) {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    openQRModal();
                }
            };
        }
    }

    function openQRModal() {
        if (!currentJoinUrl) return;

        var modal = document.getElementById('qr-modal');
        var modalCode = document.getElementById('qr-modal-code');
        if (!modal || !modalCode) return;

        modalCode.innerHTML = '';
        if (typeof QRCode !== 'undefined') {
            new QRCode(modalCode, {
                text: currentJoinUrl,
                width: 256,
                height: 256,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.M
            });
        }

        modal.classList.remove('hidden');
        document.body.style.overflow = 'hidden';

        var closeBtn = document.getElementById('qr-modal-close');
        if (closeBtn) closeBtn.focus();
    }

    function closeQRModal() {
        var modal = document.getElementById('qr-modal');
        if (modal) {
            modal.classList.add('hidden');
            document.body.style.overflow = '';
        }
    }

    function setupQRModal() {
        var modal = document.getElementById('qr-modal');
        var backdrop = modal ? modal.querySelector('.qr-modal-backdrop') : null;
        var closeBtn = document.getElementById('qr-modal-close');

        if (backdrop) backdrop.addEventListener('click', closeQRModal);
        if (closeBtn) closeBtn.addEventListener('click', closeQRModal);

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && modal && !modal.classList.contains('hidden')) {
                closeQRModal();
            }
        });
    }

    function openInviteModal() {
        if (!currentJoinUrl) return;

        var modal = document.getElementById('invite-modal');
        var modalCode = document.getElementById('invite-modal-code');
        var urlInput = document.getElementById('invite-modal-url');
        if (!modal || !modalCode) return;

        modalCode.innerHTML = '';
        if (typeof QRCode !== 'undefined') {
            new QRCode(modalCode, {
                text: currentJoinUrl,
                width: 256,
                height: 256,
                colorDark: '#000000',
                colorLight: '#ffffff',
                correctLevel: QRCode.CorrectLevel.M
            });
        }

        if (urlInput) urlInput.value = currentJoinUrl;

        modal.classList.remove('hidden');
        document.body.style.overflow = 'hidden';

        var closeBtn = document.getElementById('invite-modal-close');
        if (closeBtn) closeBtn.focus();
    }

    function closeInviteModal() {
        var modal = document.getElementById('invite-modal');
        if (modal) {
            modal.classList.add('hidden');
            document.body.style.overflow = '';
        }
    }

    function copyJoinUrl() {
        var urlInput = document.getElementById('invite-modal-url');
        var feedback = document.getElementById('invite-copy-feedback');
        if (!urlInput || !currentJoinUrl) return;

        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(currentJoinUrl).then(function () {
                showCopyFeedback(feedback);
            }).catch(function () {
                fallbackCopy(urlInput, feedback);
            });
        } else {
            fallbackCopy(urlInput, feedback);
        }
    }

    function fallbackCopy(urlInput, feedback) {
        urlInput.select();
        urlInput.setSelectionRange(0, 99999);
        try {
            document.execCommand('copy');
            showCopyFeedback(feedback);
        } catch (e) {
            console.warn('[Quizify] Copy failed:', e);
        }
    }

    function showCopyFeedback(feedback) {
        if (!feedback) return;
        feedback.classList.remove('hidden');
        setTimeout(function () { feedback.classList.add('hidden'); }, 2000);
    }

    function setupInviteModal() {
        var modal = document.getElementById('invite-modal');
        var backdrop = modal ? modal.querySelector('.invite-modal-backdrop') : null;
        var closeBtn = document.getElementById('invite-modal-close');
        var inviteBtn = document.getElementById('invite-players-btn');
        var copyBtn = document.getElementById('invite-copy-btn');

        if (backdrop) backdrop.addEventListener('click', closeInviteModal);
        if (closeBtn) closeBtn.addEventListener('click', closeInviteModal);
        if (inviteBtn) inviteBtn.addEventListener('click', openInviteModal);
        if (copyBtn) copyBtn.addEventListener('click', copyJoinUrl);

        document.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && modal && !modal.classList.contains('hidden')) {
                closeInviteModal();
            }
        });
    }

    function updateAdminControls(players) {
        var adminControls = document.getElementById('admin-controls');
        var lobbyStatus = document.getElementById('lobby-status');
        if (!adminControls) return;

        var currentPlayer = null;
        if (players && Array.isArray(players)) {
            for (var i = 0; i < players.length; i++) {
                if (players[i].name === state.playerName) {
                    currentPlayer = players[i];
                    break;
                }
            }
        }

        var playerIsAdmin;
        if (currentPlayer) {
            playerIsAdmin = currentPlayer.is_admin === true;
            state.isAdmin = playerIsAdmin;
        } else {
            playerIsAdmin = false;
        }

        if (playerIsAdmin) {
            adminControls.classList.remove('hidden');
            if (lobbyStatus) lobbyStatus.classList.add('hidden');

            var startBtn = document.getElementById('start-game-btn');
            if (startBtn) {
                startBtn.disabled = players.length < 1;
            }
        } else {
            adminControls.classList.add('hidden');
            if (lobbyStatus) lobbyStatus.classList.remove('hidden');
        }
    }

    function setupAdminControls(sendFn) {
        var startBtn = document.getElementById('start-game-btn');
        if (startBtn) {
            startBtn.addEventListener('click', function () {
                var t = (window.QuizifyI18n && window.QuizifyI18n.t)
                    || function (k) { return k; };
                if (!state.ws || state.ws.readyState !== WebSocket.OPEN) {
                    var pu = window.QuizifyPlayerUtils;
                    if (pu && pu.showToast) {
                        pu.showToast(t('connection.reconnecting'), 2500);
                    }
                    return;
                }

                startBtn.disabled = true;
                startBtn.innerHTML = '<span class="btn-icon" aria-hidden="true">🎉</span><span>'
                    + t('admin.starting') + '</span>';

                sendFn('start_game', {});
            });
        }
    }

    function init(sendFn) {
        setupQRModal();
        setupInviteModal();
        setupAdminControls(sendFn);
        pu.setupCollapsibles();
    }

    window.QuizifyPlayerLobby = {
        init: init,
        renderLobby: renderLobby,
        renderAllTime: renderAllTime,
        handlePlayerJoined: handlePlayerJoined,
        handlePlayerLeft: handlePlayerLeft,
        setupInviteSection: setupInviteSection,
        updateAdminControls: updateAdminControls,
        closeInviteModal: closeInviteModal
    };

})();


/* ============ player-team.js ============ */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var state = pu.state;

    function t(key, params) {
        var i18n = window.QuizifyI18n;
        return (i18n && i18n.t) ? i18n.t(key, params) : key;
    }

    function $(id) { return document.getElementById(id); }

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    var TEAM_COLORS = {
        coral: '#E88A7F', sage: '#8FA98A', sky: '#7FA8C9',
        sun: '#E2B65C', mauve: '#A98FA9', brick: '#B4705C'
    };

    function colorOf(team) {
        return (team && TEAM_COLORS[team.color]) || '#A89E89';
    }

    var teams = [];
    var myTeamId = null;
    var send = null;
    var pickOpen = false;
    var lockTimer = null;

    function myTeam() {
        for (var i = 0; i < teams.length; i++) {
            if (teams[i].team_id === myTeamId) return teams[i];
        }
        return null;
    }

    function isTeamMode() {
        return !!myTeamId;
    }

    function renderLobby() {
        var section = $('team-section');
        if (!section) return;

        var mine = myTeam();
        var ask = $('team-ask');
        var pick = $('team-pick');
        var mineEl = $('team-mine');

        if (mine) {
            if (ask) ask.classList.add('hidden');
            if (pick) pick.classList.add('hidden');
            if (mineEl) mineEl.classList.remove('hidden');
            var dot = $('team-mine-dot');
            if (dot) dot.style.background = colorOf(mine);
            var nameEl = $('team-mine-name');
            if (nameEl) nameEl.textContent = mine.name;
            var membersEl = $('team-mine-members');
            if (membersEl) {
                var others = (mine.members || []).filter(function (n) {
                    return n !== state.playerName;
                });
                membersEl.textContent = others.length
                    ? others.join(' · ')
                    : t('teams.waitingForTeammate');
            }
            return;
        }

        if (mineEl) mineEl.classList.add('hidden');
        if (ask) ask.classList.toggle('hidden', pickOpen);
        if (pick) pick.classList.toggle('hidden', !pickOpen);
        if (!pickOpen) return;

        var list = $('team-list');
        if (list) {
            list.innerHTML = teams.map(function (team) {
                return '<button type="button" class="qz-team-item" data-team="' + esc(team.team_id) + '">' +
                    '<span class="qz-team-itemDot" style="background:' + colorOf(team) + '"></span>' +
                    '<span class="qz-team-itemName">' + esc(team.name) + '</span>' +
                    '<span class="qz-team-itemMembers">' + esc((team.members || []).join(' · ')) + '</span>' +
                    '<span class="qz-team-itemJoin">' + esc(t('teams.joinTeam')) + '</span>' +
                '</button>';
            }).join('');
        }
        var empty = $('team-empty');
        if (empty) empty.classList.toggle('hidden', teams.length > 0);
    }

    function showNote(message) {
        var note = $('team-note');
        if (!note) return;
        note.textContent = message;
        note.classList.remove('hidden');
    }

    function openNameRow(show) {
        var row = $('team-name-row');
        var hint = $('team-name-hint');
        var openBtn = $('team-open-btn');
        if (row) row.classList.toggle('hidden', !show);
        if (hint) hint.classList.toggle('hidden', !show);
        if (openBtn) openBtn.classList.toggle('hidden', show);
        if (show) {
            var input = $('team-name-input');
            if (input) { input.value = ''; input.focus(); }
        }
    }

    function setupLobby(sendFn) {
        send = sendFn;

        var aloneBtn = $('team-alone-btn');
        if (aloneBtn) {
            aloneBtn.addEventListener('click', function () {
                pickOpen = false;
                var section = $('team-section');
                if (section) section.classList.add('hidden');
            });
        }

        var togetherBtn = $('team-together-btn');
        if (togetherBtn) {
            togetherBtn.addEventListener('click', function () {
                pickOpen = true;
                renderLobby();
            });
        }

        var openBtn = $('team-open-btn');
        if (openBtn) openBtn.addEventListener('click', function () { openNameRow(true); });

        var cancelBtn = $('team-name-cancel');
        if (cancelBtn) cancelBtn.addEventListener('click', function () { openNameRow(false); });

        var confirmBtn = $('team-name-confirm');
        if (confirmBtn) {
            confirmBtn.addEventListener('click', function () {
                var input = $('team-name-input');
                send('create_team', { name: input ? input.value.trim() : '' });
                openNameRow(false);
            });
        }

        var input = $('team-name-input');
        if (input) {
            input.addEventListener('keydown', function (e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    if (confirmBtn) confirmBtn.click();
                }
            });
        }

        var list = $('team-list');
        if (list) {
            list.addEventListener('click', function (e) {
                var item = e.target.closest ? e.target.closest('.qz-team-item') : null;
                if (!item) return;
                send('join_team', { team_id: item.getAttribute('data-team') });
            });
        }

        var leaveBtn = $('team-leave-btn');
        if (leaveBtn) {
            leaveBtn.addEventListener('click', function () { send('leave_team', {}); });
        }
    }

    function handleTeamsUpdate(msg) {
        teams = msg.teams || [];
        var found = null;
        for (var i = 0; i < teams.length; i++) {
            if ((teams[i].members || []).indexOf(state.playerName) !== -1) {
                found = teams[i];
                break;
            }
        }
        var hadTeam = myTeamId !== null;
        myTeamId = found ? found.team_id : null;
        if (hadTeam && !found) {
            pickOpen = true;
            showNote(t('teams.dissolved'));
        }
        renderLobby();
        renderChip();
    }

    function handleTeamJoined(msg) {
        var team = msg.team || {};
        myTeamId = team.team_id || null;
        var known = false;
        for (var i = 0; i < teams.length; i++) {
            if (teams[i].team_id === myTeamId) { teams[i] = team; known = true; break; }
        }
        if (!known && myTeamId) teams.push(team);
        var note = $('team-note');
        if (note) note.classList.add('hidden');
        renderLobby();
        renderChip();
    }

    function handleTeamLeft() {
        myTeamId = null;
        pickOpen = true;
        renderLobby();
        renderChip();
    }

    function handleTeamError() {
        showNote(t('teams.closedAfterStart'));
        pickOpen = false;
        renderLobby();
    }

    function renderChip(setBy) {
        var chip = $('team-chip');
        if (!chip) return;
        var mine = myTeam();
        if (!mine) {
            chip.classList.add('hidden');
            return;
        }
        chip.classList.remove('hidden');
        var dot = $('team-chip-dot');
        if (dot) dot.style.background = colorOf(mine);
        var nameEl = $('team-chip-name');
        if (nameEl) nameEl.textContent = mine.name;
        var setEl = $('team-chip-set');
        if (setEl) {
            setEl.textContent = setBy ? t('teams.standingAnswer', { name: setBy }) : '';
        }
    }

    function clearDots() {
        var buttons = document.querySelectorAll('#answer-buttons .answer-btn');
        for (var i = 0; i < buttons.length; i++) {
            buttons[i].classList.remove('has-team-answer');
            var old = buttons[i].querySelector('.qz-team-dots');
            if (old) old.remove();
        }
    }

    function handleTeamAnswer(msg) {
        clearDots();
        var buttons = document.querySelectorAll('#answer-buttons .answer-btn');
        var mine = myTeam();
        for (var i = 0; i < buttons.length; i++) {
            if (parseInt(buttons[i].dataset.index, 10) !== msg.answer_index) continue;
            buttons[i].classList.add('has-team-answer');
            var wrap = document.createElement('span');
            wrap.className = 'qz-team-dots';
            var members = msg.members || (mine && mine.members) || [];
            wrap.innerHTML = members.map(function (name) {
                var initial = (name || '?').charAt(0).toUpperCase();
                var isSetter = name === msg.set_by;
                return '<span class="qz-team-dot' + (isSetter ? ' is-setter' : '') + '"' +
                    ' style="background:' + colorOf(mine) + '" title="' + esc(name) + '">' +
                    esc(initial) + '</span>';
            }).join('');
            buttons[i].appendChild(wrap);
        }
        renderChip(msg.set_by);
        applyLock(msg.lock_seconds || 0);
    }

    function applyLock(seconds) {
        var buttons = document.querySelectorAll('#answer-buttons .answer-btn');
        if (lockTimer) { clearTimeout(lockTimer); lockTimer = null; }
        if (seconds <= 0) return;

        for (var i = 0; i < buttons.length; i++) {
            buttons[i].disabled = true;
            buttons[i].classList.add('is-team-locked');
        }
        lockTimer = setTimeout(function () {
            var btns = document.querySelectorAll('#answer-buttons .answer-btn');
            for (var j = 0; j < btns.length; j++) {
                btns[j].disabled = false;
                btns[j].classList.remove('is-team-locked');
            }
            lockTimer = null;
        }, seconds * 1000);
    }

    function resetRound() {
        if (lockTimer) { clearTimeout(lockTimer); lockTimer = null; }
        clearDots();
        renderChip();
    }

    window.QuizifyPlayerTeam = {
        setupLobby: setupLobby,
        isTeamMode: isTeamMode,
        myTeam: myTeam,
        handleTeamsUpdate: handleTeamsUpdate,
        handleTeamJoined: handleTeamJoined,
        handleTeamLeft: handleTeamLeft,
        handleTeamError: handleTeamError,
        handleTeamAnswer: handleTeamAnswer,
        renderChip: renderChip,
        resetRound: resetRound
    };

})();


/* ============ player-reveal.js ============ */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var game = window.QuizifyPlayerGame;
    var state = pu.state;

    function t(key, params) {
        if (typeof window.t === 'function') return window.t(key, params);
        return key;
    }

    var _currentQuestionId = '';
    var _flaggedThisRound = false;

    var _prevRanks = null;
    var _deltaBase = null;
    var _lastStandings = null;
    var _scoringStatus = null;

    function resetRankMemo() {
        _prevRanks = null;
        _deltaBase = null;
        _shownScores = {};
    }

    var _shownScores = {};

    function updateRevealView(data) {
        var players = data.players || [];
        var allAnswers = data.all_answers || [];

        _currentQuestionId = data.question_id || '';
        _flaggedThisRound = false;
        _resetFlagButton();

        var myAnswerEntry = null;
        for (var i = 0; i < allAnswers.length; i++) {
            if (allAnswers[i].player_name === state.playerName) {
                myAnswerEntry = allAnswers[i];
                break;
            }
        }

        var currentPlayer = null;
        for (var j = 0; j < players.length; j++) {
            if (players[j].name === state.playerName) {
                currentPlayer = players[j];
                break;
            }
        }

        var roundEl = document.getElementById('header-round-num');
        var totalEl = document.getElementById('header-round-total');
        if (roundEl) roundEl.textContent = data.round || 1;
        if (totalEl) totalEl.textContent = data.total_rounds || 10;

        renderFunFact(data.fun_fact);

        var estimateEl = document.getElementById('reveal-estimate');
        var answerStripEl = document.getElementById('reveal-answer-strip');
        if (data.question_type === 'estimate' && data.estimate) {
            if (estimateEl) estimateEl.classList.remove('hidden');
            if (answerStripEl) answerStripEl.classList.add('hidden');
            renderEstimateReveal(data);
            var estimateEntry = _estimateResultFor(data) || currentPlayer;
            renderResultHero(estimateEntry, data);
            renderStandings(data.leaderboard || players);
            playResultCue(estimateEntry);
            _renderRevealAdminControls(data, currentPlayer);
            return;
        }
        if (estimateEl) estimateEl.classList.add('hidden');
        if (answerStripEl) answerStripEl.classList.remove('hidden');

        flashAnswerButtons(data.correct_answer, myAnswerEntry);

        var resultPlayer = myAnswerEntry || currentPlayer;
        renderResultHero(resultPlayer, data);
        renderAnswerStrip(myAnswerEntry, data.correct_answer);
        renderStandings(data.leaderboard || players);

        playResultCue(resultPlayer);

        _renderRevealAdminControls(data, currentPlayer);
    }

    function _renderRevealAdminControls(data, currentPlayer) {
        var adminControls = document.getElementById('reveal-admin-controls');
        var nextRoundBtn = document.getElementById('next-round-btn');
        var isAdmin = !!(currentPlayer && currentPlayer.is_admin);
        if (document.body) document.body.classList.toggle('is-admin', isAdmin);
        if (adminControls) {
            if (isAdmin) adminControls.classList.remove('hidden');
            else adminControls.classList.add('hidden');
        }
        if (nextRoundBtn) {
            var nextLabel = nextRoundBtn.querySelector('[data-i18n]');
            if (data.last_round) {
                if (nextLabel) {
                    nextLabel.setAttribute('data-i18n', 'reveal.finalResults');
                    nextLabel.textContent = t('reveal.finalResults');
                }
                nextRoundBtn.classList.add('is-final');
            } else {
                if (nextLabel) {
                    nextLabel.setAttribute('data-i18n', 'admin.nextQuestion');
                    nextLabel.textContent = t('admin.nextQuestion');
                }
                nextRoundBtn.classList.remove('is-final');
            }
            nextRoundBtn.disabled = false;
        }
    }

    function _isMyEstimateRow(g, me) {
        if (g.members && g.members.length) return g.members.indexOf(me) !== -1;
        return g.player_name === me;
    }

    function _estimateResultFor(data) {
        var guesses = (data.estimate && data.estimate.guesses) || [];
        var me = state.playerName;
        var team = window.QuizifyPlayerTeam;
        var mine = team && team.myTeam && team.myTeam();
        var members = (mine && mine.members) || [];
        var own = null;
        var scored = null;
        for (var i = 0; i < guesses.length; i++) {
            var g = guesses[i];
            var hasGuess = !g.no_guess && g.guess !== null && g.guess !== undefined;
            var isMine = _isMyEstimateRow(g, me);
            if (isMine) own = g;
            if (hasGuess && (isMine || members.indexOf(g.player_name) !== -1)) {
                if (!scored || isMine) scored = g;
            }
        }
        var row = scored || own;
        if (!row) return null;
        if (!scored) {
            return { player_name: me, no_answer: true, correct: false, points_earned: 0 };
        }
        return {
            player_name: me,
            guess: row.guess,
            correct: true,
            base_score: 0,
            points_earned: row.points || 0
        };
    }

    function _gaveNoAnswer(player) {
        return player.missed_round === true || player.no_answer === true ||
            ((player.answer_index === null || player.answer_index === undefined) &&
             (player.guess === null || player.guess === undefined));
    }

    function _joinNames(names) {
        if (names.length < 2) return names.join('');
        return names.slice(0, -1).join(', ') + ' & ' + names[names.length - 1];
    }

    function _fmtEstimate(val, unit) {
        if (val === null || val === undefined) return '—';
        var n = Math.round(val * 1000) / 1000;
        var I = window.QuizifyI18n;
        var text = (I && I.formatNumber)
            ? I.formatNumber(n)
            : ((n === Math.round(n)) ? String(Math.round(n)) : String(n));
        return unit ? (text + ' ' + unit) : text;
    }

    function renderEstimateReveal(data) {
        var container = document.getElementById('reveal-estimate');
        if (!container) return;
        var est = data.estimate || {};
        var unit = est.unit || '';
        var answer = Number(est.answer);
        var guesses = (est.guesses || []).filter(function (g) { return !g.no_guess && g.guess !== null && g.guess !== undefined; });
        var noGuessCount = (est.guesses || []).length - guesses.length;

        var dataVals = guesses.map(function (g) { return Number(g.guess); }).concat([answer]);
        var range = window.QuizifyRenderShared.numberLineRange(dataVals, est.min, est.max, est.step);
        var lo = range.lo;
        var hi = range.hi;
        var span = range.span;

        function pct(v) {
            return Math.max(0, Math.min(100, ((v - lo) / span) * 100));
        }

        var winners = guesses.filter(function (g) { return g.rank === 1; });
        var winner = winners.length ? winners[0] : null;

        var me = state.playerName;

        var sortedForMarkers = guesses.slice().sort(function (a, b) {
            return Number(a.guess) - Number(b.guess);
        });
        var markersHtml = '';
        sortedForMarkers.forEach(function (g, idx) {
            var left = pct(Number(g.guess));
            var isWinner = g.rank === 1;
            var isMe = _isMyEstimateRow(g, me);
            var labelPos = (idx % 2 === 0) ? 'below' : 'above';
            var dotStyle = 'background:' + (g.color || 'var(--sky)') + ';';
            if (isWinner) dotStyle += 'width:18px;height:18px;border-color:var(--color-gold);';
            var nameLabel = isMe ? t('estimate.you') : g.player_name;
            var star = isWinner ? ' ★' : '';
            markersHtml +=
                '<div class="nl-tick" style="left:' + left.toFixed(1) + '%;">' +
                    '<div class="nl-dot" style="' + dotStyle + '"></div>' +
                    '<div class="nl-lbl nl-lbl--' + labelPos + (isWinner ? ' is-winner' : '') + '">' +
                        '<span class="nl-nm">' + pu.escapeHtml(nameLabel) + star + '</span> ' +
                        pu.escapeHtml(_fmtEstimate(Number(g.guess), '')) +
                    '</div>' +
                '</div>';
        });

        var truthLeft = pct(answer);

        var truthHtml =
            '<div class="nl-truth-line" style="left:' + truthLeft.toFixed(1) + '%;"></div>' +
            '<div class="nl-truth-flag" style="left:' + truthLeft.toFixed(1) + '%;">' +
                pu.escapeHtml(_fmtEstimate(answer, '')) + ' ✓</div>';

        var ranked = guesses.slice().sort(function (a, b) {
            if (a.rank !== b.rank) return a.rank - b.rank;
            return a.distance - b.distance;
        });
        var rowsHtml = '';
        ranked.forEach(function (g) {
            var isMe = _isMyEstimateRow(g, me);
            var swatch = '<span class="res-swatch" style="background:' + (g.color || 'var(--sky)') + '"></span>';
            var youTag = isMe ? '<span class="res-you-tag">' + pu.escapeHtml(t('estimate.you')) + '</span>' : '';
            rowsHtml +=
                '<div class="res-row' + (isMe ? ' is-you' : '') + (g.rank === 1 ? ' is-winner' : '') + '">' +
                    swatch +
                    '<span class="res-name">' + pu.escapeHtml(g.player_name) + youTag + '</span>' +
                    '<span class="res-guess">' + pu.escapeHtml(_fmtEstimate(Number(g.guess), '')) + '</span>' +
                    '<span class="res-off">±' + pu.escapeHtml(_fmtEstimate(g.distance, '')) + '</span>' +
                    '<span class="res-pts">+' + (g.points || 0) + '</span>' +
                '</div>';
        });

        var winnerBanner = '';
        if (winner) {
            var winnerName;
            if (winners.length > 1) {
                winnerName = t('estimate.sharedWin', { names: _joinNames(winners.map(function (g) { return g.player_name; })) });
            } else if (_isMyEstimateRow(winner, me)) {
                winnerName = t('estimate.youWon');
            } else {
                winnerName = t('estimate.playerWon', { name: winner.player_name });
            }
            var sameGuess = winners.every(function (g) { return Number(g.guess) === Number(winner.guess); });
            var winnerSub = sameGuess
                ? '<div class="est-winner-sub">' + pu.escapeHtml(t('estimate.guessOff', { guess: _fmtEstimate(Number(winner.guess), ''), off: _fmtEstimate(winner.distance, '') })) + '</div>'
                : '';
            winnerBanner =
                '<div class="est-winner">' +
                    '<span class="est-winner-medal" aria-hidden="true">🏆</span>' +
                    '<div class="est-winner-text">' +
                        '<div class="est-winner-name">' + pu.escapeHtml(winnerName) + '</div>' +
                        winnerSub +
                    '</div>' +
                    '<div class="est-winner-pts">+' + (winner.points || 0) + '</div>' +
                '</div>';
        }

        var noGuessNote = '';
        if (noGuessCount > 0) {
            noGuessNote = '<div class="est-noguess">' + pu.escapeHtml(t('estimate.noGuessNote', { count: noGuessCount })) + '</div>';
        }

        container.innerHTML =
            '<div class="est-truth">' +
                '<div class="est-truth-label">' + pu.escapeHtml(t('estimate.correctAnswer')) + '</div>' +
                '<div class="est-truth-value">' + pu.escapeHtml(_fmtEstimate(answer, '')) +
                    (unit ? '<span class="est-truth-unit">' + pu.escapeHtml(unit) + '</span>' : '') +
                '</div>' +
            '</div>' +
            '<div class="numberline-card">' +
                '<div class="nl-axis">' + markersHtml + truthHtml + '</div>' +
                '<div class="nl-scale-ends">' +
                    '<span>' + pu.escapeHtml(_fmtEstimate(lo, '')) + '</span>' +
                    '<span>' + pu.escapeHtml(_fmtEstimate(hi, '')) + '</span>' +
                '</div>' +
            '</div>' +
            winnerBanner +
            '<div class="est-results">' + rowsHtml + '</div>' +
            noGuessNote;
    }

    function renderFunFact(text) {
        var container = document.getElementById('fun-fact-container');
        var funFactEl = document.getElementById('fun-fact');

        if (!container) return;

        if (text && text.trim()) {
            if (funFactEl) funFactEl.textContent = text;
            container.classList.remove('hidden');
        } else {
            container.classList.add('hidden');
        }
    }

    function playResultCue(player) {
        var snd = window.QuizifyPlayerSound;
        if (!snd || !player) return;
        if (_gaveNoAnswer(player)) return;
        if (player.correct === true) snd.playCorrect();
        else snd.playWrong();
    }

    function _signedPoints(points) {
        var n = Number(points) || 0;
        if (n < 0) return '\u2212' + Math.abs(n);
        if (n > 0) return '+' + n;
        return '0';
    }

    function _wagerReveal(hero, score) {
        var game = window.QuizifyPlayerGame;
        var stake = game && game.takeWagerStake ? game.takeWagerStake() : 0;
        var shared = window.QuizifyRenderShared;
        if (!stake || !score || !shared || shared.prefersReducedMotion()) return;
        var num = hero.querySelector('.pl-result-big-points, .pl-result-pts, .pl-result-zero');
        if (!num) return;
        if (score < 0) {
            num.classList.add('hs-settle--lose');
            return;
        }
        var first = num.firstChild;
        if (!first || first.nodeType !== 3) return;
        var span = document.createElement('span');
        span.className = 'wager-win';
        span.textContent = score;
        num.replaceChild(span, first);
        num.insertBefore(document.createTextNode('+'), span);
        shared.rollDigits(span, 0, score);
    }

    function renderResultHero(player, data) {
        _buildResultHero(player, data);
        var hero = document.getElementById('reveal-hero');
        if (hero && player) _wagerReveal(hero, player.round_score || player.points_earned || 0);
    }

    function _buildResultHero(player, data) {
        var hero = document.getElementById('reveal-hero');
        if (!hero) return;

        hero.className = 'pl-result-hero';
        hero.innerHTML = '';

        if (!player) {
            hero.classList.add('pl-result-hero--missed');
            hero.innerHTML =
                '<span class="pl-result-verdict-circle pl-result-verdict-circle--missed" aria-hidden="true">👋</span>' +
                '<div class="pl-result-verdict">' + pu.escapeHtml(t('reveal.joinedLate')) + '</div>' +
                '<div class="pl-result-sub">' + pu.escapeHtml(t('reveal.joinedLateHint')) + '</div>';
            return;
        }

        var missed = _gaveNoAnswer(player);
        var correct = player.correct === true;
        var streak = player.streak || player.new_streak || 0;
        var roundScore = player.round_score || player.points_earned || 0;
        var correctAnswer = (data && data.correct_answer) || '';

        var BASE_POINTS = 10;
        var baseScore = (typeof player.base_score === 'number') ? player.base_score : (correct ? BASE_POINTS : 0);
        var speedBonus = player.speed_bonus || 0;
        var streakBonus = player.streak_bonus || 0;
        var difficultyBonus = player.difficulty_bonus || 0;
        var doubleBonus = player.double_bonus || 0;
        var breakdownBits = [];
        if (baseScore) breakdownBits.push(t('reveal.baseScore') + ' <b>' + baseScore + '</b>');
        if (speedBonus) breakdownBits.push(pu.feedbackLabel('reveal.speedBonus', pu.escapeHtml(t('reveal.speedBonus'))) + ' <b>+' + speedBonus + '</b>');
        if (difficultyBonus) breakdownBits.push(pu.feedbackLabel('reveal.difficulty', pu.escapeHtml(t('reveal.difficulty'))) + ' <b>+' + difficultyBonus + '</b>');
        if (streakBonus) breakdownBits.push(pu.feedbackLabel('reveal.streakBonus', pu.escapeHtml(t('reveal.streakBonus', { count: streak }))) + ' <b>+' + streakBonus + '</b>');
        if (doubleBonus) breakdownBits.push('\u2728 ' + pu.escapeHtml(t('powerups.double_points')) + ' <b>+' + doubleBonus + '</b>');
        var breakdownHtml = breakdownBits.length
            ? '<div class="pl-result-breakdown">' + breakdownBits.join(' &middot; ') + '</div>'
            : '';

        if (missed) {
            hero.classList.add('pl-result-hero--missed');
            hero.innerHTML =
                '<span class="pl-result-verdict-circle pl-result-verdict-circle--missed" aria-hidden="true">⏱</span>' +
                '<div class="pl-result-verdict">' + pu.escapeHtml(t('reveal.timeUp')) + '</div>' +
                '<div class="pl-result-sub">' + pu.escapeHtml(t('reveal.correctAnswerWas')) + ' <b>' + pu.escapeHtml(correctAnswer) + '</b></div>' +
                '<div class="pl-result-zero">' + _signedPoints(roundScore) + '<span class="pl-result-zero-unit">' + pu.escapeHtml(t('game.points')) + '</span></div>';
            return;
        }

        if (!correct) {
            var prevStreak = player.previous_streak || 0;
            hero.classList.add('pl-result-hero--wrong');
            hero.innerHTML =
                '<span class="pl-result-verdict-circle pl-result-verdict-circle--wrong" aria-hidden="true">✗</span>' +
                '<div class="pl-result-verdict">' + pu.escapeHtml(t('reveal.wrongHeadline')) + '</div>' +
                '<div class="pl-result-sub">' + pu.escapeHtml(t('reveal.correctAnswerWas')) + ' <b>' + pu.escapeHtml(correctAnswer) + '</b></div>' +
                '<div class="pl-result-zero">' + _signedPoints(roundScore) + '<span class="pl-result-zero-unit">' + pu.escapeHtml(t('game.points')) + '</span></div>' +
                (prevStreak >= 2 ? '<div class="pl-result-streak-lost">' + pu.feedbackLabel('reveal.streakLost', pu.escapeHtml(t('reveal.streakLost', { count: prevStreak }))) + '</div>' : '');
            return;
        }

        if (player.streak_active) {
            hero.classList.add('pl-result-hero--streak');
            hero.innerHTML =
                '<div class="pl-result-flame qz-icon qz-icon--sun" aria-hidden="true">' + (window.QuizifyIcons && window.QuizifyIcons.uiIcon ? window.QuizifyIcons.uiIcon('flame') : '🔥') + '</div>' +
                '<div class="pl-result-headline">' + pu.escapeHtml(t('reveal.streakHeadline', { count: streak })) + '</div>' +
                '<div class="pl-result-pts">+' + roundScore + '<span class="pl-result-pts-unit">' + pu.escapeHtml(t('game.points')) + '</span></div>' +
                breakdownHtml;
            return;
        }

        hero.classList.add('pl-result-hero--big');
        hero.innerHTML =
            '<div class="pl-result-big-points">+' + roundScore + '</div>' +
            '<div class="pl-result-pts-unit">' + pu.escapeHtml(t('game.points').toUpperCase()) + '</div>' +
            breakdownHtml;
    }

    function renderAnswerStrip(myAnswer, correctAnswer) {
        var strip = document.getElementById('reveal-answer-strip');
        if (!strip) return;

        strip.className = 'pl-result-answer-strip';

        var ans = correctAnswer || '';
        var hasAnswer = myAnswer && myAnswer.answer_index !== null && myAnswer.answer_index !== undefined;
        var isCorrect = myAnswer && myAnswer.correct === true;

        if (!hasAnswer) {
            strip.classList.add('pl-result-answer-strip--missed');
            strip.innerHTML =
                '<span>' + pu.escapeHtml(t('reveal.noAnswerShort')) + '</span>' +
                '<span class="pl-result-answer-mark">—</span>';
            return;
        }

        if (isCorrect) {
            strip.innerHTML =
                '<span>' + pu.escapeHtml(t('reveal.answerLabel')) + ': <b>' + pu.escapeHtml(ans) + '</b></span>' +
                '<span class="pl-result-answer-mark">✓</span>';
            return;
        }

        strip.classList.add('pl-result-answer-strip--wrong');
        var myText = myAnswer.answer_text || myAnswer.answer || '';
        strip.innerHTML =
            '<span>' + pu.escapeHtml(t('reveal.yourAnswer')) + ': <b>' + pu.escapeHtml(myText) + '</b></span>' +
            '<span class="pl-result-answer-mark">✗</span>';
    }

    function _colorFor(name, idx) {
        var palette = (window.QuizifyTokens && window.QuizifyTokens.players) || ['var(--color-text-light)'];
        if (!name) return palette[idx % palette.length];
        var c = name.charCodeAt(0) || 0;
        return palette[(c + idx) % palette.length];
    }

    function updateScoringStatus(msg) {
        _scoringStatus = msg;
        if (_lastStandings) renderStandings(_lastStandings, true);
    }

    function renderStandings(leaderboard, isRepaint) {
        var container = document.getElementById('reveal-standings');
        if (!container) return;
        _lastStandings = leaderboard;
        if (!isRepaint) _deltaBase = _prevRanks;
        var shared = window.QuizifyRenderShared;
        leaderboard = shared.scoringHostRows(leaderboard, _scoringStatus);

        var rows = (Array.isArray(leaderboard) ? leaderboard : []).map(function(p, idx) {
            var name = p.name || p.player_name || '';
            var score = (typeof p.score === 'number') ? p.score
                      : (typeof p.total_score === 'number') ? p.total_score
                      : (typeof p.points === 'number') ? p.points : 0;
            var color = p.color || null;
            return {
                source: p,
                key: pu.entrantKey({ entrant_id: p.entrant_id, name: name }),
                name: name, score: score, color: color,
                rank: (typeof p.rank === 'number') ? p.rank : null,
                idx: idx
            };
        });
        rows.sort(function(a, b) { return (b.score - a.score) || (a.idx - b.idx); });

        rows.forEach(function(r, i) {
            if (r.rank !== null) return;
            r.rank = (i > 0 && rows[i - 1].score === r.score) ? rows[i - 1].rank : i + 1;
        });

        var newRanks = {};
        rows.forEach(function(r) { newRanks[r.key] = r.rank; });

        function deltaFor(key) {
            if (!_deltaBase) return null;
            var prev = _deltaBase[key];
            var now = newRanks[key];
            if (typeof prev !== 'number' || typeof now !== 'number') return null;
            return prev - now;
        }

        var medalClass = { 1: 'pl-result-srow--gold', 2: 'pl-result-srow--silver', 3: 'pl-result-srow--bronze' };
        var youLabel = t('lobby.you') !== 'lobby.you' ? t('lobby.you') : 'Du';
        var me = pu.myEntrant();

        container.innerHTML = rows.map(function(r, i) {
            var isMe = r.key === me;
            var classes = ['pl-result-srow'];
            if (medalClass[r.rank]) classes.push(medalClass[r.rank]);
            if (isMe) classes.push('pl-result-srow--me');
            var scoringNote = shared.scoringNoteHtml(r.source, _scoringStatus);
            var initial = (r.name || '?').charAt(0).toUpperCase();
            var bg = r.color || _colorFor(r.name, i);
            var displayName = isMe ? youLabel : (r.name || '');
            var d = deltaFor(r.key);
            var deltaHtml = '<span class="pl-result-delta pl-result-delta--flat">—</span>';
            if (d !== null) {
                if (d > 0) deltaHtml = '<span class="pl-result-delta pl-result-delta--up">↑' + d + '</span>';
                else if (d < 0) deltaHtml = '<span class="pl-result-delta pl-result-delta--down">↓' + Math.abs(d) + '</span>';
            }
            return '<div class="' + classes.join(' ') + '">' +
                '<span class="pl-result-pos">' + r.rank + '.</span>' +
                '<span class="pl-result-av" style="background:' + pu.escapeHtml(bg) + '">' + pu.escapeHtml(initial) + '</span>' +
                '<span class="pl-result-nm">' + pu.escapeHtml(displayName) + '</span>' +
                deltaHtml +
                '<span class="pl-result-sc">' + r.score + '</span>' +
                scoringNote +
            '</div>';
        }).join('') + shared.scoringOutHtml(_scoringStatus);
        if (shared.rollScores && container.querySelectorAll) {
            shared.rollScores(
                container.querySelectorAll('.pl-result-sc'),
                rows.map(function (r) { return { key: r.key, score: r.score }; }),
                _shownScores
            );
        }
        if (_scoringStatus) {
            shared.bindScoringButtons(container, function (entrantId, out) {
                if (state.ws && state.ws.readyState === WebSocket.OPEN) {
                    state.ws.send(JSON.stringify({ type: 'set_scoring', entrant_id: entrantId, out: out }));
                }
            });
        }

        _prevRanks = newRanks;
    }

    function flashAnswerButtons(correctAnswerText, myEntry) {
        var answerButtons = document.getElementById('answer-buttons');
        if (!answerButtons) return;
        if (answerButtons.classList) answerButtons.classList.remove('is-locked');

        var buttons = answerButtons.querySelectorAll('.answer-btn');
        if (!buttons.length) return;

        var mySubmittedIndex = game && game.getLastSubmittedIndex ? game.getLastSubmittedIndex() : -1;

        function _buttonAnswerText(btn) {
            var span = btn.querySelector('.answer-btn-text, .answer-text, span');
            return (span ? span.textContent : btn.textContent || '').trim();
        }
        var correctText = (correctAnswerText || '').trim();

        var correctIndex = -1;
        var serverBtnIdx = (myEntry && typeof myEntry.correct_button_index === 'number')
            ? myEntry.correct_button_index : -1;
        if (serverBtnIdx >= 0 && serverBtnIdx < buttons.length) {
            correctIndex = serverBtnIdx;
        } else if (myEntry && myEntry.correct && mySubmittedIndex >= 0 && mySubmittedIndex < buttons.length) {
            correctIndex = mySubmittedIndex;
        } else if (correctText) {
            var firstMatch = -1;
            for (var bi = 0; bi < buttons.length; bi++) {
                if (_buttonAnswerText(buttons[bi]) === correctText) {
                    if (firstMatch === -1) firstMatch = bi;
                    if (bi !== mySubmittedIndex) { correctIndex = bi; break; }
                }
            }
            if (correctIndex === -1) correctIndex = firstMatch;
        }

        buttons.forEach(function(btn, i) {
            btn.classList.remove('is-selected');

            if (i === correctIndex) {
                btn.classList.add('correct');
            } else if (i === mySubmittedIndex && (!myEntry || !myEntry.correct)) {
                btn.classList.add('wrong');
            } else {
                btn.classList.add('dimmed');
            }
        });

        if (myEntry && !myEntry.correct && mySubmittedIndex >= 0 && mySubmittedIndex !== correctIndex) {
            var wrongBtn = buttons[mySubmittedIndex];
            if (wrongBtn) { wrongBtn.classList.remove('dimmed', 'correct'); wrongBtn.classList.add('wrong'); }
        }
    }

    function _resetFlagButton() {
        var btn = document.getElementById('flag-question-btn');
        if (btn) {
            btn.disabled = false;
            btn.textContent = '🚩';
            btn.classList.remove('is-flagged');
        }
    }

    function _wireFlagButton() {
        var btn = document.getElementById('flag-question-btn');
        if (!btn || btn._wired) return;
        btn._wired = true;
        btn.addEventListener('click', function () {
            if (_flaggedThisRound || !_currentQuestionId) return;
            _flaggedThisRound = true;
            btn.disabled = true;
            btn.textContent = '✓';
            btn.classList.add('is-flagged');
            fetch('/api/quizify/flag-question', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    question_id: _currentQuestionId,
                    player_name: state.playerName || '',
                    reason: '',
                }),
            }).then(function (r) {
                if (!r.ok) throw new Error('flag failed: ' + r.status);
                pu.showToast(t('reveal.flagThanks'), 1800);
            }).catch(function (err) {
                console.warn('[Quizify] flag error', err);
                _flaggedThisRound = false;
                _resetFlagButton();
            });
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _wireFlagButton);
    } else {
        _wireFlagButton();
    }

    window.QuizifyPlayerReveal = {
        updateRevealView: updateRevealView,
        updateScoringStatus: updateScoringStatus,
        resetRankMemo: resetRankMemo,
        renderFunFact: renderFunFact
    };

})();


/* ============ player-end.js ============ */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var utils = window.QuizifyUtils || {};
    var state = pu.state;

    function _t(key, params) {
        if (window.QuizifyI18n && typeof window.QuizifyI18n.t === 'function') {
            return window.QuizifyI18n.t(key, params);
        }
        return key;
    }

    function _tf(key, fallback, params) {
        var v = _t(key, params);
        return (v === key) ? fallback : v;
    }

    function updateEndView(data) {
        window.scrollTo(0, 0);
        var leaderboard = (data.leaderboard || []).slice();

        var team = window.QuizifyPlayerTeam;
        var mine = team && team.myTeam && team.myTeam();
        var me = (mine && (mine.team_id || mine.name)) || state.playerName;
        leaderboard.forEach(function (entry) {
            entry.is_current = ((entry.entrant_id || entry.name) === me);
        });
        leaderboard.sort(function (a, b) {
            return (a.rank || 0) - (b.rank || 0);
        });

        var superlatives = data.superlatives || [];

        playEndReveal(leaderboard);

        renderEndHeader(leaderboard, data);

        renderWinnerHero(leaderboard);

        var highlights = buildHighlights(leaderboard, superlatives);

        renderHighlightChips(highlights);

        renderScoreboard(leaderboard, highlights);

        renderShareCard(data.share, state.playerName);

        var adminControls = document.getElementById('end-admin-controls');
        var playerMessage = document.getElementById('end-player-message');
        var me = leaderboard.find(function (p) { return p.is_current; });
        var amAdmin = !!state.isAdmin || !!(me && me.is_admin);

        if (amAdmin) {
            if (adminControls) adminControls.classList.remove('hidden');
            if (playerMessage) playerMessage.classList.add('hidden');
        } else {
            if (adminControls) adminControls.classList.add('hidden');
            if (playerMessage) playerMessage.classList.remove('hidden');
        }

    }

    var _endRevealKey = null;

    function playEndReveal(leaderboard) {
        var view = document.getElementById('end-view');
        if (!view || !view.classList) return;
        var key = leaderboard.map(function (p) {
            return (p.entrant_id || p.name) + ':' + p.score;
        }).join('|');
        if (key === _endRevealKey) return;
        _endRevealKey = key;
        view.classList.remove('is-revealing');
        void view.offsetWidth;
        view.classList.add('is-revealing');
    }

    function renderEndHeader(leaderboard, data) {
        var metaEl = document.getElementById('end-meta-line');
        if (!metaEl) return;

        var rounds = (data && data.total_rounds) || 0;
        if (!rounds) {
            leaderboard.forEach(function (p) {
                if ((p.rounds_played || 0) > rounds) rounds = p.rounds_played;
            });
        }
        var players = 0;
        leaderboard.forEach(function (p) {
            players += Array.isArray(p.members) ? p.members.length : 1;
        });
        if (!players) players = leaderboard.length;

        var parts = [];
        if (rounds) {
            parts.push(_tf('game.questionsCount', rounds + ' questions', { count: rounds }));
        }
        parts.push(_tf('leaderboard.playersCount', players + ' players', { count: players }));
        metaEl.textContent = parts.join(' · ');
    }

    function renderWinnerHero(leaderboard) {
        var nameEl = document.getElementById('end-hero-name');
        var scoreEl = document.getElementById('end-hero-score');
        var winner = leaderboard.find(function (p) { return p.rank === 1; }) || leaderboard[0];
        var shared = window.QuizifyRenderShared && window.QuizifyRenderShared.winnerNames;
        var names = winner ? (shared ? shared(leaderboard) : winner.name) : '';
        if (nameEl) nameEl.textContent = names || '---';
        if (scoreEl) {
            scoreEl.textContent = winner
                ? _t('game.pointsLabel', { count: winner.score })
                : '';
        }
    }

    var CHIP_TINT = {
        'topScore': 'disc-sun',
        'highlights.awards.hotStreak': 'disc-coral',
        'highlights.awards.bestRound': 'disc-sage',
        'highlights.awards.fastestFinger': 'disc-sky',
        'highlights.awards.comebackKing': 'disc-sage',
        'highlights.awards.mostAccurate': 'disc-sage',
        'highlights.awards.buzzkill': 'disc-sky',
        'highlights.awards.knowledgeExpert': 'disc-sun'
    };

    var CHIP_EMOJI = {
        'topScore': '🏅',
        'highlights.awards.hotStreak': '🔥',
        'highlights.awards.bestRound': '🥇',
        'highlights.awards.fastestFinger': '⚡',
        'highlights.awards.comebackKing': '🚀',
        'highlights.awards.mostAccurate': '🎯',
        'highlights.awards.buzzkill': '🧊',
        'highlights.awards.knowledgeExpert': '🧠'
    };

    function buildHighlights(leaderboard, superlatives) {
        var out = [];
        var seenPlayerBadge = {};

        var winner = leaderboard.find(function (p) { return p.rank === 1; }) || leaderboard[0];
        if (winner && winner.score > 0) {
            out.push({
                key: 'topScore',
                emoji: CHIP_EMOJI.topScore,
                tint: CHIP_TINT.topScore,
                title: _tf('highlights.topScore', 'Höchste Punktzahl'),
                value: _t('highlights.scoreValue', { count: winner.score }),
                player: winner.name,
                badge: '🏅'
            });
        }

        (superlatives || []).forEach(function (award) {
            var key = award.award_key || '';
            var emoji = CHIP_EMOJI[key] || award.icon || '🏆';
            var tint = CHIP_TINT[key] || 'disc-sage';

            var title = key ? _t(key) : (award.award || '');
            if (key && title === key) title = award.award || '';

            var detailKey = award.detail_key;
            var detailParams = award.detail_params || {};
            var value = detailKey ? _t(detailKey, detailParams) : (award.detail || '');
            if (detailKey && value === detailKey) value = award.detail || '';

            out.push({
                key: key,
                emoji: emoji,
                tint: tint,
                title: title,
                value: value,
                player: award.winner || '',
                badge: emoji
            });
        });

        out.forEach(function (h) {
            if (!h.player) return;
            var k = h.player + '|' + h.badge;
            if (seenPlayerBadge[k]) { h._dupBadge = true; return; }
            seenPlayerBadge[k] = true;
        });

        return out;
    }

    function renderHighlightChips(highlights) {
        var section = document.getElementById('end-highlights-section');
        var row = document.getElementById('end-chiprow');
        if (!section || !row) return;

        if (!highlights || highlights.length === 0) {
            section.classList.add('hidden');
            row.innerHTML = '';
            return;
        }

        row.innerHTML = highlights.map(function (h) {
            var who = h.player ? '<div class="rchip-who">' + pu.escapeHtml(h.player) + '</div>' : '';
            return '<div class="rchip">' +
                '<div class="rchip-disc ' + h.tint + '">' + pu.escapeHtml(h.emoji) + '</div>' +
                '<div class="rchip-main">' +
                    '<div class="rchip-title">' + pu.escapeHtml(h.title) + '</div>' +
                    '<div class="rchip-val">' + pu.escapeHtml(String(h.value)) + '</div>' +
                    who +
                '</div>' +
            '</div>';
        }).join('');
        section.classList.remove('hidden');
    }

    function renderScoreboard(leaderboard, highlights) {
        var board = document.getElementById('end-scoreboard');
        if (!board) return;

        var youLabel = _tf('lobby.you', 'Du');
        var awayText = _tf('lobby.away', 'away');

        var badgesByPlayer = {};
        (highlights || []).forEach(function (h) {
            if (!h.player || h._dupBadge) return;
            if (h.key === 'topScore') return;
            (badgesByPlayer[h.player] = badgesByPlayer[h.player] || []).push({
                emoji: h.badge,
                title: h.title
            });
        });

        var topScore = 0;
        leaderboard.forEach(function (p) { if ((p.score || 0) > topScore) topScore = p.score; });

        var html = leaderboard.map(function (entry) {
            var rank = entry.rank || 0;
            var isYou = !!entry.is_current;
            var isWinner = (rank === 1);
            var pct = topScore > 0 ? Math.max(4, Math.round((entry.score / topScore) * 100)) : 0;

            var discClass = 'r-neutral';
            if (rank === 1) discClass = 'r-gold';
            else if (rank === 2) discClass = 'r-silver';
            else if (rank === 3) discClass = 'r-bronze';

            var barClass = isYou ? 'bar-coral' : (isWinner ? 'bar-gold' : 'bar-sage');

            var badges = (badgesByPlayer[entry.name] || []).map(function (b) {
                return '<span class="sb-badge" title="' + pu.escapeHtml(b.title) + '">' +
                    pu.escapeHtml(b.emoji) + '</span>';
            }).join('');

            var youTag = isYou
                ? '<span class="sb-you">' + pu.escapeHtml(youLabel) + '</span>' : '';

            var away = (entry.connected === false)
                ? '<span class="sb-away">(' + pu.escapeHtml(awayText) + ')</span>' : '';

            return '<div class="qz-rank-row sb-row' + (isYou ? ' sb-row--me' : '') +
                    (entry.connected === false ? ' sb-row--away' : '') +
                    '" data-place="' + rank + '">' +
                '<div class="sb-rank ' + discClass + '">' + rank + '</div>' +
                '<div class="sb-body">' +
                    '<div class="sb-nameline">' +
                        '<span class="sb-name">' + pu.escapeHtml(entry.name || '') + '</span>' +
                        away + badges + youTag +
                    '</div>' +
                    '<div class="sb-barwrap"><div class="sb-bar ' + barClass +
                        '" style="width:' + pct + '%;"></div></div>' +
                '</div>' +
                '<div class="sb-score">' + (entry.score || 0) + '</div>' +
            '</div>';
        }).join('');

        board.innerHTML = html;
    }

    function setupNewGameButton() {
        var playAgainBtn = document.getElementById('play-again-same-btn');
        var newGameBtn = document.getElementById('new-game-btn');

        if (playAgainBtn) {
            playAgainBtn.disabled = false;
            playAgainBtn.textContent = _tf('admin.playAgainSame', 'Play again');

            playAgainBtn.onclick = function () {
                var ws = state.ws;
                if (!ws || ws.readyState !== WebSocket.OPEN) {
                    if (newGameBtn) newGameBtn.click();
                    return;
                }
                playAgainBtn.disabled = true;
                playAgainBtn.innerHTML = '<span>⏳</span>';
                try { ws.send(JSON.stringify({ type: 'play_again' })); } catch (e) { }
            };
        }

        if (newGameBtn) {
            newGameBtn.onclick = function () {
                var confirmThen = window.QuizifyPlayer && window.QuizifyPlayer.confirmThen;
                if (confirmThen) confirmThen(newGameBtn, 'newGame', _startNewGame);
            };
        }
    }

    function _startNewGame() {
        var forgetIdentity = window.QuizifyPlayer && window.QuizifyPlayer.forgetIdentity;
        if (forgetIdentity) forgetIdentity(); else pu.clearSession();
        try {
            sessionStorage.removeItem('quizify_admin_name');
        } catch (e) { }

        var ws = state.ws;
        if (ws && ws.readyState === WebSocket.OPEN) {
            try { ws.send(JSON.stringify({ type: 'reset_game' })); } catch (e) { }
        }
        window.location.href = '/quizify/admin';
    }

    var RESULT_GLYPH = { correct: '✅', wrong: '❌', timeout: '⬜' };

    function buildShareText(entry, packs) {
        if (!entry) { return ''; }
        var lines = [];
        lines.push(_tf('share.line.rank', 'Quizify — {name}, {rank} of {total}', {
            name: entry.name, rank: entry.rank, total: entry.total_players
        }));
        if (packs && packs.length) {
            lines.push(_tf('share.line.packs', 'Packs: {packs}', {
                packs: packs.join(' · ')
            }));
        }
        lines.push(_tf('share.line.score', 'Correct: {correct}/{rounds} · {score} points', {
            correct: entry.correct, rounds: entry.rounds, score: entry.score
        }));
        if (entry.powerups) {
            lines.push(_tf('share.line.powerups', '⚡ {count} power-ups', {
                count: entry.powerups
            }));
        }
        var strip = (entry.results || []).map(function (r) {
            return RESULT_GLYPH[r] || RESULT_GLYPH.wrong;
        }).join('');
        if (strip) { lines.push(strip); }
        lines.push('github.com/mholzi/quizify');
        return lines.join('\n');
    }

    function findShareEntry(share, playerName) {
        var players = (share && share.players) || [];
        for (var i = 0; i < players.length; i++) {
            if (players[i].name === playerName) { return players[i]; }
        }
        return null;
    }

    function renderShareCard(share, playerName) {
        var section = document.getElementById('end-share-section');
        if (!section) { return; }
        var entry = findShareEntry(share, playerName);
        if (!entry || !entry.rounds) {
            section.classList.add('hidden');
            return;
        }
        section.classList.remove('hidden');

        var packs = (share && share.packs) || [];
        var titleEl = document.getElementById('end-share-title');
        if (titleEl) {
            titleEl.textContent = _tf('share.slipTitle', '{name} — {rank} of {total}', {
                name: entry.name, rank: entry.rank, total: entry.total_players
            });
        }

        var facts = document.getElementById('end-share-facts');
        if (facts) {
            facts.innerHTML = '';
            var rows = [];
            if (packs.length) {
                rows.push([_tf('share.factPacks', 'Packs'), packs.join(' · ')]);
            }
            rows.push([_tf('share.factCorrect', 'Correct'), entry.correct + ' / ' + entry.rounds]);
            rows.push([_tf('share.factScore', 'Points'), String(entry.score)]);
            if (entry.powerups) {
                rows.push([_tf('share.factPowerups', 'Power-ups'), String(entry.powerups)]);
            }
            rows.forEach(function (row) {
                var dt = document.createElement('dt');
                dt.textContent = row[0];
                var dd = document.createElement('dd');
                dd.textContent = row[1];
                facts.appendChild(dt);
                facts.appendChild(dd);
            });
        }

        var stripEl = document.getElementById('end-share-strip');
        if (stripEl) {
            stripEl.textContent = (entry.results || []).map(function (r) {
                return RESULT_GLYPH[r] || RESULT_GLYPH.wrong;
            }).join('');
        }

        setupShareButton(buildShareText(entry, packs));
    }

    function setupShareButton(text) {
        var btn = document.getElementById('end-share-btn');
        var status = document.getElementById('end-share-status');
        if (!btn) { return; }
        btn.onclick = function () {
            function done(msgKey, fallback) {
                if (status) { status.textContent = _tf(msgKey, fallback); }
            }
            if (navigator.share) {
                navigator.share({ text: text }).then(function () {
                    done('share.shared', 'Shared');
                }).catch(function (err) {
                    if (err && err.name === 'AbortError') { return; }
                    copyToClipboard(text, done);
                });
                return;
            }
            copyToClipboard(text, done);
        };
    }

    function copyToClipboard(text, done) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(function () {
                done('share.copied', 'Copied to clipboard');
            }).catch(function () {
                legacyCopy(text, done);
            });
            return;
        }
        legacyCopy(text, done);
    }

    function legacyCopy(text, done) {
        try {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.setAttribute('readonly', '');
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            var ok = document.execCommand('copy');
            document.body.removeChild(ta);
            done(ok ? 'share.copied' : 'share.copyFailed',
                 ok ? 'Copied to clipboard' : 'Could not copy — select the card and copy it by hand');
        } catch (e) {
            done('share.copyFailed', 'Could not copy — select the card and copy it by hand');
        }
    }

    window.QuizifyPlayerEnd = {
        updateEndView: updateEndView,
        buildShareText: buildShareText,
        renderShareCard: renderShareCard,
        renderWinnerHero: renderWinnerHero,
        renderScoreboard: renderScoreboard,
        renderHighlightChips: renderHighlightChips,
        buildHighlights: buildHighlights,
        setupNewGameButton: setupNewGameButton
    };

})();


/* ============ player-lightning.js ============ */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var state = pu.state;

    var _send = function () {};
    function setSend(fn) { _send = fn; }

    function t(key, vars) {
        var fn = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        return fn(key, vars);
    }

    var _answeredIndex = -1;
    var _questionIndex = -1;

    function handleLightningSplash(msg) {
        msg = msg || {};
        pu.showView('lightning-splash-view');

        var countEl = document.getElementById('lightning-splash-count');
        if (countEl && typeof msg.num_questions === 'number') {
            countEl.textContent = msg.num_questions;
        }
        var secEl = document.getElementById('lightning-splash-seconds');
        if (secEl && typeof msg.seconds_per_question === 'number') {
            secEl.textContent = Math.round(msg.seconds_per_question) + 's';
        }

        var waitHint = document.getElementById('lightning-splash-waithint');
        if (waitHint) waitHint.classList.remove('hidden');
    }

    function handleLightningQuestion(msg) {
        pu.showView('lightning-view');

        _questionIndex = (typeof msg.index === 'number') ? msg.index : -1;

        var prog = document.getElementById('lightning-progress');
        if (prog) prog.textContent = ((msg.index || 0) + 1) + ' / ' + (msg.num_questions || 5);

        var cat = document.getElementById('lightning-category');
        if (cat) cat.textContent = msg.category || '';

        var img = document.getElementById('lightning-image');
        if (img) {
            var safeImg = (window.QuizifyUtils && window.QuizifyUtils.safeImageUrl)
                ? window.QuizifyUtils.safeImageUrl(msg.image_url) : '';
            if (safeImg) {
                var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
                img.src = safeImg;
                img.alt = t('game.questionImageAlt');
                img.hidden = false;
            }
            else { img.hidden = true; img.alt = ''; img.removeAttribute('src'); }
        }

        var qtext = document.getElementById('lightning-question-text');
        if (qtext) qtext.textContent = msg.question_text || '';

        var answers = msg.answers || [];
        for (var i = 0; i < 3; i++) {
            var span = document.getElementById('lightning-answer-text-' + i);
            var btn = document.querySelector('[data-lightning-answer="' + i + '"]');
            if (span) {
                var a = answers[i];
                span.textContent = ((a && typeof a === 'object') ? a.text : a) || '';
            }
            if (btn) {
                btn.disabled = false;
                btn.classList.remove('answer-btn--correct', 'answer-btn--wrong', 'selected');
                btn.style.visibility = (i < answers.length) ? '' : 'hidden';
            }
        }

        var answered = document.getElementById('lightning-answered');
        if (answered) answered.classList.add('hidden');
        if (_lightningLockTimer) { clearTimeout(_lightningLockTimer); _lightningLockTimer = null; }

        var timer = document.getElementById('lightning-timer');
        if (timer) timer.textContent = Math.ceil(msg.seconds || 15);

        var shared = window.QuizifyRenderShared;
        if (shared && shared.playEntrance) {
            shared.playEntrance(qtext,
                document.querySelectorAll('[data-lightning-answer]'), { fast: true });
        }

        _answeredIndex = -1;

        if (msg.you_answered) {
            lockAnswered(
                (typeof msg.you_answer_index === 'number') ? msg.you_answer_index : -1
            );
        }
    }

    function lockAnswered(index) {
        _answeredIndex = index;
        var btns = document.querySelectorAll('[data-lightning-answer]');
        for (var i = 0; i < btns.length; i++) {
            btns[i].disabled = true;
            var idx = parseInt(btns[i].getAttribute('data-lightning-answer'), 10);
            btns[i].classList.toggle('selected', idx === index);
        }
        var row = document.getElementById('lightning-answered');
        if (row) row.classList.remove('hidden');
    }

    function handleLightningTick(msg) {
        var timer = document.getElementById('lightning-timer');
        if (timer && typeof msg.remaining === 'number') {
            timer.textContent = Math.ceil(msg.remaining);
        }
    }

    function inTeam() {
        var team = window.QuizifyPlayerTeam;
        return !!(team && team.isTeamMode());
    }

    function submitAnswer(shuffledIndex) {
        if (inTeam()) {
            _send('lightning_answer', {
                answer_index: shuffledIndex, index: _questionIndex
            });
            return;
        }

        if (_answeredIndex !== -1) return;
        _answeredIndex = shuffledIndex;
        _send('lightning_answer', { answer_index: shuffledIndex, index: _questionIndex });

        var btns = document.querySelectorAll('[data-lightning-answer]');
        for (var i = 0; i < btns.length; i++) {
            btns[i].disabled = true;
            if (parseInt(btns[i].getAttribute('data-lightning-answer'), 10) === shuffledIndex) {
                btns[i].classList.add('selected');
            }
        }
        var answered = document.getElementById('lightning-answered');
        if (answered) answered.classList.remove('hidden');
    }

    var _lightningLockTimer = null;

    function handleLightningTeamAnswer(msg) {
        if (typeof msg.index === 'number' && msg.index !== _questionIndex) return;
        var btns = document.querySelectorAll('[data-lightning-answer]');
        for (var i = 0; i < btns.length; i++) {
            var idx = parseInt(btns[i].getAttribute('data-lightning-answer'), 10);
            var isStanding = idx === msg.answer_index;
            btns[i].classList.toggle('selected', isStanding);
            btns[i].disabled = true;
            btns[i].classList.add('is-team-locked');
        }
        var answered = document.getElementById('lightning-answered');
        if (answered) {
            var who = msg.set_by || '';
            answered.textContent = who ? t('teams.standingAnswer', { name: who }) : '';
            answered.classList.remove('hidden');
        }
        if (_lightningLockTimer) clearTimeout(_lightningLockTimer);
        _lightningLockTimer = setTimeout(function () {
            var list = document.querySelectorAll('[data-lightning-answer]');
            for (var j = 0; j < list.length; j++) {
                list[j].disabled = false;
                list[j].classList.remove('is-team-locked');
            }
            _lightningLockTimer = null;
        }, (msg.lock_seconds || 2) * 1000);
    }

    function handleLightningAnswerResult(msg) {
        var scoreEl = document.getElementById('lightning-score');
        if (scoreEl && typeof msg.score === 'number') scoreEl.textContent = msg.score;
    }

    function handleLightningRecap(msg) {
        pu.showView('lightning-recap-view');
        var recap = msg.recap || (msg.lightning_recap) || {};
        renderRecap(recap);

        var adminCtl = document.getElementById('lightning-recap-admin');
        var playerMsg = document.getElementById('lightning-recap-player-msg');
        if (adminCtl) adminCtl.classList.toggle('hidden', !state.isAdmin);
        if (playerMsg) playerMsg.classList.toggle('hidden', !!state.isAdmin);

        var continueBtn = document.getElementById('lightning-recap-continue-btn');
        if (continueBtn) continueBtn.disabled = false;
    }

    var myEntrant = pu.myEntrant;

    function renderRecap(recap) {
        var lb = recap.leaderboard || [];
        var lbEl = document.getElementById('lightning-recap-leaderboard');
        if (lbEl) {
            var youLabel = (t('lobby.you') && t('lobby.you') !== 'lobby.you')
                ? t('lobby.you') : 'Du';
            var meRow = myEntrant();
            var rows = lb.map(function (p) {
                return {
                    rank: p.rank,
                    name: p.name,
                    score: p.score,
                    isYou: pu.entrantKey(p) === meRow
                };
            });
            pu.renderMedalStandings(lbEl, rows, { youLabel: youLabel });
        }

        var grid = document.getElementById('lightning-recap-grid');
        if (grid) {
            var me = myEntrant();
            var questions = recap.questions || [];
            grid.innerHTML = questions.map(function (q, qi) {
                var result = (q.results || {})[me] || 'miss';
                var ok = result === 'correct';
                var rowCls = ok ? 'lr-recap-row ok' : 'lr-recap-row no';
                var badge = ok ? '✓' : '✗';

                var html = '<div class="' + rowCls + '">' +
                    '<span class="lr-recap-badge">' + badge + '</span>' +
                    '<div class="lr-recap-body">' +
                        '<div class="lr-recap-q">' +
                            '<span class="lr-recap-qnum">' + (qi + 1) + '.</span> ' +
                            pu.escapeHtml(q.question_text) +
                        '</div>' +
                        '<div class="lr-recap-correct">' +
                            '<span class="lr-recap-tag" data-i18n="lightning.correctTag">' +
                            pu.escapeHtml(t('lightning.correctTag')) + '</span>' +
                            pu.escapeHtml(q.correct_answer) +
                        '</div>';

                if (!ok && result === 'wrong') {
                    var chosen = (q.chosen || {})[me];
                    if (chosen) {
                        html += '<div class="lr-recap-yours">' +
                            '<span class="lr-recap-tag" data-i18n="lightning.youSaidTag">' +
                            pu.escapeHtml(t('lightning.youSaidTag')) + '</span>' +
                            pu.escapeHtml(chosen) +
                            '</div>';
                    }
                }

                html += '</div></div>';
                return html;
            }).join('');
        }
    }

    function init() {
        var btns = document.querySelectorAll('[data-lightning-answer]');
        for (var i = 0; i < btns.length; i++) {
            (function (idx) {
                btns[idx].addEventListener('click', function () {
                    submitAnswer(parseInt(this.getAttribute('data-lightning-answer'), 10));
                });
            })(i);
        }
        var continueBtn = document.getElementById('lightning-recap-continue-btn');
        if (continueBtn) {
            continueBtn.addEventListener('click', function () {
                window.QuizifyPlayerUtils.hostStep(continueBtn, _send, 'next_question');
            });
        }
    }

    window.QuizifyPlayerLightning = {
        setSend: setSend,
        init: init,
        handleLightningSplash: handleLightningSplash,
        handleLightningQuestion: handleLightningQuestion,
        handleLightningTick: handleLightningTick,
        handleLightningTeamAnswer: handleLightningTeamAnswer,
        handleLightningAnswerResult: handleLightningAnswerResult,
        handleLightningRecap: handleLightningRecap,
        renderRecap: renderRecap
    };
})();


/* ============ player-hotseat.js ============ */

(function () {
    'use strict';

    var _state = {
        bidding: false,
        bidPlaced: false,
        seated: false,
        betPlaced: false,
        betSide: null,
        score: 0,
        winner: null
    };

    function t(key, vars) {
        var fn = window.QuizifyI18n && window.QuizifyI18n.t;
        return fn ? fn(key, vars) : key;
    }

    function send(type, payload) {
        var fn = window.QuizifyPlayer && window.QuizifyPlayer.send;
        if (fn) fn(type, payload);
    }

    function el(id) {
        return document.getElementById(id);
    }

    function paintQuestionImage(imgUrl) {
        var fn = window.QuizifyPlayerGame
            && window.QuizifyPlayerGame.renderQuestionImageBanner;
        if (fn) fn(imgUrl || '', null, 0);
    }

    function panel() {
        return el('hotseat-panel');
    }

    function clearPreviousQuestion() {
        var category = el('question-category');
        if (category) category.textContent = '';
        var text = el('question-text');
        if (text) text.textContent = '';
        ['answers-container', 'estimate-container', 'submission-tracker',
            'submitted-confirmation'].forEach(function (id) {
            var node = el(id);
            if (node) node.classList.add('hidden');
        });
    }

    function stage(id, show) {
        var node = el(id);
        if (node) node.classList.toggle('hidden', !show);
    }

    function setTitle(key, params) {
        var title = el('hotseat-title');
        if (!title) return;
        title.setAttribute('data-i18n', key);
        if (params) title.setAttribute('data-i18n-params', JSON.stringify(params));
        else title.removeAttribute('data-i18n-params');
        title.textContent = t(key, params);
    }

    function myEntrant() {
        var team = window.QuizifyPlayerTeam;
        var mine = (team && team.myTeam) ? team.myTeam() : null;
        if (mine && (mine.team_id || mine.name)) return mine.team_id || mine.name;
        var utils = window.QuizifyPlayerUtils;
        return (utils && utils.state) ? utils.state.playerName : null;
    }

    function isAdmin() {
        var utils = window.QuizifyPlayerUtils;
        return !!(utils && utils.state && utils.state.isAdmin);
    }

    function hide() {
        var p = panel();
        if (p) p.classList.add('hidden');
        _state.bidding = false;
    }

    function reset() {
        _state.bidding = false;
        _state.bidPlaced = false;
        _state.seated = false;
        _state.betPlaced = false;
        _state.betSide = null;
        _state.seatAnswering = false;
        _state.winner = null;
        stage('hotseat-result-stage', false);
        hide();
    }

    function handleAuctionYou(msg) {
        var p = panel();
        if (!p) return;
        _state.bidding = true;
        _state.bidPlaced = false;
        _state.seated = false;
        _state.betPlaced = false;
        _state.betSide = null;
        _state.score = msg.score || 0;

        paintQuestionImage('');
        var game = window.QuizifyPlayerGame;
        if (game && game.resetSubmissionState) game.resetSubmissionState();
        clearPreviousQuestion();

        p.classList.remove('hidden');
        p.classList.remove('wager-panel--collapsed');

        var bidStage = el('hotseat-bid-stage');
        var betStage = el('hotseat-bet-stage');
        if (bidStage) bidStage.classList.remove('hidden');
        if (betStage) betStage.classList.add('hidden');
        stage('hotseat-result-stage', false);

        var hint = el('hotseat-hint');
        var bank = el('hotseat-bank');
        var slider = el('hotseat-slider');
        var btn = el('hotseat-bid-btn');
        var count = el('hotseat-bid-count');

        setTitle('hotSeat.auctionTitle');
        if (hint) hint.textContent = t('hotSeat.auctionHint');
        if (bank) bank.textContent = _state.score;
        if (count) count.textContent = t('hotSeat.sealed');

        if (slider) {
            slider.value = '25';
            slider.disabled = false;
            slider.oninput = syncBidValue;
            syncBidValue();
        }
        if (btn) {
            btn.disabled = false;
            btn.textContent = t('hotSeat.bidSubmit');
            btn.onclick = submitBid;
        }
    }

    function syncBidValue() {
        var slider = el('hotseat-slider');
        var out = el('hotseat-value');
        if (!slider || !out) return;
        var pct = parseInt(slider.value, 10);
        var pts = Math.floor(_state.score * pct / 100);
        out.textContent = t('wager.valueFmt', { pct: pct, pts: pts });
    }

    function submitBid() {
        if (_state.bidPlaced) return;
        var slider = el('hotseat-slider');
        if (!slider) return;
        var pct = parseInt(slider.value, 10);
        _state.bidPlaced = true;
        slider.disabled = true;
        var btn = el('hotseat-bid-btn');
        if (btn) btn.disabled = true;
        send('hot_seat_bid', { bid: pct });

        var hint = el('hotseat-hint');
        if (hint) {
            hint.textContent = t('hotSeat.bidPlaced', {
                pct: pct,
                pts: Math.floor(_state.score * pct / 100)
            });
        }
    }

    function handleBidCount(msg) {
        var count = el('hotseat-bid-count');
        if (!count || !_state.bidding) return;
        count.textContent = window.QuizifyRenderShared.hotSeatBidCountText(msg);
    }

    function handleAwarded(msg) {
        var utils = window.QuizifyPlayerUtils;
        var me = (utils && utils.state) ? utils.state.playerName : null;
        _state.winner = msg.winner;
        _state.seated = (me != null && me === msg.winner);

        var hint = el('hotseat-hint');
        var bidStage = el('hotseat-bid-stage');
        if (bidStage) bidStage.classList.add('hidden');

        if (_state.seated) {
            setTitle('hotSeat.won', { pct: msg.pct, pts: msg.stake });
            if (hint) hint.textContent = t('hotSeat.seatedHint');
        } else {
            setTitle('hotSeat.lost', window.QuizifyRenderShared.hotSeatAward(msg).vars);
            if (hint) hint.textContent = '';
        }
    }

    function handleNoBids() {
        var hint = el('hotseat-hint');
        if (hint) hint.textContent = t('hotSeat.noBids');
        reset();
    }

    function handleQuestion(msg) {
        var p = panel();
        if (!p) return;
        p.classList.remove('hidden');

        var qText = el('question-text');
        if (qText && msg.question) qText.textContent = msg.question;
        var qCat = el('question-category');
        if (qCat) qCat.textContent = '';
        paintQuestionImage(msg.image_url);
        var estimateSection = el('estimate-container');
        if (estimateSection) estimateSection.classList.add('hidden');

        if (msg.you_are_seated) {
            var bidStage = el('hotseat-bid-stage');
            var betStage = el('hotseat-bet-stage');
            if (bidStage) bidStage.classList.add('hidden');
            if (betStage) betStage.classList.add('hidden');
            var hint = el('hotseat-hint');
            if (hint) hint.textContent = t('hotSeat.timeoutNote');
            renderSeatAnswers(msg.answers || []);
            return;
        }

        var spectatorAnswers = el('answers-container');
        if (spectatorAnswers) spectatorAnswers.classList.add('hidden');

        _state.score = typeof msg.score === 'number' ? msg.score : _state.score;

        if (msg.you_are_seat_team) {
            var betStage = el('hotseat-bet-stage');
            if (betStage) betStage.classList.add('hidden');
            setTitle('hotSeat.teamSeated', { name: msg.winner });
            var teamHint = el('hotseat-hint');
            if (teamHint) teamHint.textContent = '';
            return;
        }

        showBetStage(msg.winner);
    }

    function renderSeatAnswers(answers) {
        var answersSection = el('answers-container');
        if (answersSection) answersSection.classList.remove('hidden');

        var host = el('answer-buttons');
        if (!host) return;
        if (host.classList) host.classList.remove('is-locked');
        var oldChecks = host.querySelectorAll('.lock-in-check');
        for (var c = 0; c < oldChecks.length; c++) {
            if (oldChecks[c].parentNode) oldChecks[c].parentNode.removeChild(oldChecks[c]);
        }
        var buttons = host.querySelectorAll('.answer-btn');
        for (var i = 0; i < buttons.length; i++) {
            var btn = buttons[i];
            var text = answers[i];
            btn.dataset.index = String(i);
            btn.disabled = false;
            btn.classList.remove(
                'is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'hidden',
                'correct', 'wrong', 'dimmed'
            );
            var textEl = btn.querySelector('.answer-text');
            if (textEl) {
                textEl.textContent =
                    ((text && typeof text === 'object') ? text.text : text) || '';
            }
            if (i >= answers.length) btn.classList.add('hidden');
        }
        _state.seatAnswering = true;
        var shared = window.QuizifyRenderShared;
        if (shared && shared.playEntrance) {
            shared.playEntrance(el('question-text'), buttons, { fast: true });
        }
    }

    function handleSeatAnswerClick(index) {
        if (!_state.seatAnswering) return false;
        var host = el('answer-buttons');
        if (host) {
            var buttons = host.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = true;
                if (i === index) buttons[i].classList.add('is-selected');
            }
        }
        _state.seatAnswering = false;
        send('hot_seat_answer', { answer: index });
        return true;
    }

    function showBetStage(winner) {
        var betStage = el('hotseat-bet-stage');
        var hint = el('hotseat-hint');
        if (betStage) betStage.classList.remove('hidden');
        setTitle('hotSeat.betTitle', { name: winner });
        if (hint) hint.textContent = '';

        var slider = el('hotseat-bet-slider');
        if (slider) {
            slider.disabled = false;
            slider.oninput = syncBetValue;
            syncBetValue();
        }
        _state.betSide = null;
        wireBet('hotseat-bet-will', 'will');
        wireBet('hotseat-bet-wont', 'wont');
        paintBetSide();
        var place = el('hotseat-bet-place');
        if (place) place.onclick = placeBet;
    }

    function syncBetValue() {
        var slider = el('hotseat-bet-slider');
        var out = el('hotseat-bet-value');
        if (!slider || !out) return;
        var pct = parseInt(slider.value, 10);
        out.textContent = t('wager.valueFmt', {
            pct: pct,
            pts: Math.floor(_state.score * pct / 100)
        });
    }

    function wireBet(id, side) {
        var btn = el(id);
        if (!btn) return;
        btn.disabled = false;
        btn.onclick = function () {
            if (_state.betPlaced) return;
            _state.betSide = side;
            paintBetSide();
        };
    }

    function paintBetSide() {
        [['hotseat-bet-will', 'will'], ['hotseat-bet-wont', 'wont']].forEach(function (pair) {
            var b = el(pair[0]);
            if (!b) return;
            var on = _state.betSide === pair[1];
            b.setAttribute('aria-pressed', on ? 'true' : 'false');
            b.classList.toggle('is-selected', on);
        });
        var place = el('hotseat-bet-place');
        if (place) place.disabled = _state.betPlaced || !_state.betSide;
    }

    function placeBet() {
        if (_state.betPlaced || !_state.betSide) return;
        var slider = el('hotseat-bet-slider');
        var pct = slider ? parseInt(slider.value, 10) : 0;
        var side = _state.betSide;
        send('hot_seat_bet', { side: side, bet: pct });
        lockBetUi({ pct: pct, side: side });
    }

    function handleResult(msg, restored) {
        msg = msg || {};
        var p = panel();
        if (!p) {
            reset();
            return;
        }

        _state.bidding = false;
        _state.seatAnswering = false;

        p.classList.remove('hidden');
        p.classList.remove('wager-panel--collapsed');
        stage('hotseat-bid-stage', false);
        stage('hotseat-bet-stage', false);
        stage('hotseat-result-stage', true);

        var settlement = window.QuizifyRenderShared.hotSeatSettlement(msg);
        setTitle(settlement.key, settlement.vars);

        var answerEl = el('hotseat-result-answer');
        if (answerEl) {
            answerEl.textContent = msg.correct_answer
                ? t('reveal.correctAnswerWas') + ' ' + msg.correct_answer
                : '';
            answerEl.classList.toggle('hidden', !msg.correct_answer);
        }

        renderOwnSettlement(msg, restored);
        renderResultStandings(msg.leaderboard);

        var hint = el('hotseat-hint');
        if (hint) {
            hint.textContent = t(isAdmin()
                ? 'hotSeat.hostSettled' : 'lightning.recapWaitHint');
        }

        var host = el('answer-buttons');
        if (host && host.querySelectorAll) {
            var buttons = host.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) buttons[i].disabled = true;
        }
        var g = window.QuizifyPlayerGame;
        if (g && g.clearTimeAnnouncement) g.clearTimeAnnouncement();
    }

    function renderOwnSettlement(msg, restored) {
        var row = el('hotseat-result-you');
        if (!row) return;
        var deltas = msg.deltas || {};
        var me = myEntrant();
        var has = me != null
            && Object.prototype.hasOwnProperty.call(deltas, me);
        row.classList.toggle('hidden', !has);
        if (!has) return;
        var mine = deltas[me] || 0;
        var label = el('hotseat-result-you-label');
        var value = el('hotseat-result-you-delta');
        if (label) label.textContent = t('lobby.you');
        if (value) {
            value.textContent = t('reveal.pointsDelta', {
                sign: mine < 0 ? '\u2212' : '+',
                points: Math.abs(mine)
            });
        }
        row.classList.remove('hs-settle--win', 'hs-settle--lose');
        if (!restored && mine !== 0) {
            void row.offsetWidth;
            row.classList.add(mine > 0 ? 'hs-settle--win' : 'hs-settle--lose');
        }
    }

    function renderResultStandings(leaderboard) {
        var box = el('hotseat-result-standings');
        if (!box) return;
        var rows = leaderboard || [];
        var pu = window.QuizifyPlayerUtils;
        if (!pu || !pu.renderMedalStandings || !rows.length) {
            box.innerHTML = '';
            return;
        }
        var me = myEntrant();
        var youLabel = t('lobby.you');
        if (youLabel === 'lobby.you') youLabel = 'You';
        pu.renderMedalStandings(box, rows.map(function (p) {
            return {
                rank: p.rank,
                name: p.name,
                score: p.score,
                isYou: (p.entrant_id || p.name) === me
            };
        }), { youLabel: youLabel });
        var game = window.QuizifyPlayerGame;
        if (game && game.updateLeaderboard) {
            game.updateLeaderboard({ leaderboard: rows }, 'leaderboard-list');
        }
    }

    function handleTick(msg) {
        var fn = window.QuizifyPlayerGame && window.QuizifyPlayerGame.updateTimer;
        if (fn) fn(msg.remaining);
    }

    function restoreFromSnapshot(hs, snapshot) {
        if (!hs) return;
        var stage = hs.stage;

        if (stage === 'auction') {
            handleAuctionYou({ score: hs.own_bank });
            handleBidCount({ count: hs.bid_count, total: hs.bidder_count });
            if (hs.you_bid != null) {
                lockBidUi(hs.you_bid);
            }
            return;
        }

        if (stage === 'result') {
            var settled = {};
            var summary = hs.summary || {};
            for (var key in summary) {
                if (Object.prototype.hasOwnProperty.call(summary, key)) {
                    settled[key] = summary[key];
                }
            }
            settled.leaderboard = (snapshot && snapshot.leaderboard) || [];
            handleResult(settled, true);
            return;
        }

        if (stage === 'awarded') {
            clearPreviousQuestion();
            handleAwarded({
                winner: hs.winner,
                pct: hs.pct,
                stake: hs.stake,
                bids: hs.bids || []
            });
            return;
        }

        if (stage === 'question') {
            handleAwarded({
                winner: hs.winner,
                pct: hs.pct,
                stake: hs.stake,
                bids: hs.bids || []
            });
            handleQuestion(questionMessageFromSnapshot(hs));
            if (hs.you_bet) lockBetUi(hs.you_bet);
        }
    }

    function questionMessageFromSnapshot(hs) {
        var q = hs.question || {};
        var msg = {};
        for (var k in q) {
            if (Object.prototype.hasOwnProperty.call(q, k)) msg[k] = q[k];
        }
        msg.question = q.text;
        msg.answers = q.answers || [];
        msg.winner = hs.winner;
        msg.you_are_seated = !!hs.you_are_seated;
        msg.seconds = hs.time_remaining;
        msg.score = hs.own_bank;
        return msg;
    }

    function lockBidUi(pct) {
        _state.bidPlaced = true;
        var slider = el('hotseat-slider');
        var btn = el('hotseat-bid-btn');
        if (slider) slider.disabled = true;
        if (btn) btn.disabled = true;
        var hint = el('hotseat-hint');
        if (hint) {
            hint.textContent = t('hotSeat.bidPlaced', {
                pct: pct,
                pts: Math.floor((_state.score || 0) * pct / 100)
            });
        }
    }

    function lockBetUi(bet) {
        _state.betPlaced = true;
        var slider = el('hotseat-bet-slider');
        if (slider) slider.disabled = true;
        ['hotseat-bet-will', 'hotseat-bet-wont', 'hotseat-bet-place'].forEach(function (x) {
            var b = el(x);
            if (b) b.disabled = true;
        });
        var hint = el('hotseat-hint');
        if (hint) {
            hint.textContent = t('hotSeat.betPlaced', {
                pct: bet.pct,
                side: t(bet.side === 'will' ? 'hotSeat.betWill' : 'hotSeat.betWont')
            });
        }
    }

    window.QuizifyPlayerHotSeat = {
        restoreFromSnapshot: restoreFromSnapshot,
        handleAuctionYou: handleAuctionYou,
        handleBidCount: handleBidCount,
        handleAwarded: handleAwarded,
        handleNoBids: handleNoBids,
        handleQuestion: handleQuestion,
        handleSeatAnswerClick: handleSeatAnswerClick,
        handleResult: handleResult,
        handleTick: handleTick,
        reset: reset
    };

})();


/* ============ player-game.js ============ */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var utils = window.QuizifyUtils || {};
    var state = pu.state;

    var countdownInterval = null;

    var lastAnnouncedSecond = null;

    function announceTimeLeft(seconds) {
        if (seconds > 10) {
            clearTimeAnnouncement();
            return;
        }
        if (seconds !== 10 && seconds !== 5) return;
        if (seconds === lastAnnouncedSecond) return;
        lastAnnouncedSecond = seconds;
        var region = document.getElementById('timer-sr-announce');
        if (!region) return;
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var key = seconds === 10 ? 'game.timerTenLeft' : 'game.timerFiveLeft';
        region.setAttribute('data-i18n', key);
        region.textContent = t(key);
    }

    function clearTimeAnnouncement() {
        lastAnnouncedSecond = null;
        var region = document.getElementById('timer-sr-announce');
        if (!region) return;
        region.removeAttribute('data-i18n');
        region.textContent = '';
    }

    function pulseTimer(el) {
        el.classList.remove('timer--tick');
        void el.offsetWidth;
        el.classList.add('timer--tick');
    }

    function startCountdown(deadline) {
        stopCountdown();
        if (window.QuizifyPlayerSound) window.QuizifyPlayerSound.resetTick();

        var timerElement = document.getElementById('timer');
        if (!timerElement) return;

        timerElement.classList.remove('timer--warning', 'timer--critical', 'timer--tick');

        function updateCountdown() {
            var now = Date.now();
            var remaining = Math.max(0, Math.ceil((deadline - now) / 1000));

            timerElement.textContent = remaining;
            announceTimeLeft(remaining);

            _tick(remaining);

            if (remaining <= 5) {
                timerElement.classList.remove('timer--warning');
                timerElement.classList.add('timer--critical');
                pulseTimer(timerElement);
            } else if (remaining <= 10) {
                timerElement.classList.remove('timer--critical', 'timer--tick');
                timerElement.classList.add('timer--warning');
            } else {
                timerElement.classList.remove('timer--warning', 'timer--critical', 'timer--tick');
            }

            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            timerElement.setAttribute('aria-label', t('game.timerRemainingAria', { seconds: remaining }));

            if (remaining <= 0) {
                timerElement.setAttribute('aria-label', t('game.timerUpAria'));
                stopCountdown();
                _setTimeUp(true);
            }
        }

        updateCountdown();
        countdownInterval = setInterval(updateCountdown, 1000);
    }

    function stopCountdown() {
        if (countdownInterval) {
            clearInterval(countdownInterval);
            countdownInterval = null;
        }
        clearTimeAnnouncement();
        _setTimeUp(false);
    }

    var _timeUp = false;

    function _hasAnswered() {
        var grid = document.getElementById('answer-buttons');
        return !!(hasSubmitted || _guessPending ||
            (grid && grid.querySelector && grid.querySelector('.has-team-answer')));
    }

    function _tick(remaining) {
        if (!window.QuizifyPlayerSound || _hasAnswered()) return;
        window.QuizifyPlayerSound.tickFromRemaining(remaining);
    }

    function _setTimeUp(on) {
        _timeUp = !!on;
        var grid = document.getElementById('answer-buttons');
        var answered = _hasAnswered();
        var dim = _timeUp && !answered;
        var timerEl = document.getElementById('timer');
        if (timerEl && timerEl.classList) timerEl.classList.toggle('timer--up', dim);
        if (timerEl && _timeUp) {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var upText = t('game.timerUpAria');
            timerEl.textContent = (dim && upText && upText !== 'game.timerUpAria') ? upText : '0';
        }
        if (grid && grid.classList) grid.classList.toggle('is-time-up', dim);
        var est = document.getElementById('estimate-container');
        if (est && est.classList) est.classList.toggle('is-time-up', dim);
        var pwr = document.getElementById('powerup-btn');
        if (pwr && pwr.classList) pwr.classList.toggle('is-time-up', dim);
    }

    var FROZEN_RING_CIRC = 2 * Math.PI * 54;
    var frozenInterval = null;

    function startFrozenOverlay(seconds) {
        var overlay = document.getElementById('frozen-overlay');
        if (!overlay) return;

        var total = Math.max(0, Math.floor(Number(seconds) || 0));
        if (total <= 0) { stopFrozenOverlay(); return; }

        if (frozenInterval) {
            clearInterval(frozenInterval);
            frozenInterval = null;
        }

        var numEl = document.getElementById('frozen-ring-num');
        var progEl = document.getElementById('frozen-ring-prog');

        overlay.classList.remove('hidden');

        var remaining = total;

        function paint() {
            if (numEl) numEl.textContent = remaining;
            if (progEl) {
                var elapsedFrac = (total - remaining) / total;
                progEl.style.strokeDashoffset = (FROZEN_RING_CIRC * elapsedFrac).toFixed(2);
            }
        }

        paint();

        frozenInterval = setInterval(function () {
            remaining -= 1;
            if (remaining <= 0) {
                remaining = 0;
                paint();
                stopFrozenOverlay();
                return;
            }
            paint();
        }, 1000);
    }

    function stopFrozenOverlay() {
        if (frozenInterval) {
            clearInterval(frozenInterval);
            frozenInterval = null;
        }
        var overlay = document.getElementById('frozen-overlay');
        if (overlay) overlay.classList.add('hidden');
    }

    function isFrozen() {
        var overlay = document.getElementById('frozen-overlay');
        return !!(overlay && !overlay.classList.contains('hidden'));
    }

    function updateTimer(remaining) {
        var timerElement = document.getElementById('timer');
        if (!timerElement) return;

        var displaySeconds = Math.ceil(remaining);
        if (_timeUp) {
            if (displaySeconds <= 0) return;
            _setTimeUp(false);
        }
        timerElement.textContent = displaySeconds;
        announceTimeLeft(displaySeconds);

        _tick(remaining);

        setRevealBlur(remaining);

        if (remaining <= 5) {
            timerElement.classList.remove('timer--warning');
            timerElement.classList.add('timer--critical');
        } else if (remaining <= 10) {
            timerElement.classList.remove('timer--critical');
            timerElement.classList.add('timer--warning');
        } else {
            timerElement.classList.remove('timer--warning', 'timer--critical');
        }

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        timerElement.setAttribute('aria-label', t('game.timerRemainingAria', { seconds: displaySeconds }));
    }

    var _wagerState = { active: false, submitted: false, pct: 0, round: 0 };

    var REVEAL_MAX_BLUR_PX = 14;

    function _revealTargets() {
        return [
            document.getElementById('question-image'),
            document.getElementById('image-zoom-img'),
        ];
    }

    var _reveal = window.QuizifyRenderShared.createProgressiveReveal({
        maxBlurPx: REVEAL_MAX_BLUR_PX,
        targets: _revealTargets
    });

    function setRevealBlur(remaining) {
        _reveal.set(remaining);
    }

    function clearRevealBlur() {
        _reveal.clear();
    }

    function renderQuestionImageBanner(imgUrl, revealStyle, duration) {
        var media = document.getElementById('question-media');
        var img = document.getElementById('question-image');
        if (!media || !img) return;
        var safeImg = (window.QuizifyUtils && window.QuizifyUtils.safeImageUrl)
            ? window.QuizifyUtils.safeImageUrl(imgUrl) : '';
        var missing = document.getElementById('question-image-missing');
        media.classList.remove('is-loading', 'is-missing');
        if (missing) missing.hidden = true;
        img.onload = function() { media.classList.remove('is-loading'); };
        img.onerror = function() {
            img.removeAttribute('src');
            media.classList.remove('is-loading');
            media.classList.add('is-missing');
            if (missing) missing.hidden = false;
        };
        clearRevealBlur();
        if (safeImg) {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            media.classList.add('is-loading');
            img.src = safeImg;
            img.alt = t('game.questionImageAlt');
            media.hidden = false;
            if (revealStyle === 'progressive') {
                _reveal.arm(duration);
            }
        } else {
            img.removeAttribute('src');
            img.alt = '';
            media.hidden = true;
        }
    }

    function preloadNextImage(imgUrl) {
        window.QuizifyRenderShared.preloadNextImage(imgUrl);
    }

    function _initImageZoom() {
        var zoomBtn = document.getElementById('question-image-zoom');
        var overlay = document.getElementById('image-zoom-overlay');
        var closeBtn = document.getElementById('image-zoom-close');
        var overlayImg = document.getElementById('image-zoom-img');
        var bannerImg = document.getElementById('question-image');
        if (!zoomBtn || !overlay || !overlayImg) return;

        function open() {
            if (bannerImg && bannerImg.getAttribute('src')) {
                overlayImg.src = bannerImg.getAttribute('src');
                overlayImg.alt = bannerImg.getAttribute('alt') || '';
                overlay.classList.remove('hidden');
            }
        }
        function close() {
            overlay.classList.add('hidden');
            overlayImg.removeAttribute('src');
        }
        zoomBtn.addEventListener('click', open);
        if (closeBtn) closeBtn.addEventListener('click', close);
        overlay.addEventListener('click', function(e) {
            if (e.target === overlay) close();
        });
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && !overlay.classList.contains('hidden')) close();
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', _initImageZoom);
    } else {
        _initImageZoom();
    }

    var _isEstimateRound = false;

    var DIFFICULTY_ICONS = { 'easy': '🌱', 'medium': '🎯', 'hard': '🔥' };

    function paintDifficultyBadge(difficulty) {
        var badge = document.getElementById('game-difficulty-badge');
        if (!badge) return;
        var diff = String(difficulty || '').toLowerCase();
        if (!DIFFICULTY_ICONS[diff]) {
            badge.textContent = '';
            badge.classList.add('hidden');
            return;
        }
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var key = 'difficulties.' + diff;
        badge.innerHTML = DIFFICULTY_ICONS[diff] + ' <span data-i18n="' + key + '">'
            + pu.escapeHtml(t(key)) + '</span>';
        badge.classList.remove('hidden');
    }

    function renderQuestion(data) {
        var questionText = document.getElementById('question-text');
        var questionCategory = document.getElementById('question-category');
        var answerButtons = document.getElementById('answer-buttons');

        if (questionText) questionText.textContent = data.question_text || '';
        if (questionCategory) questionCategory.textContent = data.category || '';
        paintDifficultyBadge(data.difficulty);

        renderQuestionImageBanner(
            data.image_url, data.reveal_style,
            data.reveal_duration || data.timer_duration
        );
        if (typeof data.timer_duration === 'number') {
            setRevealBlur(data.timer_duration);
        }

        _isEstimateRound = (data.question_type === 'estimate');
        var estimateContainer = document.getElementById('estimate-container');
        var answersContainer = document.getElementById('answers-container');
        if (_isEstimateRound) {
            if (estimateContainer) estimateContainer.classList.remove('hidden');
            if (answersContainer) answersContainer.classList.add('hidden');
            _showWagerBadge(false);
            renderEstimateInput(data);
            _playQuestionEntrance(questionText, []);
            return;
        }
        if (estimateContainer) estimateContainer.classList.add('hidden');
        if (answersContainer) answersContainer.classList.remove('hidden');

        _showWagerBadge(!!data.is_final_round);

        if (answerButtons) {
            var answers = data.answers || [];
            var buttons = answerButtons.querySelectorAll('.answer-btn');

            for (var i = 0; i < buttons.length; i++) {
                var btn = buttons[i];
                btn.dataset.index = String(i);

                var textEl = btn.querySelector('.answer-text');
                if (textEl) {
                    var a = answers[i];
                    textEl.textContent = ((a && typeof a === 'object') ? a.text : a) || '';
                }

                if (hasSubmitted && lastSubmittedIndex === i) {
                    btn.disabled = true;
                    btn.classList.add('is-selected');
                    btn.classList.remove('is-correct', 'is-wrong', 'is-eliminated', 'hidden');
                } else if (hasSubmitted) {
                    btn.disabled = true;
                    btn.classList.remove('is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'hidden');
                } else {
                    btn.disabled = false;
                    btn.classList.remove('is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'hidden');
                }
            }
        }

        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.toggle('hidden', !hasSubmitted);

        _playQuestionEntrance(questionText,
            answerButtons ? answerButtons.querySelectorAll('.answer-btn') : []);
    }

    function _playQuestionEntrance(head, tiles, fast) {
        var shared = window.QuizifyRenderShared;
        if (shared && shared.playEntrance) shared.playEntrance(head, tiles, { fast: !!fast });
    }

    var LOCK_CHECK_PATH = 'M5 12.5l4.5 4.5L19 7.5';

    function _lockCheckSvg() {
        var ns = 'http://www.w3.org/2000/svg';
        var svg = document.createElementNS(ns, 'svg');
        svg.setAttribute('class', 'lock-in-check');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('aria-hidden', 'true');
        svg.setAttribute('focusable', 'false');
        var path = document.createElementNS(ns, 'path');
        path.setAttribute('d', LOCK_CHECK_PATH);
        svg.appendChild(path);
        return svg;
    }

    function _estimateLockIn(on, animate) {
        var box = document.getElementById('estimate-container');
        var conf = document.getElementById('estimate-submitted-confirmation');
        if (box) box.classList.toggle('est-locked', on);
        if (!conf) return;
        var old = conf.querySelector('.lock-in-check');
        if (old) conf.removeChild(old);
        conf.classList.remove('est-lock-anim');
        if (on && animate && document.createElementNS &&
            window.QuizifyRenderShared && !window.QuizifyRenderShared.prefersReducedMotion()) {
            conf.insertBefore(_lockCheckSvg(), conf.firstChild);
            conf.classList.add('est-lock-anim');
        }
    }

    function _applyLockIn(selectedIndex) {
        var grid = document.getElementById('answer-buttons');
        if (grid && grid.classList) grid.classList.add('is-locked');
        if (grid && grid.querySelectorAll && selectedIndex >= 0 &&
            document.createElementNS) {
            var buttons = grid.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                var btn = buttons[i];
                if (parseInt(btn.dataset.index, 10) !== selectedIndex) continue;
                if (btn.querySelector && btn.querySelector('.lock-in-check')) continue;
                btn.appendChild(_lockCheckSvg());
            }
        }
        _paintSentLine();
    }

    function _clearLockIn() {
        var grid = document.getElementById('answer-buttons');
        if (!grid) return;
        if (grid.classList) grid.classList.remove('is-locked');
        if (grid.querySelectorAll) {
            var checks = grid.querySelectorAll('.lock-in-check');
            for (var i = 0; i < checks.length; i++) {
                if (checks[i].parentNode) checks[i].parentNode.removeChild(checks[i]);
            }
        }
        _paintSentLine();
    }

    function _stillAnswering() {
        var mine = myEntrant();
        return _latestPlayers.filter(function (p) {
            return p && !p.submitted && entrantKey(p) !== mine;
        }).length;
    }

    function _paintSentLine() {
        var line = document.getElementById('lock-in-status-text');
        if (!line) return;
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || null;
        var left = hasSubmitted ? _stillAnswering() : 0;
        var text;
        if (left > 0) {
            text = t ? t('game.sentWaiting', { count: left }) : '';
        } else {
            text = t ? t('game.sent') : '';
        }
        if (text && text.indexOf('game.') !== 0) line.textContent = text;
    }

    var _estimate = { min: 0, max: 100, step: 1, unit: '' };

    function _formatEstimateValue(val) {
        var n = (Math.round(val * 1000) / 1000);
        var I = window.QuizifyI18n;
        var text = (I && I.formatNumber)
            ? I.formatNumber(n)
            : ((n === Math.round(n)) ? String(Math.round(n)) : String(n));
        return _estimate.unit ? (text + ' ' + _estimate.unit) : text;
    }

    function renderEstimateInput(data) {
        var est = data.estimate || {};
        var min = Number(est.min);
        var max = Number(est.max);
        var step = Number(est.step) || 1;
        if (!isFinite(min)) min = 0;
        if (!isFinite(max) || max <= min) max = min + 100;
        _estimate = { min: min, max: max, step: step, unit: est.unit || '' };

        var slider = document.getElementById('estimate-slider');
        var valueEl = document.getElementById('estimate-value');
        var minEl = document.getElementById('estimate-scale-min');
        var midEl = document.getElementById('estimate-scale-mid');
        var maxEl = document.getElementById('estimate-scale-max');
        var submitBtn = document.getElementById('estimate-submit-btn');
        var confirmation = document.getElementById('estimate-submitted-confirmation');

        var mid = min + (max - min) / 2;

        if (minEl) minEl.textContent = _formatEstimateValue(min);
        if (midEl) midEl.textContent = _formatEstimateValue(mid);
        if (maxEl) maxEl.textContent = _formatEstimateValue(max);

        if (slider) {
            slider.min = String(min);
            slider.max = String(max);
            slider.step = String(step);
            var startVal = Math.round((mid - min) / step) * step + min;
            slider.value = String(startVal);
            slider.setAttribute('aria-valuemin', String(min));
            slider.setAttribute('aria-valuemax', String(max));

            function syncValue() {
                var v = Number(slider.value);
                if (valueEl) valueEl.textContent = _formatEstimateValue(v);
                slider.setAttribute('aria-valuenow', String(v));
                slider.setAttribute('aria-valuetext', _formatEstimateValue(v));
            }
            slider.oninput = syncValue;
            syncValue();

            slider.disabled = hasSubmitted || _guessPending;
        }

        if (submitBtn) {
            submitBtn.disabled = hasSubmitted || _guessPending;
            submitBtn.onclick = function () {
                var send = window.QuizifyPlayer && window.QuizifyPlayer.send;
                if (send) handleEstimateSubmit(send);
            };
        }

        if (confirmation) confirmation.classList.toggle('hidden', !hasSubmitted);
        _estimateLockIn(hasSubmitted, false);
    }

    var _guessPending = false;

    var GUESS_RETRYABLE_CODES = { INVALID_ACTION: true, FROZEN: true };

    function _setEstimateLocked(locked) {
        var slider = document.getElementById('estimate-slider');
        if (slider) slider.disabled = locked;
        var submitBtn = document.getElementById('estimate-submit-btn');
        if (submitBtn) submitBtn.disabled = locked;
    }

    function _showEstimateConfirmation(show) {
        var confirmation = document.getElementById('estimate-submitted-confirmation');
        if (confirmation) confirmation.classList.toggle('hidden', !show);
    }

    function handleEstimateSubmit(sendFn) {
        if (hasSubmitted || _guessPending || _timeUp) return;
        if (isFrozen()) return;
        var slider = document.getElementById('estimate-slider');
        if (!slider) return;
        var guess = Number(slider.value);
        if (!isFinite(guess)) return;
        guess = Math.max(_estimate.min, Math.min(_estimate.max, guess));

        _guessPending = true;
        _setEstimateLocked(true);

        if (sendFn('submit_answer', { guess: guess }) === false) {
            _guessPending = false;
            _setEstimateLocked(false);
        }
    }

    function confirmGuess() {
        if (!_guessPending) return;
        _guessPending = false;
        hasSubmitted = true;
        _setEstimateLocked(true);
        _showEstimateConfirmation(true);
        _estimateLockIn(true, true);
    }

    function releaseGuess(code) {
        if (!_guessPending) return;
        if (!GUESS_RETRYABLE_CODES[code]) return;
        _guessPending = false;
        _setEstimateLocked(false);
        _showEstimateConfirmation(false);
        _estimateLockIn(false);
    }

    function renderWagerWindow(data) {
        var panel = document.getElementById('wager-panel');
        if (!panel) return;

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var round = data.round_num || 0;

        if (_wagerState.active && _wagerState.round === round) return;
        _wagerState = { active: true, submitted: false, pct: 0, round: round };

        var categoryEl = document.getElementById('question-category');
        var questionText = document.getElementById('question-text');
        var media = document.getElementById('question-media');
        var answersContainer = document.getElementById('answers-container');
        var estimateContainer = document.getElementById('estimate-container');
        var tracker = document.getElementById('submission-tracker');
        var confirmation = document.getElementById('submitted-confirmation');
        if (categoryEl) categoryEl.textContent = data.category || '';
        if (questionText) questionText.textContent = t('wager.questionPending');
        if (media) media.hidden = true;
        if (answersContainer) answersContainer.classList.add('hidden');
        if (estimateContainer) estimateContainer.classList.add('hidden');
        if (tracker) tracker.classList.add('hidden');
        if (confirmation) confirmation.classList.add('hidden');

        var seconds = data.window_duration || 0;
        if (seconds > 0) startCountdown(Date.now() + seconds * 1000);

        panel.classList.remove('hidden', 'wager-panel--collapsed');
        _paintWagerPanel(data.player_score || 0);

        if (data.you_wagered != null) _lockWagerUi(data.you_wagered);
    }

    function _showWagerBadge(isFinal) {
        var panel = document.getElementById('wager-panel');
        var tracker = document.getElementById('submission-tracker');
        if (tracker) tracker.classList.remove('hidden');
        _wagerState.active = false;
        if (!panel) return;
        if (!isFinal || !_wagerState.submitted) {
            panel.classList.add('hidden');
            return;
        }
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        panel.classList.remove('hidden');
        panel.classList.add('wager-panel--collapsed');
        var titleEl = document.getElementById('wager-panel-title');
        if (titleEl) titleEl.textContent = t('wager.locked', { pct: _wagerState.pct });
    }

    function _lockWagerUi(pct, live) {
        _wagerState.submitted = true;
        _wagerState.pct = pct;

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var panel = document.getElementById('wager-panel');
        var slider = document.getElementById('wager-slider');
        var submitBtn = document.getElementById('wager-submit-btn');
        var titleEl = document.getElementById('wager-panel-title');
        var hintEl = document.getElementById('wager-panel-hint');
        var timeoutNoteEl = document.getElementById('wager-panel-timeout-note');

        if (slider) {
            slider.value = String(pct);
            slider.disabled = true;
        }
        if (submitBtn) submitBtn.disabled = true;
        var st = _wagerState;
        var stake = Math.floor((st.score || 0) * pct / 100);
        var RS = window.QuizifyRenderShared;
        var bankEl = document.getElementById('wager-bank');
        function collapse() {
            if (panel && st === _wagerState && st.submitted) panel.classList.add('wager-panel--collapsed');
        }
        if (live && stake > 0 && bankEl && bankEl.parentNode && RS && RS.rollDigits &&
            !RS.prefersReducedMotion()) {
            st.stake = stake;
            RS.rollDigits(bankEl, st.score, st.score - stake);
            var chip = document.createElement('span');
            chip.className = 'wager-stake-chip';
            chip.textContent = '\u2212' + stake;
            bankEl.parentNode.appendChild(chip);
            setTimeout(function () {
                if (chip.parentNode) chip.parentNode.removeChild(chip);
                collapse();
            }, 750);
        } else {
            collapse();
        }
        if (titleEl) titleEl.textContent = t('wager.locked', { pct: pct });
        if (hintEl) hintEl.textContent = t('wager.waitingForOthers');
        if (timeoutNoteEl) timeoutNoteEl.textContent = '';
    }

    function takeWagerStake() {
        var n = _wagerState.stake || 0;
        _wagerState.stake = 0;
        return n;
    }

    function _paintWagerPanel(currentScore) {
        var panel = document.getElementById('wager-panel');
        if (!panel) return;

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        var titleEl = document.getElementById('wager-panel-title');
        var hintEl = document.getElementById('wager-panel-hint');
        var timeoutNoteEl = document.getElementById('wager-panel-timeout-note');
        var slider = document.getElementById('wager-slider');
        var valueEl = document.getElementById('wager-value');
        var bankEl = document.getElementById('wager-bank');
        var submitBtn = document.getElementById('wager-submit-btn');

        if (titleEl) titleEl.textContent = t('wager.title');
        if (hintEl) hintEl.textContent = t('wager.hint');
        if (timeoutNoteEl) timeoutNoteEl.textContent = t('wager.timeoutNote');
        if (bankEl) bankEl.textContent = currentScore;
        _wagerState.score = currentScore;
        if (slider) {
            slider.value = '25';
            slider.disabled = false;
        }

        function syncValue() {
            var pct = parseInt(slider.value, 10);
            var pts = Math.floor(currentScore * pct / 100);
            if (valueEl) valueEl.textContent = t('wager.valueFmt', { pct: pct, pts: pts });
        }
        if (slider && valueEl) {
            slider.oninput = syncValue;
            syncValue();
        }

        if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.textContent = t('wager.submit');
            submitBtn.onclick = function () {
                if (_wagerState.submitted) return;
                var pct = parseInt(slider.value, 10);
                _lockWagerUi(pct, true);
                var send = window.QuizifyPlayer && window.QuizifyPlayer.send;
                if (send) send('submit_wager', { wager: pct });
            };
        }
    }

    var hasSubmitted = false;
    var lastSubmittedIndex = -1;

    function handleAnswerClick(selectedIndex, sendFn) {
        if (hasSubmitted || _timeUp) return;
        if (isFrozen()) return;

        var teamMod = window.QuizifyPlayerTeam;
        if (teamMod && teamMod.isTeamMode()) {
            lastSubmittedIndex = selectedIndex;
            sendFn('submit_answer', { answer_index: selectedIndex });
            return;
        }

        hasSubmitted = true;
        lastSubmittedIndex = selectedIndex;

        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            var buttons = answerButtons.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = true;
                if (parseInt(buttons[i].dataset.index, 10) === selectedIndex) {
                    buttons[i].classList.add('is-selected');
                }
            }
        }

        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.remove('hidden');
        _applyLockIn(selectedIndex);

        sendFn('submit_answer', { answer_index: selectedIndex });
    }

    function getLastSubmittedIndex() {
        return lastSubmittedIndex;
    }

    function lockSubmitted(selectedIndex) {
        hasSubmitted = true;
        _guessPending = false;
        var marked = (typeof selectedIndex === 'number' && selectedIndex >= 0)
            ? selectedIndex : -1;
        if (marked >= 0) lastSubmittedIndex = marked;
        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            var buttons = answerButtons.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = true;
                if (marked >= 0 &&
                    parseInt(buttons[i].dataset.index, 10) === marked) {
                    buttons[i].classList.add('is-selected');
                }
            }
        }
        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.remove('hidden');
        if (!_isEstimateRound) _applyLockIn(marked);

        var slider = document.getElementById('estimate-slider');
        if (slider) slider.disabled = true;
        var estSubmitBtn = document.getElementById('estimate-submit-btn');
        if (estSubmitBtn) estSubmitBtn.disabled = true;
        var estConfirm = document.getElementById('estimate-submitted-confirmation');
        if (estConfirm) estConfirm.classList.remove('hidden');
        _estimateLockIn(true, false);
        if (_timeUp) _setTimeUp(true);
    }

    function resetSubmissionState() {
        hasSubmitted = false;
        lastSubmittedIndex = -1;
        _guessPending = false;

        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            var buttons = answerButtons.querySelectorAll('.answer-btn');
            for (var i = 0; i < buttons.length; i++) {
                buttons[i].disabled = false;
                buttons[i].classList.remove('is-selected', 'is-correct', 'is-wrong', 'is-eliminated', 'correct', 'wrong', 'dimmed', 'is-team-locked', 'has-team-answer');
            }
        }

        var confirmation = document.getElementById('submitted-confirmation');
        if (confirmation) confirmation.classList.add('hidden');
        _clearLockIn();

        var slider = document.getElementById('estimate-slider');
        if (slider) slider.disabled = false;
        var estSubmitBtn = document.getElementById('estimate-submit-btn');
        if (estSubmitBtn) estSubmitBtn.disabled = false;
        var estConfirm = document.getElementById('estimate-submitted-confirmation');
        if (estConfirm) estConfirm.classList.add('hidden');
        _estimateLockIn(false);

        if (_latestPlayers.length) {
            renderSubmissionTracker(_latestPlayers.map(function (p) {
                return Object.assign({}, p, { submitted: false });
            }));
        }
    }

    function getInitials(name) {
        if (!name) return '?';
        var trimmed = name.trim();
        if (!trimmed) return '?';

        var parts = trimmed.split(/[\s-]+/).filter(Boolean);
        if (parts.length >= 2) {
            return (parts[0][0] + parts[1][0]).toUpperCase();
        }
        return trimmed.slice(0, Math.min(2, trimmed.length)).toUpperCase();
    }

    var _latestPlayers = [];

    function renderSubmissionTracker(players) {
        var tracker = document.getElementById('submission-tracker');
        var container = document.getElementById('submitted-players');

        var playerList = players || [];
        _latestPlayers = playerList;
        _refreshOpenStealPicker(playerList);

        if (!tracker || !container) return;
        var submittedCount = playerList.filter(function (p) {
            return p.submitted;
        }).length;
        var totalCount = playerList.length;

        var allSubmitted = submittedCount === totalCount && totalCount > 0;
        tracker.classList.toggle('all-submitted', allSubmitted);
        _paintSentLine();

        var mine = myEntrant();
        container.innerHTML = playerList.map(function (player) {
            var initials = getInitials(player.name);
            var isCurrentPlayer = entrantKey(player) === mine;
            var isDisconnected = player.connected === false;
            var classes = [
                'player-indicator',
                player.submitted ? 'is-submitted' : '',
                isCurrentPlayer ? 'is-current-player' : '',
                isDisconnected ? 'player-indicator--disconnected' : ''
            ].filter(Boolean).join(' ');

            return '<div class="' + classes + '">' +
                '<div class="player-avatar">' +
                    '<span class="player-initials">' + pu.escapeHtml(initials) + '</span>' +
                '</div>' +
                '<span class="player-name">' + pu.escapeHtml(player.name) + '</span>' +
            '</div>';
        }).join('');
    }

    function resetSubmissionRoster() {
        renderSubmissionTracker([]);
    }

    var _prevLeaderboardRanks = {};

    var myEntrant = pu.myEntrant;
    var entrantKey = pu.entrantKey;

    function resetRankMemo() {
        _prevLeaderboardRanks = {};
        _shownScores = {};
        _shownStreaks = {};
    }

    var _shownScores = {};
    var _shownStreaks = {};

    function updateLeaderboard(data, targetListId) {
        var leaderboard = data.leaderboard || [];
        var listEl = document.getElementById(targetListId || 'leaderboard-list');
        if (!listEl) return;

        var me = myEntrant();
        leaderboard.forEach(function (entry) {
            entry.is_current = (entrantKey(entry) === me);
            var prevRank = _prevLeaderboardRanks[entrantKey(entry)];
            if (prevRank !== undefined && prevRank !== entry.rank) {
                entry.rank_delta = prevRank - entry.rank;
            } else {
                entry.rank_delta = 0;
            }
        });

        var displayList = compressLeaderboard(leaderboard, me);

        var oldPositions = {};
        listEl.querySelectorAll('.leaderboard-entry[data-entrant]').forEach(function(el) {
            oldPositions[el.dataset.entrant] = el.getBoundingClientRect().top;
        });

        var html = '';
        displayList.forEach(function (entry) {
            html += renderLeaderboardEntry(entry);
        });

        var RS = window.QuizifyRenderShared;
        var ghosts = (RS && RS.captureRemoved)
            ? RS.captureRemoved(listEl, '.leaderboard-entry[data-entrant]',
                leaderboard.map(function (e) { return String(entrantKey(e)); }))
            : [];
        listEl.innerHTML = html;

        var shared = window.QuizifyRenderShared;
        if (shared && shared.rollScores && listEl.querySelectorAll) {
            var rows = displayList.filter(function (e) { return !e.separator; });
            shared.rollScores(
                listEl.querySelectorAll('.entry-score'),
                rows.map(function (e) { return { key: entrantKey(e), score: e.score }; }),
                _shownScores
            );
            shared.motionStreaks(
                listEl.querySelectorAll('.leaderboard-entry'),
                rows.map(function (e) {
                    return { key: entrantKey(e), streak: e.streak_active ? e.streak : 0 };
                }),
                _shownStreaks
            );
        }

        var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (!prefersReduced && Object.keys(oldPositions).length > 0) {
            listEl.querySelectorAll('.leaderboard-entry[data-entrant]').forEach(function(el) {
                var key = el.dataset.entrant;
                if (oldPositions[key] !== undefined) {
                    var newTop = el.getBoundingClientRect().top;
                    var delta = oldPositions[key] - newTop;
                    if (Math.abs(delta) > 2) {
                        el.style.transform = 'translateY(' + delta + 'px)';
                        el.style.transition = 'none';
                        requestAnimationFrame(function() {
                            el.style.transition = 'transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94)';
                            if (ghosts.length) el.style.transitionDelay = 'var(--dur-removed-lead)';
                            el.style.transform = '';
                        });
                    }
                }
            });
        }

        if (ghosts.length) RS.slideRemoved(listEl, ghosts);

        leaderboard.forEach(function(entry) {
            _prevLeaderboardRanks[entrantKey(entry)] = entry.rank;
        });

        if (leaderboard.length > 8) {
            scrollToCurrentPlayer(listEl);
        }

        updateLeaderboardSummary(leaderboard);
    }

    function compressLeaderboard(players, currentEntrant) {
        if (players.length <= 10) return players;

        var top5 = players.slice(0, 5);
        var bottom3 = players.slice(-3);
        var currentIdx = -1;

        for (var i = 0; i < players.length; i++) {
            if (entrantKey(players[i]) === currentEntrant) {
                currentIdx = i;
                break;
            }
        }

        if (currentIdx < 5 || currentIdx >= players.length - 3) {
            return [].concat(top5, [{ separator: true }], bottom3);
        }

        return [].concat(
            top5,
            [{ separator: true }],
            [players[currentIdx]],
            [{ separator: true }],
            bottom3
        );
    }

    function renderLeaderboardEntry(entry) {
        if (entry.separator) {
            return '<div class="leaderboard-separator">...</div>';
        }

        var rank = entry.rank || 0;
        var rankClass = rank <= 3 ? ' rank-' + rank : '';
        var currentClass = entry.is_current ? ' is-current' : '';
        var disconnectedClass = entry.connected === false ? ' is-disconnected' : '';
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var youBadge = entry.is_current
            ? '<span class="you-badge">(<span data-i18n="lobby.you">'
                + pu.escapeHtml(t('lobby.you')) + '</span>)</span>'
            : '';
        var streakBadge = entry.streak_active
            ? '<span class="leaderboard-streak">' + entry.streak + 'x</span>'
            : '';
        var deltaBadge = '';
        if (entry.rank_delta > 0) {
            deltaBadge = '<span class="rank-delta rank-delta--up">▲' + entry.rank_delta + '</span>';
        } else if (entry.rank_delta < 0) {
            deltaBadge = '<span class="rank-delta rank-delta--down">▼' + Math.abs(entry.rank_delta) + '</span>';
        }

        var colorDot = entry.color
            ? '<span class="player-color-dot" style="background:' + entry.color + '"></span>'
            : '';
        var colorBorder = entry.color ? ' style="border-left:3px solid ' + entry.color + '"' : '';
        return '<div class="leaderboard-entry' + currentClass + disconnectedClass + '"' + colorBorder + ' data-entrant="' + pu.escapeHtml(entrantKey(entry)) + '">' +
            '<span class="entry-rank' + rankClass + '">' + rank + '</span>' +
            colorDot +
            '<span class="entry-name">' + pu.escapeHtml(entry.name) + youBadge + '</span>' +
            deltaBadge +
            '<span class="entry-score">' + entry.score + '</span>' +
            streakBadge +
        '</div>';
    }

    function scrollToCurrentPlayer(listEl) {
        var currentEntry = listEl.querySelector('.leaderboard-entry.is-current');
        if (currentEntry) {
            currentEntry.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    }

    function updateLeaderboardSummary(leaderboard) {
        var summaryIds = ['leaderboard-summary', 'reveal-leaderboard-summary'];
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        summaryIds.forEach(function (id) {
            var summaryEl = document.getElementById(id);
            if (!summaryEl || !leaderboard || leaderboard.length === 0) return;

            var leader = leaderboard[0];
            if (!leader) return;

            var summary = leader.name + ': ' + leader.score;
            var others = leaderboard.length - 1;
            if (others < 1) {
                summaryEl.textContent = summary;
                return;
            }
            var key = 'lobby.andOthers';
            var params = { count: others };
            var more = document.createElement('span');
            more.setAttribute('data-i18n', key);
            if (params) more.setAttribute('data-i18n-params', JSON.stringify(params));
            more.textContent = t(key, params);
            summaryEl.textContent = summary + '  ';
            summaryEl.appendChild(more);
        });
    }

    var POWERUP_ICONS = {
        joker: '🃏',
        double_points: '✨',
        freeze: '🧊',
        time_boost: '⏰',
        steal: '🥷',
    };

    var POWERUP_HINTS = {
        joker: 'powerups.jokerHint',
        double_points: 'powerups.doublePointsHint',
        freeze: 'powerups.freezeHint',
        time_boost: 'powerups.timeBoostHint',
        steal: 'powerups.stealHint2',
    };

    function renderPowerUp(powerupType) {
        var powerupBtn = document.getElementById('powerup-btn');
        if (!powerupBtn) return;
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var hintEl = document.getElementById('powerup-hint');

        if (powerupType) {
            powerupBtn.classList.remove('hidden', 'used');
            var label = powerupBtn.querySelector('.powerup-label') || powerupBtn;
            var icon = POWERUP_ICONS[powerupType] || '';
            var name = t('powerups.' + powerupType);
            label.textContent = icon ? icon + ' ' + name : name;
            if (label !== powerupBtn) label.removeAttribute('data-i18n');

            if (hintEl) {
                var hintKey = POWERUP_HINTS[powerupType];
                hintEl.textContent = hintKey ? t(hintKey) : '';
                hintEl.classList.toggle('hidden', !hintKey);
            }
        } else {
            powerupBtn.classList.add('hidden');
            if (hintEl) hintEl.classList.add('hidden');
        }
    }

    function _answeredBadgeHtml() {
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        return '<span class="powerup-target-submitted">' +
            pu.escapeHtml(t('powerups.targetAnswered')) + '</span>';
    }

    function _setStealOptionEnabled(btn, enabled) {
        btn.disabled = !enabled;
        if (enabled) {
            btn.removeAttribute('aria-disabled');
        } else {
            btn.setAttribute('aria-disabled', 'true');
        }
    }

    function _refreshOpenStealPicker(players) {
        var modal = document.getElementById('powerup-target-modal');
        var listEl = document.getElementById('powerup-target-list');
        if (!modal || !listEl || modal.classList.contains('hidden')) return;
        if (modal.dataset.powerup !== 'steal') return;
        var submitted = {};
        (players || []).forEach(function (p) {
            if (p && p.name && p.submitted) submitted[p.name] = true;
        });
        listEl.querySelectorAll('.powerup-target-option').forEach(function (btn) {
            if (btn.disabled && submitted[btn.dataset.player]) {
                _setStealOptionEnabled(btn, true);
                btn.innerHTML += _answeredBadgeHtml();
            }
        });
    }

    function powerupNeedsTarget(powerupType) {
        return powerupType === 'freeze' || powerupType === 'steal';
    }

    function openTargetPicker(powerupType, onConfirm, roster) {
        var modal = document.getElementById('powerup-target-modal');
        var titleEl = document.getElementById('powerup-target-title');
        var hintEl = document.getElementById('powerup-target-hint');
        var listEl = document.getElementById('powerup-target-list');
        var cancelBtn = document.getElementById('powerup-target-cancel');
        if (!modal || !listEl) return;

        if (typeof modal._teardown === 'function') {
            modal._teardown();
            modal._teardown = null;
        }

        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };

        var me = pu.state.playerName;
        var teamApi = window.QuizifyPlayerTeam;
        var myTeam = teamApi && teamApi.myTeam && teamApi.myTeam();
        var teammates = (myTeam && myTeam.members) || [];
        var submittedByName = {};
        (_latestPlayers || []).forEach(function (p) {
            if (p && p.name && p.submitted) submittedByName[p.name] = true;
        });
        var source = (roster && roster.length) ? roster : (_latestPlayers || []);
        var opponents = source.filter(function (p) {
            return p && p.name && p.name !== me && p.connected !== false &&
                teammates.indexOf(p.name) === -1;
        }).map(function (p) {
            return { name: p.name, color: p.color, submitted: !!(p.submitted || submittedByName[p.name]) };
        });

        modal.dataset.powerup = powerupType;

        if (titleEl) {
            titleEl.textContent = powerupType === 'steal'
                ? t('powerups.pickStealTitle')
                : t('powerups.pickFreezeTitle');
        }

        listEl.innerHTML = '';

        if (opponents.length === 0) {
            if (hintEl) hintEl.textContent = t('powerups.noOpponents');
        } else {
            if (hintEl) {
                if (powerupType === 'steal') {
                    var hintIcon = pu.feedbackIconHtml ? pu.feedbackIconHtml('bulb', 'sun') : '';
                    if (hintIcon) {
                        hintEl.classList.add('powerup-hint--with-icon');
                        hintEl.innerHTML = hintIcon + '<span class="powerup-hint-text">' + pu.escapeHtml(t('powerups.stealHint')) + '</span>';
                    } else {
                        hintEl.textContent = t('powerups.stealHint');
                    }
                } else {
                    hintEl.classList.remove('powerup-hint--with-icon');
                    hintEl.textContent = t('powerups.pickHint');
                }
            }
            opponents.forEach(function (opp) {
                var li = document.createElement('li');
                var btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'powerup-target-option';
                btn.dataset.player = opp.name;
                var colorDot = '';
                if (opp.color) {
                    colorDot = '<span class="powerup-target-dot" style="background:' +
                        pu.escapeHtml(opp.color) + '"></span>';
                }
                var submittedBadge = '';
                if (powerupType === 'steal' && opp.submitted) {
                    submittedBadge = _answeredBadgeHtml();
                }
                btn.innerHTML = colorDot +
                    '<span class="powerup-target-name">' + pu.escapeHtml(opp.name) + '</span>' +
                    submittedBadge;
                if (powerupType === 'steal') _setStealOptionEnabled(btn, opp.submitted);
                btn.addEventListener('click', function () {
                    if (btn.disabled) return;
                    closeTargetPicker();
                    onConfirm(opp.name);
                });
                li.appendChild(btn);
                listEl.appendChild(li);
            });
        }

        modal.classList.remove('hidden');

        function onCancel() { closeTargetPicker(); }
        function onBackdrop(e) {
            if (e.target && e.target.classList.contains('powerup-target-backdrop')) {
                closeTargetPicker();
            }
        }
        function onKey(e) {
            if (e.key === 'Escape') closeTargetPicker();
        }
        if (cancelBtn) cancelBtn.addEventListener('click', onCancel, { once: true });
        modal.addEventListener('click', onBackdrop);
        document.addEventListener('keydown', onKey);
        modal._teardown = function () {
            modal.removeEventListener('click', onBackdrop);
            document.removeEventListener('keydown', onKey);
            if (cancelBtn) cancelBtn.removeEventListener('click', onCancel);
        };
    }

    function closeTargetPicker() {
        var modal = document.getElementById('powerup-target-modal');
        if (!modal) return;
        modal.classList.add('hidden');
        if (typeof modal._teardown === 'function') {
            modal._teardown();
            modal._teardown = null;
        }
    }

    function applyJoker(removeIndex) {
        var answerButtons = document.getElementById('answer-buttons');
        if (!answerButtons) return;

        var buttons = answerButtons.querySelectorAll('.answer-btn');
        for (var i = 0; i < buttons.length; i++) {
            if (parseInt(buttons[i].dataset.index, 10) === removeIndex) {
                buttons[i].classList.add('is-eliminated');
                buttons[i].disabled = true;
                break;
            }
        }
    }

    var lastAnswerResult = null;

    function handleAnswerResult(data) {
        lastAnswerResult = data;
    }

    function getLastAnswerResult() {
        return lastAnswerResult;
    }

    function clearLastAnswerResult() {
        lastAnswerResult = null;
    }

    window.QuizifyPlayerGame = {
        startCountdown: startCountdown,
        stopCountdown: stopCountdown,
        clearTimeAnnouncement: clearTimeAnnouncement,
        isTimeUp: function () { return _timeUp; },
        startFrozenOverlay: startFrozenOverlay,
        stopFrozenOverlay: stopFrozenOverlay,
        isFrozen: isFrozen,
        updateTimer: updateTimer,
        renderQuestion: renderQuestion,
        renderQuestionImageBanner: renderQuestionImageBanner,
        renderWagerWindow: renderWagerWindow,
        takeWagerStake: takeWagerStake,
        clearRevealBlur: clearRevealBlur,
        preloadNextImage: preloadNextImage,
        handleAnswerClick: handleAnswerClick,
        confirmGuess: confirmGuess,
        releaseGuess: releaseGuess,
        lockSubmitted: lockSubmitted,
        resetSubmissionState: resetSubmissionState,
        renderSubmissionTracker: renderSubmissionTracker,
        resetSubmissionRoster: resetSubmissionRoster,
        updateLeaderboard: updateLeaderboard,
        resetRankMemo: resetRankMemo,
        renderLeaderboardEntry: renderLeaderboardEntry,
        updateLeaderboardSummary: updateLeaderboardSummary,
        renderPowerUp: renderPowerUp,
        powerupNeedsTarget: powerupNeedsTarget,
        openTargetPicker: openTargetPicker,
        closeTargetPicker: closeTargetPicker,
        applyJoker: applyJoker,
        handleAnswerResult: handleAnswerResult,
        getLastAnswerResult: getLastAnswerResult,
        clearLastAnswerResult: clearLastAnswerResult,
        getLastSubmittedIndex: getLastSubmittedIndex
    };

})();


/* ============ player-core.js ============ */

(function () {
    'use strict';

    var pu = window.QuizifyPlayerUtils;
    var lobby = window.QuizifyPlayerLobby;
    var game = window.QuizifyPlayerGame;
    var reveal = window.QuizifyPlayerReveal;
    var end = window.QuizifyPlayerEnd;
    var lightning = window.QuizifyPlayerLightning;
    var hotSeat = window.QuizifyPlayerHotSeat;
    var team = window.QuizifyPlayerTeam;
    var state = pu.state;

    var els = {
        nameInput: document.getElementById('name-input'),
        joinBtn: document.getElementById('join-btn')
    };

    var currentQuestion = null;
    var myPowerUp = null;

    function send(type, payload) {
        var SUBMIT_TYPES = /^(submit_answer|submit_wager|hot_seat_bid|hot_seat_bet|hot_seat_answer|lightning_answer|use_powerup)$/;
        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            state.ws.send(JSON.stringify(Object.assign({ type: type }, payload || {})));
            if (SUBMIT_TYPES.test(type) && pu.submitHaptic) pu.submitHaptic();
            return true;
        }
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        if (pu && pu.showToast) pu.showToast(t('connection.reconnecting'), 2500);
        if (window.console && console.warn) {
            console.warn('[quizify] command not sent, socket not open:', type);
        }
        return false;
    }

    function forgetIdentity() {
        pu.clearSession();
        state.sessionToken = null;
        state.playerName = null;
        state.playerId = null;
        state.isAdmin = false;
    }

    function dropIdentity() {
        state.sessionToken = null;
        state.playerName = null;
        state.playerId = null;
        state.isAdmin = false;
    }

    var _wsOpenTimeout = null;

    function connect() {
        if (state.sessionMoved) return;
        if (state.ws && (state.ws.readyState === WebSocket.OPEN ||
                         state.ws.readyState === WebSocket.CONNECTING)) {
            return;
        }
        state.ws = pu.createWebSocket('/api/quizify/ws', {
            onOpen: function () {
                if (_wsOpenTimeout) { clearTimeout(_wsOpenTimeout); _wsOpenTimeout = null; }

                if (els.joinBtn && !state.playerName) {
                    var tConn = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
                    var nameVal = els.nameInput ? els.nameInput.value.trim() : '';
                    els.joinBtn.disabled = nameVal.length === 0;
                    if (els.joinBtn.textContent === tConn('connection.retryConnection')) {
                        els.joinBtn.textContent = tConn('join.joinButton');
                    }
                }

                var mine = (state.sessionToken && state.playerName)
                    ? { token: state.sessionToken, name: state.playerName, game: null } : null;
                var session = mine || (state.ignoreStoredSession
                    ? { token: null, name: null, game: null } : pu.getSession());
                var params = new URLSearchParams(location.search);
                var isAdminSelfJoin = params.get('admin') === 'true';
                var forceReconnect = params.get('reconnect') === '1';
                var useReconnect = (!isAdminSelfJoin || forceReconnect) && session.token && session.name;
                if (useReconnect) {
                    var reconnectMsg = { session_token: session.token, name: session.name };
                    if (!mine && !forceReconnect && !state.staleConfirmed &&
                            typeof session.game === 'string') {
                        reconnectMsg.last_game_id = session.game;
                    }
                    send('reconnect', reconnectMsg);
                } else if (state.playerName) {
                    var joinMsg = { name: state.playerName };
                    if (isAdminSelfJoin) {
                        state.isAdmin = true;
                    }
                    if (state.isAdmin) {
                        joinMsg.is_admin = true;
                        var _at = QuizifyUtils.readAdminToken();
                        if (_at) joinMsg.admin_token = _at;
                    }
                    beginJoinPending();
                    send('join', joinMsg);
                }
            },
            onMessage: handleMessage,
            onReconnect: connect,
            onClose: function () {
                state.ws = null;
            }
        });
    }

    var _lastTitlePhase = null;
    var _lastTitleMsg = null;

    var _wakeLock = null;

    async function _acquireWakeLock() {
        if (!('wakeLock' in navigator)) return;
        if (_wakeLock) return;
        try {
            _wakeLock = await navigator.wakeLock.request('screen');
            _wakeLock.addEventListener('release', function () {
                _wakeLock = null;
            });
        } catch (e) {
            _wakeLock = null;
        }
    }

    function _releaseWakeLock() {
        if (_wakeLock) {
            try { _wakeLock.release(); } catch (e) { }
            _wakeLock = null;
        }
    }

    function updatePageTitle(phase, msg) {
        _lastTitlePhase = phase;
        _lastTitleMsg = msg;
        if (!window.QuizifyI18n || !window.QuizifyI18n.isReady()) return;
        var t = window.QuizifyI18n.t;
        var title;
        switch (phase) {
            case 'LOBBY':
                title = state.playerName ? t('page.titleLobby') : t('page.titleJoin');
                break;
            case 'WAGER_ACTIVE':
                title = t('page.titleWager');
                break;
            case 'QUESTION_ACTIVE':
            case 'PLAYING':
                title = t('page.titleQuestion', { current: (msg && msg.round) || 1 });
                break;
            case 'ANSWER_REVEAL':
            case 'REVEAL':
                title = t('page.titleReveal');
                break;
            case 'FINALE':
            case 'END':
                title = t('page.titleFinale');
                break;
            default:
                title = t('page.titleJoin');
        }
        if (title && title !== document.title) document.title = title;
    }

    function _flushPendingTitle() {
        if (_lastTitlePhase) updatePageTitle(_lastTitlePhase, _lastTitleMsg);
    }

    function handleMessage(msg) {
        if (state.sessionMoved) return;
        switch (msg.type || msg.event) {
            case 'session_moved':
                handleSessionMoved();
                break;

            case 'reconnect_stale':
                showSessionChoice('stale', (pu.getSession() || {}).name || '');
                break;

            case 'game_state':
                handleGameState(msg);
                break;

            case 'game_reset':
                endJoinPending();
                var resetName = lastPlayerName();
                forgetIdentity();
                if (game && game.resetRankMemo) game.resetRankMemo();
                if (reveal && reveal.resetRankMemo) reveal.resetRankMemo();
                if (game && game.stopFrozenOverlay) game.stopFrozenOverlay();
                clearGameChrome();
                returnToJoin('join.resetHint', resetName);
                break;

            case 'kicked':
                forgetIdentity();
                if (game && game.stopFrozenOverlay) game.stopFrozenOverlay();
                if (pu.hideReconnectingOverlay) pu.hideReconnectingOverlay();
                pu.updateConnectionIndicator('disconnected', { noRetry: true });
                clearGameChrome();
                pu.showView('kicked-view');
                break;

            case 'joined':
            case 'reconnected':
                endJoinPending();
                hideJoinHint();
                state.playerName = msg.player_id || state.playerName;
                state.playerId = msg.player_id;
                if (msg.session_token) {
                    state.sessionToken = msg.session_token;
                    pu.saveSession(msg.session_token, state.playerName);
                }
                if (msg.is_admin) state.isAdmin = true;
                state.ignoreStoredSession = false;
                state.staleConfirmed = false;
                armBackGuard();
                if (typeof msg.welcome_back_score === 'number') {
                    pu.showToast(t('game.welcomeBackScore', {
                        name: state.playerName,
                        score: msg.welcome_back_score
                    }), 4000);
                }
                if (msg.powerup !== undefined) {
                    myPowerUp = msg.powerup;
                    if (game && game.renderPowerUp) game.renderPowerUp(myPowerUp);
                }
                if (msg.all_time !== undefined && lobby && lobby.renderAllTime) {
                    lobby.renderAllTime(msg.all_time);
                }
                if (msg.color) {
                    state.playerColor = msg.color;
                    document.documentElement.style.setProperty('--my-player-color', msg.color);
                }
                break;

            case 'reconnect_failed':
                var failedName = lastPlayerName();
                forgetIdentity();
                var failedHint = msg.reason === 'reset' ? 'join.resetHint'
                    : msg.reason === 'restart' ? 'states.restartPhone'
                    : 'join.reconnectFailedHint';
                returnToJoin(failedHint, failedName);
                break;

            case 'host_presence':
                _rememberHostFlag(msg);
                refreshStageReset();
                break;

            case 'player_joined':
                lobby.handlePlayerJoined(msg);
                _rememberRoster(msg);
                refreshStageReset();
                break;

            case 'player_left':
                lobby.handlePlayerLeft(msg);
                _rememberRoster(msg);
                refreshStageReset();
                break;

            case 'teams_update':
                if (team) team.handleTeamsUpdate(msg);
                break;

            case 'team_joined':
                if (team) team.handleTeamJoined(msg);
                break;

            case 'team_left':
                if (team) team.handleTeamLeft(msg);
                break;

            case 'team_answer':
                if (team) team.handleTeamAnswer(msg);
                break;

            case 'wager_window':
                handleWagerWindow(msg);
                break;

            case 'question_started':
                var questionReceivedAt = Date.now();
                if (isFinalRound(msg)) {
                    playFinaleCountdown(function () {
                        handleQuestionStarted(msg, questionReceivedAt);
                    });
                } else {
                    handleQuestionStarted(msg, questionReceivedAt);
                }
                break;

            case 'timer_tick':
                game.updateTimer(msg.remaining);
                break;

            case 'all_time_update':
                if (msg.all_time !== undefined && lobby && lobby.renderAllTime) {
                    lobby.renderAllTime(msg.all_time, 'end-alltime');
                }
                break;

            case 'answer_progress':
                game.renderSubmissionTracker(msg.players);
                break;

            case 'answer_result':
                game.handleAnswerResult(msg);
                break;

            case 'round_summary':
                handleRoundSummary(msg);
                if (msg.next_image_url && window.QuizifyPlayerGame
                    && QuizifyPlayerGame.preloadNextImage) {
                    QuizifyPlayerGame.preloadNextImage(msg.next_image_url);
                }
                break;

            case 'finale':
                handleFinale(msg);
                break;

            case 'powerup_assigned':
                myPowerUp = msg.powerup_type;
                game.renderPowerUp(myPowerUp);
                break;

            case 'powerup_applied':
                handlePowerUpApplied(msg);
                break;

            case 'scoring_status':
                reveal.updateScoringStatus(msg);
                break;

            case 'reactions':
                (msg.reactions || []).forEach(function (r) {
                    showFloatingReaction(r.emoji, r.player_name);
                });
                break;

            case 'reaction':
                showFloatingReaction(msg.emoji, msg.player_name);
                break;

            case 'reaction_bonus':
                handleReactionBonus(msg);
                break;

            case 'wager_accepted':
                break;

            case 'hot_seat_auction_you':
                if (hotSeat) hotSeat.handleAuctionYou(msg);
                break;

            case 'hot_seat_bid_count':
                if (hotSeat) hotSeat.handleBidCount(msg);
                break;

            case 'hot_seat_bid_accepted':
            case 'hot_seat_bet_accepted':
            case 'hot_seat_answer_accepted':
                break;

            case 'hot_seat_awarded':
                if (hotSeat) hotSeat.handleAwarded(msg);
                break;

            case 'hot_seat_no_bids':
                if (hotSeat) hotSeat.handleNoBids();
                break;

            case 'hot_seat_question':
                if (game && game.clearTimeAnnouncement) game.clearTimeAnnouncement();
                if (hotSeat) hotSeat.handleQuestion(msg);
                break;

            case 'hot_seat_tick':
                if (hotSeat) hotSeat.handleTick(msg);
                break;

            case 'hot_seat_result':
                if (hotSeat) hotSeat.handleResult(msg);
                break;

            case 'lightning_splash':
                if (lightning) lightning.handleLightningSplash(msg);
                break;

            case 'lightning_question':
                if (lightning) lightning.handleLightningQuestion(msg);
                break;
            case 'lightning_tick':
                if (lightning) lightning.handleLightningTick(msg);
                break;
            case 'lightning_answer_result':
                if (lightning) lightning.handleLightningAnswerResult(msg);
                break;
            case 'lightning_team_answer':
                if (lightning) lightning.handleLightningTeamAnswer(msg);
                break;
            case 'lightning_recap':
                if (lightning) lightning.handleLightningRecap(msg);
                break;

            case 'guess_accepted':
                if (game && game.confirmGuess) game.confirmGuess();
                break;

            case 'error':
                handleError(msg);
                break;
        }

        enterStageFor(msg);
        clearStalePanels(msg);
    }

    function handleReactionBonus(msg) {
        var to = msg.to_players || [];
        var from = msg.from_player || '';
        if (state.playerName && to.indexOf(state.playerName) !== -1 && from) {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var toast = document.createElement('div');
            toast.className = 'reaction-bonus-toast';
            var rbIcon = pu.feedbackIconHtml ? pu.feedbackIconHtml('party', 'coral') : '';
            if (rbIcon) {
                toast.classList.add('toast--with-icon');
                toast.innerHTML = rbIcon + '<span class="toast-text">' + pu.escapeHtml(t('wager.bonusFromReaction', { from: from })) + '</span>';
            } else {
                toast.textContent = t('wager.bonusFromReaction', { from: from });
            }
            document.body.appendChild(toast);
            setTimeout(function () { toast.remove(); }, 1600);
        }
        if (msg.leaderboard && game && game.updateLeaderboard) {
            game.updateLeaderboard({ leaderboard: msg.leaderboard }, 'reveal-leaderboard-list');
        }
    }

    function handleGameState(msg) {
        pu.setPhase(msg.phase);

        if (state.playerId && msg.game_id !== undefined && pu.saveSessionGame) {
            pu.saveSessionGame(msg.game_id);
        }

        if (team && msg.teams) team.handleTeamsUpdate(msg);

        if (msg.leaderboard && game && game.updateLeaderboard) {
            game.updateLeaderboard({ leaderboard: msg.leaderboard }, 'leaderboard-list');
        }

        if (msg.phase === 'QUESTION_ACTIVE' || msg.phase === 'PLAYING') {
            _acquireWakeLock();
        } else {
            _releaseWakeLock();
            _clearFinaleCountdown();
        }

        if (!_syncServerLanguage(msg)) {
            updatePageTitle(msg.phase, msg);
        }

        if (msg.players) lobby.handlePlayerJoined(msg);

        if (msg.phase !== 'PAUSED') disarmResetAffordance('paused-reset-btn');
        _rememberHostFlag(msg);
        _rememberRoster(msg);
        setResetStage(STAGE_RESET_AFFORDANCES[msg.phase] ? msg.phase : null);
        clearStalePanelsForPhase(msg.phase);

        switch (msg.phase) {
            case 'LOBBY':
                if (game && game.resetSubmissionRoster) game.resetSubmissionRoster();
                if (!state.playerName) {
                    pu.showView('join-view');
                } else {
                    pu.showView('lobby-view');
                    lobby.renderLobby(msg);
                }
                break;

            case 'WAGER_ACTIVE':
                if (msg.wager) {
                    handleWagerWindow(wagerWindowFromSnapshot(msg));
                } else {
                    pu.showView('game-view');
                }
                break;

            case 'QUESTION_ACTIVE':
            case 'PLAYING':
                if (msg.question) {
                    var priorRound = currentQuestion && currentQuestion.round_num;
                    var priorIndex = game.getLastSubmittedIndex();

                    handleQuestionStarted(questionStartedFromSnapshot(msg));

                    if (team && msg.team_answer) {
                        team.handleTeamAnswer(msg.team_answer);
                    }

                    game.renderSubmissionTracker(msg.players || []);

                    if (msg.leaderboard && state.playerName) {
                        var me = msg.leaderboard.find(function (p) {
                            return p && p.name === state.playerName;
                        });
                        if (me && me.submitted) {
                            var sameRound = (priorRound !== null &&
                                priorRound !== undefined &&
                                priorRound === msg.round);
                            game.lockSubmitted(sameRound ? priorIndex : -1);
                        }
                    }
                } else {
                    pu.showView('game-view');
                }
                break;

            case 'ANSWER_REVEAL':
            case 'REVEAL':
                game.stopCountdown();
                pu.showView('reveal-view');
                reveal.updateRevealView(msg);
                disarmResetAffordance('paused-reset-btn');
                break;

            case 'FINALE':
            case 'END':
                handleFinale(msg);
                break;

            case 'LIGHTNING':
                if (lightning && msg.lightning && msg.lightning.splash_pending) {
                    lightning.handleLightningSplash({
                        num_questions: msg.lightning.num_questions,
                        seconds_per_question: msg.lightning.seconds_per_question
                    });
                } else if (lightning && msg.lightning) {
                    var lq = msg.lightning.question;
                    lightning.handleLightningQuestion({
                        question_text: lq ? lq.text : '',
                        answers: lq ? lq.answers : [],
                        index: msg.lightning.index,
                        num_questions: msg.lightning.num_questions,
                        seconds: msg.lightning.time_remaining,
                        category: lq ? lq.category : '',
                        image_url: lq ? lq.image_url : '',
                        you_answered: !!msg.lightning.you_answered,
                        you_answer_index: msg.lightning.you_answer_index
                    });
                } else {
                    pu.showView('lightning-view');
                }
                break;

            case 'LIGHTNING_RECAP':
                if (lightning) lightning.handleLightningRecap({ recap: msg.lightning_recap });
                break;

            case 'HOT_SEAT_AUCTION':
            case 'HOT_SEAT':
            case 'HOT_SEAT_REVEAL':
                pu.showView('game-view');
                if (hotSeat && msg.hot_seat) hotSeat.restoreFromSnapshot(msg.hot_seat, msg);
                var adminBarHS = document.getElementById('admin-control-bar');
                if (adminBarHS) adminBarHS.classList.toggle('hidden', !state.isAdmin);
                var nextRoundHS = document.getElementById('next-round-admin-btn');
                var skipHS = document.getElementById('skip-question-btn');
                var pauseHS = document.getElementById('pause-game-btn');
                var resumeHS = document.getElementById('resume-game-btn');
                var inReveal = msg.phase === 'HOT_SEAT_REVEAL';
                if (nextRoundHS) nextRoundHS.classList.toggle('hidden', !inReveal);
                if (skipHS) skipHS.classList.toggle('hidden', inReveal);
                if (pauseHS) pauseHS.classList.add('hidden');
                if (resumeHS) resumeHS.classList.add('hidden');
                break;

            case 'PAUSED':
                game.stopCountdown();
                pu.showView('paused-view');
                updatePausedView(msg);
                var adminBarP = document.getElementById('admin-control-bar');
                if (adminBarP) adminBarP.classList.toggle('hidden', !state.isAdmin);
                var pauseBtnP = document.getElementById('pause-game-btn');
                var resumeBtnP = document.getElementById('resume-game-btn');
                if (pauseBtnP) pauseBtnP.classList.add('hidden');
                if (resumeBtnP) resumeBtnP.classList.remove('hidden');
                break;

            default:
                pu.showView(state.playerName ? 'lobby-view' : 'join-view');
                break;
        }
    }

    var _finaleCountdownTimers = [];

    function isFinalRound(msg) {
        if (!msg) return false;
        if (msg.is_final_round === true) return true;
        var rn = msg.round_num;
        var tr = msg.total_rounds;
        return typeof rn === 'number' && typeof tr === 'number' && tr > 0 && rn >= tr;
    }

    function _clearFinaleCountdown() {
        for (var i = 0; i < _finaleCountdownTimers.length; i++) {
            clearTimeout(_finaleCountdownTimers[i]);
        }
        _finaleCountdownTimers = [];
        var overlay = document.getElementById('finale-countdown-overlay');
        if (overlay) {
            overlay.classList.add('hidden');
            overlay.setAttribute('aria-hidden', 'true');
        }
    }

    function playFinaleCountdown(done) {
        var fired = false;
        function finish() {
            if (fired) return;
            fired = true;
            _clearFinaleCountdown();
            try { done(); } catch (e) { }
        }

        var overlay = document.getElementById('finale-countdown-overlay');
        var numberEl = document.getElementById('finale-countdown-number');
        if (!overlay || !numberEl) {
            finish();
            return;
        }

        try {
            _clearFinaleCountdown();
            numberEl.textContent = '';
            overlay.classList.remove('hidden');
            overlay.setAttribute('aria-hidden', 'false');

            var digits = [3, 2, 1];
            digits.forEach(function (d, idx) {
                _finaleCountdownTimers.push(setTimeout(function () {
                    numberEl.textContent = String(d);
                    numberEl.classList.remove('tick');
                    void numberEl.offsetWidth;
                    numberEl.classList.add('tick');
                }, 700 + idx * 600));
            });

            _finaleCountdownTimers.push(setTimeout(finish, 700 + digits.length * 600));
        } catch (e) {
            finish();
        }
    }

    function _myScore(msg) {
        var boards = [msg.leaderboard || [], msg.players || []];
        for (var b = 0; b < boards.length; b++) {
            for (var i = 0; i < boards[b].length; i++) {
                if (boards[b][i] && boards[b][i].name === state.playerName) {
                    return boards[b][i].score || 0;
                }
            }
        }
        return 0;
    }

    function questionStartedFromSnapshot(msg) {
        var q = msg.question || {};
        var live = {};
        for (var k in q) {
            if (Object.prototype.hasOwnProperty.call(q, k)) live[k] = q[k];
        }
        live.question_text = q.text;
        live.timer_duration = q.time_remaining || q.time_limit;
        live.reveal_duration = q.time_limit || q.time_remaining;
        live.round_num = msg.round;
        live.total_rounds = msg.total_rounds;
        live.player_score = _myScore(msg);
        return live;
    }

    function wagerWindowFromSnapshot(msg) {
        var w = msg.wager || {};
        return {
            round_num: msg.round,
            total_rounds: msg.total_rounds,
            category: w.category,
            difficulty: w.difficulty,
            window_duration: w.window_remaining,
            player_score: (w.own_bank != null) ? w.own_bank : _myScore(msg),
            you_wagered: (w.you_wagered != null) ? w.you_wagered : null
        };
    }

    function handleWagerWindow(msg) {
        pu.setPhase('WAGER_ACTIVE');
        pu.showView('game-view');
        game.resetSubmissionState();
        game.stopFrozenOverlay();
        if (team) team.resetRound();

        var currentRound = document.getElementById('current-round');
        var totalRounds = document.getElementById('total-rounds');
        if (currentRound) currentRound.textContent = msg.round_num || 1;
        if (totalRounds) totalRounds.textContent = msg.total_rounds || 10;

        var banner = document.getElementById('last-round-banner');
        if (banner) banner.classList.remove('hidden');

        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) adminBar.classList.toggle('hidden', !state.isAdmin);
        var nextRoundAdminBtn = document.getElementById('next-round-admin-btn');
        var skipBtn = document.getElementById('skip-question-btn');
        var pauseBtn = document.getElementById('pause-game-btn');
        var resumeBtn = document.getElementById('resume-game-btn');
        if (nextRoundAdminBtn) nextRoundAdminBtn.classList.add('hidden');
        if (skipBtn) skipBtn.classList.toggle('hidden', !state.isAdmin);
        var skipLabel = document.getElementById('skip-question-label');
        if (skipLabel && window.QuizifyI18n) {
            skipLabel.setAttribute('data-i18n', 'admin.closeBets');
            skipLabel.textContent = window.QuizifyI18n.t('admin.closeBets');
        }
        if (pauseBtn) pauseBtn.classList.add('hidden');
        if (resumeBtn) resumeBtn.classList.add('hidden');

        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.add('hidden');

        game.renderWagerWindow(msg);
    }

    function handleQuestionStarted(msg, receivedAt) {
        pu.setPhase('QUESTION_ACTIVE');
        currentQuestion = msg;

        pu.showView('game-view');

        game.renderQuestion(msg);
        game.resetSubmissionState();
        if (team) team.resetRound();

        game.stopFrozenOverlay();

        var currentRound = document.getElementById('current-round');
        var totalRounds = document.getElementById('total-rounds');
        if (currentRound) currentRound.textContent = msg.round_num || 1;
        if (totalRounds) totalRounds.textContent = msg.total_rounds || 10;

        var lastRoundBanner = document.getElementById('last-round-banner');
        if (lastRoundBanner) {
            lastRoundBanner.classList.toggle('hidden', !isFinalRound(msg));
        }

        if (msg.timer_duration) {
            var startedAt = (typeof receivedAt === 'number') ? receivedAt : Date.now();
            var deadline = startedAt + (msg.timer_duration * 1000);
            game.startCountdown(deadline);
        }

        game.renderPowerUp(myPowerUp);

        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) {
            adminBar.classList.toggle('hidden', !state.isAdmin);
        }
        var nextRoundAdminBtn = document.getElementById('next-round-admin-btn');
        var skipBtn = document.getElementById('skip-question-btn');
        var pauseBtn = document.getElementById('pause-game-btn');
        var resumeBtn = document.getElementById('resume-game-btn');
        if (nextRoundAdminBtn) nextRoundAdminBtn.classList.add('hidden');
        if (skipBtn) skipBtn.classList.toggle('hidden', !state.isAdmin);
        var skipLabel = document.getElementById('skip-question-label');
        if (skipLabel && window.QuizifyI18n) {
            skipLabel.setAttribute('data-i18n', 'admin.reveal');
            skipLabel.textContent = window.QuizifyI18n.t('admin.reveal');
        }
        if (pauseBtn) pauseBtn.classList.remove('hidden');
        if (resumeBtn) resumeBtn.classList.add('hidden');

        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.add('hidden');
    }

    function handleRoundSummary(msg) {
        pu.setPhase('ANSWER_REVEAL');
        game.stopCountdown();
        game.stopFrozenOverlay();
        _clearFinaleCountdown();
        if (game.clearRevealBlur) game.clearRevealBlur();
        pu.showView('reveal-view');
        if (game.closeTargetPicker) game.closeTargetPicker();

        if (currentQuestion) {
            msg.question_text = currentQuestion.question_text;
            msg.question = { text: currentQuestion.question_text };
        }

        var lastResult = game.getLastAnswerResult ? game.getLastAnswerResult() : null;
        if (lastResult && msg.all_answers) {
            msg.all_answers = msg.all_answers.map(function(a) {
                if (a.player_name === state.playerName) {
                    return Object.assign({}, a, {
                        speed_bonus: lastResult.speed_bonus || 0,
                        streak_bonus: lastResult.streak_bonus || 0,
                        difficulty_multiplier: lastResult.difficulty_multiplier || 1.0,
                        difficulty_bonus: lastResult.difficulty_bonus || 0,
                        double_bonus: lastResult.double_bonus || 0,
                        round_score: (typeof a.points_earned === 'number')
                            ? a.points_earned
                            : (lastResult.points_earned || 0),
                        streak: lastResult.new_streak || 0,
                        streak_active: lastResult.streak_active === true,
                    });
                }
                return a;
            });
        }

        reveal.updateRevealView(msg);

        game.clearLastAnswerResult();
        myPowerUp = null;

        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.remove('hidden');

        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) adminBar.classList.add('hidden');
        var nextRoundAdminBtn2 = document.getElementById('next-round-admin-btn');
        var skipBtn2 = document.getElementById('skip-question-btn');
        if (nextRoundAdminBtn2) nextRoundAdminBtn2.classList.add('hidden');
        if (skipBtn2) skipBtn2.classList.add('hidden');
    }

    function clearGameChrome() {
        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.add('hidden');
        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) adminBar.classList.add('hidden');
        if (pu.clearToast) pu.clearToast();
        if (game && game.clearTimeAnnouncement) game.clearTimeAnnouncement();
        setResetStage(null);
        _lastRoster = [];
        if (game && game.resetSubmissionRoster) game.resetSubmissionRoster();
        _hostSeenInRoster = false;
        _hostConnectedFlag = null;
    }

    function handleFinale(msg) {
        pu.setPhase('FINALE');
        updatePageTitle('FINALE', msg);
        game.stopCountdown();
        _clearFinaleCountdown();
        if (game.closeTargetPicker) game.closeTargetPicker();
        setResetStage(null);
        pu.showView('end-view');

        end.updateEndView(msg);
        end.setupNewGameButton();

        var reactionBar = document.getElementById('reaction-bar');
        if (reactionBar) reactionBar.classList.add('hidden');
        var adminBar = document.getElementById('admin-control-bar');
        if (adminBar) adminBar.classList.add('hidden');
    }

    function updatePausedView(data) {
        var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
        var titleEl = document.getElementById('pause-title');
        var messageEl = document.getElementById('pause-message');
        var isDisconnect = data.pause_reason === 'admin_disconnected';
        var titleKey = isDisconnect ? 'admin.pausedHostDisconnected' : 'admin.pausedTitle';
        var hintKey = isDisconnect ? 'admin.pausedHostHint' : 'admin.pausedHint';
        if (titleEl) titleEl.textContent = t(titleKey);
        if (messageEl) messageEl.textContent = t(hintKey);

        if (isDisconnect && !state.isAdmin) {
            armResetAffordance('paused-reset-btn');
        } else {
            disarmResetAffordance('paused-reset-btn');
        }
    }

    var RESET_AFFORDANCE_DELAY_MS = 60000;
    var _resetAffordanceTimers = {};

    function armResetAffordance(btnId, wrapperId) {
        if (_resetAffordanceTimers[btnId]) return;
        var btn = document.getElementById(btnId);
        if (btn && !btn.classList.contains('hidden')) return;
        _resetAffordanceTimers[btnId] = setTimeout(function () {
            _resetAffordanceTimers[btnId] = null;
            var b = document.getElementById(btnId);
            if (b) {
                b.disabled = false;
                b.classList.remove('hidden');
            }
            if (wrapperId) {
                var w = document.getElementById(wrapperId);
                if (w) w.classList.remove('hidden');
            }
        }, RESET_AFFORDANCE_DELAY_MS);
    }

    function disarmResetAffordance(btnId, wrapperId) {
        if (_resetAffordanceTimers[btnId]) {
            clearTimeout(_resetAffordanceTimers[btnId]);
            _resetAffordanceTimers[btnId] = null;
        }
        var btn = document.getElementById(btnId);
        if (btn) btn.classList.add('hidden');
        if (wrapperId) {
            var w = document.getElementById(wrapperId);
            if (w) w.classList.add('hidden');
        }
        if (_guestResetTrigger && _guestResetTrigger.id === btnId) {
            closeGuestResetModal();
        }
    }

    var STAGE_RESET_AFFORDANCES = {
        'ANSWER_REVEAL': ['reveal-reset-btn', 'reveal-reset-controls'],
        'REVEAL': ['reveal-reset-btn', 'reveal-reset-controls'],
        'LIGHTNING_RECAP': ['lightning-recap-reset-btn', 'lightning-recap-reset-controls'],
        'HOT_SEAT_REVEAL': ['hotseat-reset-btn', 'hotseat-reset-controls']
    };

    var STAGE_ENTERED_BY = {
        'round_summary': 'ANSWER_REVEAL',
        'lightning_recap': 'LIGHTNING_RECAP',
        'hot_seat_result': 'HOT_SEAT_REVEAL'
    };

    function enterStageFor(msg) {
        var stage = msg && STAGE_ENTERED_BY[msg.type || msg.event];
        if (stage) setResetStage(stage);
    }

    var GAME_VIEW_PANELS = {
        'last-round-banner': {
            raisedBy: ['wager_window'],
            phases: ['WAGER_ACTIVE'],
            clear: null,
            owner: 'handleQuestionStarted, which lowers it on any round that is not the last (#706)'
        },
        'wager-panel': {
            raisedBy: ['wager_window'],
            phases: ['WAGER_ACTIVE'],
            clear: null,
            owner: 'game.renderQuestion via _showWagerBadge, which hides it or collapses it to a badge (#656)'
        },
        'hotseat-panel': {
            raisedBy: [
                'hot_seat_auction_you',
                'hot_seat_question',
                'hot_seat_result'
            ],
            phases: ['HOT_SEAT_AUCTION', 'HOT_SEAT', 'HOT_SEAT_REVEAL'],
            clear: function () { if (hotSeat) hotSeat.reset(); },
            owner: null
        },
        'hotseat-reset-controls': {
            raisedBy: ['hot_seat_result'],
            phases: ['HOT_SEAT_REVEAL'],
            clear: null,
            owner: 'setResetStage, which disarms every stage but the one being entered (#803/#858)'
        },
        'estimate-container': {
            raisedBy: ['question_started'],
            phases: ['QUESTION_ACTIVE', 'PLAYING'],
            clear: null,
            owner: 'game.renderQuestion, which swaps the two input sections per round type (#275)'
        }
    };

    var MOVED_PAST_DETOUR = [
        'question_started',
        'wager_window',
        'lightning_splash'
    ];

    function _clearPanels(keep) {
        Object.keys(GAME_VIEW_PANELS).forEach(function (id) {
            var row = GAME_VIEW_PANELS[id];
            if (!row.clear || keep(row)) return;
            row.clear();
        });
    }

    function clearStalePanels(msg) {
        var type = msg && (msg.type || msg.event);
        if (MOVED_PAST_DETOUR.indexOf(type) === -1) return;
        _clearPanels(function (row) {
            return row.raisedBy.indexOf(type) !== -1;
        });
    }

    function clearStalePanelsForPhase(phase) {
        _clearPanels(function (row) {
            return (row.phases || []).indexOf(phase) !== -1;
        });
    }

    var _lastRoster = [];

    var _hostConnectedFlag = null;

    var _hostSeenInRoster = false;

    var _resetStage = null;

    function _rememberHostFlag(msg) {
        if (msg && typeof msg.host_connected === 'boolean') {
            _hostConnectedFlag = msg.host_connected;
        }
    }

    function _rememberRoster(msg) {
        if (!msg || !Array.isArray(msg.players)) return;
        _lastRoster = msg.players;
        if (_lastRoster.some(function (p) { return p && p.is_admin; })) {
            _hostSeenInRoster = true;
        }
    }

    function _hostPresence() {
        if (_hostConnectedFlag !== null) {
            return _hostConnectedFlag ? 'connected' : 'gone';
        }
        var named = false;
        for (var i = 0; i < _lastRoster.length; i++) {
            var p = _lastRoster[i];
            if (!p || !p.is_admin) continue;
            named = true;
            if (p.connected !== false) return 'connected';
        }
        return (named || _hostSeenInRoster) ? 'gone' : 'unknown';
    }

    function setResetStage(stage) {
        _resetStage = stage || null;
        var mine = _resetStage ? STAGE_RESET_AFFORDANCES[_resetStage][0] : null;
        Object.keys(STAGE_RESET_AFFORDANCES).forEach(function (key) {
            var ids = STAGE_RESET_AFFORDANCES[key];
            if (ids[0] === mine) return;
            disarmResetAffordance(ids[0], ids[1]);
        });
        refreshStageReset();
    }

    function refreshStageReset() {
        var ids = _resetStage && STAGE_RESET_AFFORDANCES[_resetStage];
        if (!ids) return;
        if (state.isAdmin || _hostPresence() !== 'gone') {
            disarmResetAffordance(ids[0], ids[1]);
        } else {
            armResetAffordance(ids[0], ids[1]);
        }
    }

    var CONFIRM_KINDS = {
        reset: { title: 'admin.resetGameConfirm', text: 'game.resetGuestWarning',
            confirm: 'admin.resetGame', cancel: 'common.cancel' },
        end: { title: 'admin.endGameConfirm', text: 'admin.endGameWarning',
            confirm: 'admin.endGame', cancel: 'common.cancel' },
        newGame: { title: 'admin.resetGameConfirm', text: 'admin.resetGameWarning',
            confirm: 'admin.resetGame', cancel: 'common.cancel' },
        leave: { title: 'game.leaveConfirm', text: 'game.leaveWarning',
            confirm: 'game.leave', cancel: 'game.keepPlaying',
            confirmClass: 'btn-secondary', cancelClass: 'btn-primary', sheet: 'modal--leave' }
    };
    var _guestResetTrigger = null;
    var _guestResetKeyHandler = null;
    var _confirmPending = null;

    function _focus(el) {
        if (el && typeof el.focus === 'function') el.focus();
    }

    function _paintConfirmKind(kind) {
        var keys = CONFIRM_KINDS[kind] || CONFIRM_KINDS.reset;
        var t = window.QuizifyI18n && window.QuizifyI18n.t;
        [
            ['guest-reset-modal-title', keys.title],
            ['guest-reset-modal-text', keys.text],
            ['guest-reset-confirm-btn', keys.confirm],
            ['guest-reset-cancel-btn', keys.cancel]
        ].forEach(function (pair) {
            var el = document.getElementById(pair[0]);
            if (!el) return;
            el.setAttribute('data-i18n', pair[1]);
            if (t) el.textContent = t(pair[1]);
        });
        var yes = document.getElementById('guest-reset-confirm-btn');
        var no = document.getElementById('guest-reset-cancel-btn');
        if (yes) yes.className = 'btn ' + (keys.confirmClass || 'btn-danger');
        if (no) no.className = 'btn ' + (keys.cancelClass || 'btn-secondary');
        var modal = document.getElementById('guest-reset-modal');
        if (modal && modal.classList) modal.classList.toggle('modal--leave', keys.sheet === 'modal--leave');
    }

    function confirmThen(triggerBtn, kind, run, onCancel) {
        var modal = document.getElementById('guest-reset-modal');
        if (!modal) return false;
        _confirmPending = { kind: kind, run: run || null, onCancel: onCancel || null };
        _paintConfirmKind(kind);
        return _openConfirmSheet(modal, triggerBtn);
    }

    function openGuestResetModal(triggerBtn) {
        var modal = document.getElementById('guest-reset-modal');
        if (!modal) return false;
        _confirmPending = { kind: 'reset', run: null };
        _paintConfirmKind('reset');
        return _openConfirmSheet(modal, triggerBtn);
    }

    function _openConfirmSheet(modal, triggerBtn) {
        _guestResetTrigger = triggerBtn || null;
        modal.classList.remove('hidden');
        var cancelBtn = document.getElementById('guest-reset-cancel-btn');
        setTimeout(function () { _focus(cancelBtn); }, 0);

        if (_guestResetKeyHandler) {
            document.removeEventListener('keydown', _guestResetKeyHandler, true);
        }
        _guestResetKeyHandler = function (e) {
            if (e.key === 'Escape') {
                e.preventDefault();
                closeGuestResetModal();
                return;
            }
            if (e.key !== 'Tab') return;
            var first = document.getElementById('guest-reset-confirm-btn');
            var last = cancelBtn;
            if (!first || !last) return;
            var active = document.activeElement;
            if (e.shiftKey) {
                if (active === first || !modal.contains(active)) {
                    e.preventDefault();
                    _focus(last);
                }
            } else if (active === last || !modal.contains(active)) {
                e.preventDefault();
                _focus(first);
            }
        };
        document.addEventListener('keydown', _guestResetKeyHandler, true);
        return true;
    }

    function isConfirmSheetOpen() {
        var modal = document.getElementById('guest-reset-modal');
        return !!(modal && !modal.classList.contains('hidden'));
    }

    function closeGuestResetModal() {
        var modal = document.getElementById('guest-reset-modal');
        if (modal) modal.classList.add('hidden');
        var pending = _confirmPending;
        _confirmPending = null;
        if (pending && pending.onCancel) pending.onCancel();
        if (_guestResetKeyHandler) {
            document.removeEventListener('keydown', _guestResetKeyHandler, true);
            _guestResetKeyHandler = null;
        }
        var trigger = _guestResetTrigger;
        _guestResetTrigger = null;
        _focus(trigger);
    }

    function setupResetAffordance() {
        [
            'paused-reset-btn',
            'reveal-reset-btn',
            'lightning-recap-reset-btn',
            'hotseat-reset-btn'
        ].forEach(function (id) {
            var btn = document.getElementById(id);
            if (btn) {
                btn.addEventListener('click', function () {
                    openGuestResetModal(btn);
                });
            }
        });
        var confirmBtn = document.getElementById('guest-reset-confirm-btn');
        if (confirmBtn) {
            confirmBtn.addEventListener('click', function () {
                var trigger = _guestResetTrigger;
                var pending = _confirmPending;
                if (pending && pending.run) {
                    _confirmPending = null;
                    closeGuestResetModal();
                    pending.run();
                    return;
                }
                if (!trigger || trigger.classList.contains('hidden')) {
                    closeGuestResetModal();
                    return;
                }
                trigger.disabled = true;
                send('reset_game', {});
                closeGuestResetModal();
            });
        }
        var cancelBtn = document.getElementById('guest-reset-cancel-btn');
        if (cancelBtn) cancelBtn.addEventListener('click', closeGuestResetModal);
        var modal = document.getElementById('guest-reset-modal');
        var backdrop = modal && modal.querySelector('.modal-backdrop');
        if (backdrop) backdrop.addEventListener('click', closeGuestResetModal);
    }

    function handlePowerUpApplied(msg) {
        if (msg.powerup_type === 'joker' && msg.joker_remove_index != null) {
            game.applyJoker(msg.joker_remove_index);
        } else if (msg.powerup_type === 'joker' && msg.source_player !== state.playerName) {
            var tJk = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            pu.showToast(tJk('game.opponentUsedJoker', { name: msg.source_player }), 2000, 'game.opponentUsedJoker');
        } else if (msg.powerup_type === 'steal') {
            var tPwr = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var pts = msg.stolen_points || 0;
            if (msg.source_player === state.playerName) {
                pu.showToast(tPwr('game.stoleFromOpponent', { points: pts, name: msg.target_player || tPwr('lobby.you') }), 2500, 'game.stoleFromOpponent');
            } else if (msg.target_player === state.playerName) {
                pu.showToast(tPwr('game.stoleFromYou', { name: msg.source_player || tPwr('lobby.you'), points: pts }), 2500, 'game.stoleFromYou');
            }
        } else if (msg.powerup_type === 'freeze' && msg.target_player === state.playerName) {
            var freezeSecs = Number(msg.freeze_duration) || 5;
            game.startFrozenOverlay(freezeSecs);
        }
        if (msg.source_player === state.playerName) {
            myPowerUp = null;
            var powerupBtn = document.getElementById('powerup-btn');
            if (powerupBtn) {
                powerupBtn.classList.add('used');
            }
        }
    }

    function showFloatingReaction(emoji, playerName) {
        var container = document.getElementById('reaction-container');
        if (!container) return;

        var el = document.createElement('div');
        el.className = 'floating-reaction';
        el.textContent = emoji;
        el.style.left = (20 + Math.random() * 60) + '%';
        container.appendChild(el);

        setTimeout(function () {
            if (el.parentNode) el.parentNode.removeChild(el);
        }, 2000);
    }

    function handleError(msg) {
        console.warn('[Quizify] Error:', msg.code, msg.message);
        var t = _t();
        var code = msg.code || 'UNKNOWN';

        if (state.joinPending || (!state.playerName && els.joinBtn)) {
            pu.showToast(showJoinRefusal(code, msg.message));
            return;
        }

        var key = 'errors.' + code;
        var translated = t(key);
        var userMsg;
        if (translated && translated !== key) {
            userMsg = translated;
        } else if (msg.message) {
            userMsg = msg.message;
        } else {
            userMsg = t('errors.UNKNOWN');
        }
        pu.showToast(userMsg);

        if (game && game.releaseGuess) game.releaseGuess(msg.code);

        if (msg.code === 'TEAM_CLOSED' && team) team.handleTeamError();
    }

    var JOIN_ANSWER_TIMEOUT_MS = 10000;
    var _joinTimeout = null;

    var JOIN_REFUSALS_CLEARING_NAME = [
        'NAME_TAKEN', 'NAME_INVALID', 'GAME_FULL', 'GAME_ENDED', 'ALREADY_JOINED'
    ];

    function _t() {
        return (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
    }

    function joinRefusalText(code, serverMessage) {
        var t = _t();
        var candidates = ['join.refused.' + code, 'errors.' + code];
        for (var i = 0; i < candidates.length; i++) {
            var value = t(candidates[i]);
            if (value && value !== candidates[i]) return value;
        }
        if (serverMessage) return serverMessage;
        return t('join.refused.UNKNOWN');
    }

    function beginJoinPending() {
        state.joinPending = true;
        if (_joinTimeout) clearTimeout(_joinTimeout);
        _joinTimeout = setTimeout(function () {
            _joinTimeout = null;
            if (state.joinPending) showJoinRefusal('NO_CONNECTION', null);
        }, JOIN_ANSWER_TIMEOUT_MS);
    }

    function endJoinPending() {
        state.joinPending = false;
        if (_joinTimeout) { clearTimeout(_joinTimeout); _joinTimeout = null; }
    }

    function lastPlayerName() {
        var stored = pu.getSession ? pu.getSession() : null;
        return state.playerName || (stored && stored.name) || '';
    }

    function returnToJoin(reasonKey, lastName) {
        var t = _t();
        var hint = document.getElementById('join-hint');
        if (hint) {
            hint.setAttribute('data-i18n', reasonKey);
            hint.textContent = t(reasonKey);
            hint.classList.remove('hidden');
        }
        if (lastName && els.nameInput) els.nameInput.value = lastName;
        if (els.joinBtn) {
            els.joinBtn.textContent = t('join.joinButton');
            els.joinBtn.disabled = !(els.nameInput &&
                pu.validateName(els.nameInput.value).valid);
        }
        pu.showView('join-view');
    }

    function hideJoinHint() {
        var hint = document.getElementById('join-hint');
        if (hint) hint.classList.add('hidden');
    }

    function handleSessionMoved() {
        endJoinPending();
        state.movedName = state.playerName;
        dropIdentity();
        state.sessionMoved = true;
        if (state.reconnectTimer) { clearTimeout(state.reconnectTimer); state.reconnectTimer = null; }
        _releaseWakeLock();
        if (game && game.stopFrozenOverlay) game.stopFrozenOverlay();
        if (pu.hideReconnectingOverlay) pu.hideReconnectingOverlay();
        clearGameChrome();
        pu.updateConnectionIndicator('disconnected', { noRetry: true });
        if (state.ws) {
            state.intentionalLeave = true;
            try { state.ws.close(); } catch (e) { }
        }
        showSessionChoice('moved', '');
    }

    var SESSION_CHOICES = {
        moved: { title: 'session.movedTitle', primary: 'session.playHere' },
        stale: { title: 'session.continueAs', primary: 'session.continue' }
    };
    var _sessionChoice = null;

    function showSessionChoice(kind, name) {
        var keys = SESSION_CHOICES[kind];
        var t = _t();
        var params = kind === 'stale' ? { name: name } : null;
        _sessionChoice = kind;
        var title = document.getElementById('session-title');
        if (title) {
            title.setAttribute('data-i18n', keys.title);
            if (params) title.setAttribute('data-i18n-params', JSON.stringify(params));
            else title.removeAttribute('data-i18n-params');
            title.textContent = t(keys.title, params || undefined);
        }
        var primary = document.getElementById('session-primary-btn');
        if (primary) {
            primary.setAttribute('data-i18n', keys.primary);
            primary.textContent = t(keys.primary);
        }
        pu.showView('session-view');
    }

    function _sessionPrimary() {
        var stored = pu.getSession();
        if (_sessionChoice === 'moved') {
            if (stored.token && stored.name === state.movedName) {
                location.reload();
            } else {
                _sessionSomeoneElse();
            }
            return;
        }
        _sessionChoice = null;
        state.staleConfirmed = true;
        if (!stored.token) { _showEmptyJoin(); return; }
        pu.showView('loading-view');
        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            send('reconnect', { session_token: stored.token, name: stored.name });
        } else {
            connect();
        }
    }

    function _sessionSomeoneElse() {
        if (_sessionChoice === 'moved') {
            state.sessionMoved = false;
            state.ignoreStoredSession = true;
            pu.updateConnectionIndicator('connecting');
        } else {
            pu.clearSession();
            dropIdentity();
        }
        _sessionChoice = null;
        _showEmptyJoin();
        connect();
    }

    function _showEmptyJoin() {
        hideJoinHint();
        if (els.nameInput) els.nameInput.value = '';
        if (els.joinBtn) {
            els.joinBtn.textContent = _t()('join.joinButton');
            els.joinBtn.disabled = true;
        }
        pu.showView('join-view');
        if (els.nameInput && typeof els.nameInput.focus === 'function') els.nameInput.focus();
    }

    function setupSessionChoice() {
        var primary = document.getElementById('session-primary-btn');
        var other = document.getElementById('session-other-btn');
        if (primary) primary.addEventListener('click', _sessionPrimary);
        if (other) other.addEventListener('click', _sessionSomeoneElse);
    }

    function showJoinRefusal(code, serverMessage) {
        endJoinPending();
        var t = _t();
        var text = joinRefusalText(code, serverMessage);

        if (JOIN_REFUSALS_CLEARING_NAME.indexOf(code) !== -1) {
            forgetIdentity();
            if (pu.hideReconnectingOverlay) pu.hideReconnectingOverlay();
            state.isReconnecting = false;
            state.reconnectAttempts = 0;
            pu.showView('join-view');
        }

        if (els.joinBtn) {
            els.joinBtn.disabled = false;
            els.joinBtn.textContent = code === 'NO_CONNECTION'
                ? t('connection.retryConnection')
                : t('join.joinButton');
        }
        if (els.nameInput) els.nameInput.style.borderColor = 'var(--color-error)';
        var vmsg = document.getElementById('name-validation-msg');
        if (vmsg) {
            vmsg.textContent = text;
            vmsg.classList.remove('hidden');
        }
        return text;
    }

    function setupJoinForm() {
        if (!els.nameInput || !els.joinBtn) return;

        els.nameInput.addEventListener('input', function () {
            var result = pu.validateName(this.value);
            els.joinBtn.disabled = !result.valid;
            var vmsg = document.getElementById('name-validation-msg');
            if (vmsg && vmsg.textContent) {
                vmsg.textContent = '';
                vmsg.classList.add('hidden');
            }
            this.style.borderColor = '';
        });

        els.joinBtn.addEventListener('click', handleJoinClick);

        els.nameInput.addEventListener('keydown', function (e) {
            if (e.key === 'Enter' && !els.joinBtn.disabled) {
                els.joinBtn.click();
            }
        });
    }

    function handleJoinClick() {
        var result = pu.validateName(els.nameInput.value);
        if (!result.valid) return;

        beginJoinPending();
        state.playerName = result.name;
        els.joinBtn.disabled = true;
        els.joinBtn.textContent = t('join.joining');

        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            var joinMsg = { name: result.name };
            var isAdminSelfJoin = new URLSearchParams(location.search).get('admin') === 'true';
            if (isAdminSelfJoin) {
                state.isAdmin = true;
            }
            if (state.isAdmin) {
                joinMsg.is_admin = true;
                var _at = QuizifyUtils.readAdminToken();
                if (_at) joinMsg.admin_token = _at;
            }
            send('join', joinMsg);
        } else {
            connect();
        }
    }

    function retryConnection() {
        if (state.reconnectTimer) {
            clearTimeout(state.reconnectTimer);
            state.reconnectTimer = null;
        }
        state.reconnectAttempts = 0;
        connect();
    }

    function setupRetryConnection() {
        var retryBtn = document.getElementById('retry-connection-btn');
        if (retryBtn) {
            retryBtn.addEventListener('click', retryConnection);
        }
        pu.setConnectionRetry(retryConnection);
    }

    var BACK_SHEETS = ['guest-reset-modal', 'powerup-target-modal', 'image-zoom-overlay',
        'invite-modal', 'qr-modal'];
    var MID_GAME_PHASES = {
        WAGER_ACTIVE: true, QUESTION_ACTIVE: true, PLAYING: true, ANSWER_REVEAL: true,
        PAUSED: true, LIGHTNING: true, LIGHTNING_RECAP: true, HOT_SEAT_AUCTION: true,
        HOT_SEAT: true, HOT_SEAT_REVEAL: true
    };
    var _backGuard = false;
    var _leaving = false;

    function armBackGuard() {
        if (_backGuard || _leaving || !state.playerName) return;
        if (!window.history || typeof window.history.pushState !== 'function') return;
        try {
            window.history.pushState({ quizifyBack: true }, '');
            _backGuard = true;
        } catch (e) { }
    }

    function _openBackSheet() {
        for (var i = 0; i < BACK_SHEETS.length; i++) {
            var el = document.getElementById(BACK_SHEETS[i]);
            if (el && !el.classList.contains('hidden')) return el;
        }
        return null;
    }

    function handleBack() {
        _backGuard = false;
        if (_openBackSheet()) {
            document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
            armBackGuard();
            return;
        }
        if (state.playerName && MID_GAME_PHASES[state.currentPhase]) {
            var asked = confirmThen(null, 'leave', function () {
                _leaving = true;
                window.history.back();
            }, armBackGuard);
            if (asked) return;
        }
        window.history.back();
    }

    function setupBackGesture() {
        window.addEventListener('popstate', handleBack);
    }

    function setupAdminControls() {
        var skipBtn = document.getElementById('skip-question-btn');
        if (skipBtn) {
            skipBtn.addEventListener('click', function () {
                pu.hostStep(skipBtn, send, 'admin_skip');
            });
        }

        var nextRoundAdminBtn = document.getElementById('next-round-admin-btn');
        if (nextRoundAdminBtn) {
            nextRoundAdminBtn.addEventListener('click', function () {
                pu.hostStep(nextRoundAdminBtn, send, 'next_round');
            });
        }

        var endGameBtn = document.getElementById('end-game-btn');
        if (endGameBtn) {
            endGameBtn.addEventListener('click', function () {
                confirmThen(endGameBtn, 'end', function () { send('end_game', {}); });
            });
        }

        var pauseBtn = document.getElementById('pause-game-btn');
        if (pauseBtn) {
            pauseBtn.addEventListener('click', function () { pu.hostStep(pauseBtn, send, 'pause_game'); });
        }
        var resumeBtn = document.getElementById('resume-game-btn');
        if (resumeBtn) {
            resumeBtn.addEventListener('click', function () { pu.hostStep(resumeBtn, send, 'resume_game'); });
        }

        var nextRoundBtn = document.getElementById('next-round-btn');
        if (nextRoundBtn) {
            nextRoundBtn.addEventListener('click', function () {
                pu.hostStep(nextRoundBtn, send, 'next_round');
            });
        }

        var endFromReveal = document.getElementById('end-game-from-reveal-btn');
        if (endFromReveal) {
            endFromReveal.addEventListener('click', function () {
                confirmThen(endFromReveal, 'end', function () { send('end_game', {}); });
            });
        }
    }

    function setupReactionBar() {
        var reactionBtns = document.querySelectorAll('.reaction-btn');
        reactionBtns.forEach(function (btn) {
            btn.addEventListener('click', function () {
                var emoji = btn.dataset.emoji;
                if (emoji) {
                    send('reaction', { emoji: emoji });
                    btn.classList.add('reaction-btn--sent');
                    setTimeout(function () {
                        btn.classList.remove('reaction-btn--sent');
                    }, 500);
                }
            });
        });
    }

    var _renderSoundToggle = null;
    var _renderA11yToggle = null;

    var PLAYER_LANG_KEY = 'quizify-player-lang';

    function _storedPlayerLang() {
        try {
            return window.localStorage.getItem(PLAYER_LANG_KEY) || null;
        } catch (e) {
            return null;
        }
    }

    function _markActiveLangChip() {
        var group = document.getElementById('player-lang-chips');
        if (!group || !window.QuizifyI18n) return;
        var active = QuizifyI18n.getLanguage();
        group.querySelectorAll('.chip').forEach(function (chip) {
            chip.classList.toggle('active', chip.dataset.value === active);
            chip.setAttribute('aria-pressed', chip.dataset.value === active ? 'true' : 'false');
        });
    }

    function _syncServerLanguage(msg) {
        if (!msg.language || !window.QuizifyI18n) return false;
        if (_storedPlayerLang()) return false;
        if (QuizifyI18n.getLanguage() === msg.language) return false;
        QuizifyI18n.setLanguage(msg.language).then(function () {
            QuizifyI18n.initPageTranslations();
            _markActiveLangChip();
            _flushToggleLabels();
            updatePageTitle(msg.phase, msg);
        });
        return true;
    }

    function setupLanguagePicker() {
        var group = document.getElementById('player-lang-chips');
        if (!group) return;
        if (group.textContent.indexOf('{{') !== -1) {
            group.classList.add('hidden');
            return;
        }
        if (!group.querySelector('.chip') || !window.QuizifyI18n) {
            group.classList.add('hidden');
            return;
        }

        group.addEventListener('click', function (e) {
            var chip = e.target.closest('.chip');
            if (!chip || !chip.dataset.value) return;
            var code = chip.dataset.value;
            if (code === QuizifyI18n.getLanguage()) return;
            try {
                window.localStorage.setItem(PLAYER_LANG_KEY, code);
            } catch (_e) { }
            QuizifyI18n.setLanguage(code).then(function () {
                QuizifyI18n.initPageTranslations();
                _markActiveLangChip();
                _flushToggleLabels();
            });
        });
    }

    function _flushToggleLabels() {
        if (_renderSoundToggle) _renderSoundToggle();
        if (_renderA11yToggle) _renderA11yToggle();
    }

    function setupSoundToggle() {
        var btn = document.getElementById('sound-toggle-btn');
        var snd = window.QuizifyPlayerSound;
        if (!btn) return;
        if (!snd) { btn.classList.add('hidden'); return; }

        function render() {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var muted = snd.isMuted();
            btn.textContent = muted ? '🔇' : '🔊';
            btn.classList.toggle('is-muted', muted);
            btn.setAttribute('aria-pressed', muted ? 'true' : 'false');
            var label = muted ? t('game.soundUnmute') : t('game.soundMute');
            btn.setAttribute('aria-label', label);
            btn.setAttribute('title', label);
        }

        btn.addEventListener('click', function () {
            snd.toggleMute();
            render();
        });
        _renderSoundToggle = render;
        render();
    }

    function setupA11yToggle() {
        var btn = document.getElementById('a11y-toggle-btn');
        var a11y = window.QuizifyA11y;
        if (!btn) return;
        if (!a11y) { btn.classList.add('hidden'); return; }

        function render() {
            var t = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
            var on = a11y.isEnabled();
            btn.classList.toggle('is-on', on);
            btn.setAttribute('aria-pressed', on ? 'true' : 'false');
            var label = on ? t('a11y.modeOff') : t('a11y.modeOn');
            btn.setAttribute('aria-label', label);
            btn.setAttribute('title', label);
        }

        btn.addEventListener('click', function () {
            a11y.toggle();
            render();
        });
        _renderA11yToggle = render;
        render();
    }

    function init() {
        pu.paintUiIcons();
        setupJoinForm();
        lobby.init(send);
        if (team) team.setupLobby(send);
        setupRetryConnection();
        setupAdminControls();
        setupBackGesture();
        setupReactionBar();
        setupSoundToggle();
        setupA11yToggle();
        setupLanguagePicker();
        setupResetAffordance();
        pu.setupCollapsibles();
        if (lightning) { lightning.setSend(send); lightning.init(); }

        var answerButtons = document.getElementById('answer-buttons');
        if (answerButtons) {
            answerButtons.addEventListener('click', function (e) {
                var btn = e.target.closest('.answer-btn');
                if (!btn || btn.disabled) return;
                var index = parseInt(btn.dataset.index, 10);
                if (isNaN(index)) return;
                if (hotSeat && hotSeat.handleSeatAnswerClick &&
                    hotSeat.handleSeatAnswerClick(index)) {
                    return;
                }
                game.handleAnswerClick(index, send);
            });
        }

        var powerupBtn = document.getElementById('powerup-btn');
        if (powerupBtn) {
            powerupBtn.addEventListener('click', function () {
                if (!myPowerUp || (game && game.isTimeUp && game.isTimeUp())) return;
                if (game && game.powerupNeedsTarget && game.powerupNeedsTarget(myPowerUp)) {
                    game.openTargetPicker(myPowerUp, function (targetName) {
                        send('use_powerup', { target_player_id: targetName });
                    }, _lastRoster);
                } else {
                    send('use_powerup', { target_player_id: null });
                }
            });
        }

        var urlParams = new URLSearchParams(location.search);
        var prefilledName = urlParams.get('name');
        if (prefilledName && els.nameInput) {
            els.nameInput.value = prefilledName;
            els.joinBtn.disabled = false;
            state.playerName = prefilledName;
        }

        if (urlParams.get('admin') === 'true') {
            state.isAdmin = true;
            if (window.QuizifyClientCore && window.QuizifyClientCore.useHostSeat) {
                window.QuizifyClientCore.useHostSeat();
            }
        }

        if (window.QuizifyI18n) {
            QuizifyI18n.init(_storedPlayerLang() || undefined).then(function () {
                QuizifyI18n.initPageTranslations();
                _markActiveLangChip();
                _flushPendingTitle();
                _flushToggleLabels();
            });
        }

        pu.showView('join-view');
        if (els.joinBtn) els.joinBtn.disabled = true;

        pu.updateConnectionIndicator('connecting');
        connect();

        _wsOpenTimeout = setTimeout(function () {
            if (!state.ws || state.ws.readyState !== WebSocket.OPEN) {
                var vmsgConn = document.getElementById('name-validation-msg');
                if (vmsgConn) {
                    vmsgConn.textContent = joinRefusalText('NO_CONNECTION', null);
                    vmsgConn.classList.remove('hidden');
                }
                if (els.joinBtn) {
                    var tRetry = (window.QuizifyI18n && window.QuizifyI18n.t) || function (k) { return k; };
                    els.joinBtn.disabled = false;
                    els.joinBtn.textContent = tRetry('connection.retryConnection');
                    els.joinBtn.addEventListener('click', function retryOnce() {
                        els.joinBtn.removeEventListener('click', retryOnce);
                        els.joinBtn.disabled = true;
                        els.joinBtn.textContent = tRetry('join.joinButton');
                        state.reconnectAttempts = 0;
                        connect();
                    }, { once: true });
                }
                pu.updateConnectionIndicator('disconnected');
            }
        }, 10000);

        if (prefilledName) {
            var autoJoinInterval = setInterval(function () {
                if (state.ws && state.ws.readyState === WebSocket.OPEN) {
                    clearInterval(autoJoinInterval);
                    els.joinBtn.click();
                }
            }, 200);
            setTimeout(function () { clearInterval(autoJoinInterval); }, 5000);
        }

        window.addEventListener('online', function () {
            if (document.visibilityState === 'hidden') return;
            var ws = state.ws;
            if (state.playerName && (!ws || ws.readyState === WebSocket.CLOSING ||
                    ws.readyState === WebSocket.CLOSED)) {
                retryConnection();
            }
        });

        document.addEventListener('visibilitychange', function () {
            if (document.visibilityState === 'visible') {
                var ws = state.ws;
                if (!ws || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
                    if (state.playerName) {
                        console.log('[Quizify] Page visible, WS dead \u2014 reconnecting.');
                        retryConnection();
                    }
                }
                if (state.currentPhase === 'QUESTION_ACTIVE' || state.currentPhase === 'PLAYING') {
                    _acquireWakeLock();
                }
            }
        });

        setupSessionChoice();

        var kickedRejoinBtn = document.getElementById('kicked-rejoin-btn');
        if (kickedRejoinBtn) {
            kickedRejoinBtn.addEventListener('click', function () {
                location.href = location.pathname;
            });
        }

        setTimeout(function () {
            var visible = [].slice.call(document.querySelectorAll('.view'))
                .find(function (e) { return e.offsetParent !== null; });
            var stuck = !visible || visible.id === 'loading-view';
            if (stuck) {
                pu.showView('join-view');
            }
        }, 4000);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    window.QuizifyPlayer = {
        init: init,
        send: send,
        forgetIdentity: forgetIdentity,
        confirmThen: confirmThen
    };

    window.quizifyIsIdleForReload = function () {
        switch (state.currentPhase) {
            case 'QUESTION_ACTIVE':
            case 'PLAYING':
            case 'LIGHTNING':
            case 'HOT_SEAT_AUCTION':
            case 'HOT_SEAT':
            case 'PAUSED':
                return false;
            default:
                return true;
        }
    };

})();
